import * as React from "react"
import * as TabsPrimitive from "@radix-ui/react-tabs"

import { cn } from "@/lib/utils"

const Tabs = TabsPrimitive.Root

const TabsList = React.forwardRef(({ className, ...props }, ref) => (
  <TabsPrimitive.List
    ref={ref}
    className={cn(
      "inline-flex h-9 items-center justify-center rounded-lg bg-muted p-1 text-muted-foreground",
      className
    )}
    {...props} />
))
TabsList.displayName = TabsPrimitive.List.displayName

const TabsTrigger = React.forwardRef(({ className, ...props }, ref) => (
  <TabsPrimitive.Trigger
    ref={ref}
    className={cn(
      "inline-flex items-center justify-center whitespace-nowrap rounded-md px-3 py-1 text-sm font-medium ring-offset-background transition-all focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 data-[state=active]:bg-background data-[state=active]:text-foreground data-[state=active]:shadow",
      className
    )}
    {...props} />
))
TabsTrigger.displayName = TabsPrimitive.Trigger.displayName

const TabsContent = React.forwardRef(({ className, ...props }, ref) => (
  <TabsPrimitive.Content
    ref={ref}
    className={cn(
      "mt-2 ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
      className
    )}
    {...props} />
))
TabsContent.displayName = TabsPrimitive.Content.displayName

export { Tabs, TabsList, TabsTrigger, TabsContent }

import { Input } from "@/components/ui/input";
import { Trash2, Box, Copy } from "lucide-react";
import { money } from "./foundationCalc";
import { hasFoundationCostSnapshot } from "./foundationCatalogIntegrity";
import { inventoryNumberInput } from "@/components/masterInventory/inventoryNormalization";

const amt = (v) => (hasFoundationCostSnapshot(v) ? money(v) : "Not saved");
const num2 = (v) => (Number.isFinite(v) ? v.toFixed(2) : "Not saved");

const Field = ({ label, ...props }) => (
  <label className="text-xs text-gray-500">
    {label}
    <Input {...props} />
  </label>
);

const Check = ({ label, checked, onChange }) => (
  <label className="flex items-center gap-1.5 text-xs font-medium text-gray-700">
    <input type="checkbox" checked={!!checked} onChange={(e) => onChange(e.target.checked)} />
    {label}
  </label>
);

const Picker = ({ label, value, onChange, options, placeholder }) => {
  const missing = value && !options.some((o) => o.id === value);
  return (
    <label className="text-xs text-gray-500">
      {label}
      <select
        value={value || ""}
        onChange={(e) => onChange(e.target.value)}
        className="flex h-9 w-full rounded-md border border-input bg-transparent px-2 text-sm shadow-sm"
      >
        <option value="">{placeholder}</option>
        {missing && (
          <option value={value} disabled>
            Catalog item unavailable ({value})
          </option>
        )}
        {options.map((o) => (
          <option key={o.id} value={o.id}>
            {o.material_name}
          </option>
        ))}
      </select>
    </label>
  );
};

export default function FoundationItemCard({ item, index, catalog, onChange, onRemove, onDuplicate, pricing }) {
  const set = (patch) => onChange(index, patch);
  const numSet = (key) => (e) => set({ [key]: parseFloat(e.target.value) || 0 });
  // Blank clears the override (null); a malformed draft is preserved verbatim so
  // the item validation reports it instead of a NaN leaking into saved costs.
  // Delegates to the boundary's catalog draft (CMP-A08) — identical contract,
  // plus whitespace-only drafts clear to null instead of minting Number(" ")=0.
  const nullSet = (key) => (e) => set({ [key]: inventoryNumberInput(e.target.value) });
  const isPillar = item.foundation_type === "pillar";
  // Versioned items price steel from the accepted reinforcement design — the
  // legacy implicit fields below do not apply to them and stay hidden.
  const legacyReinforcement = item.reinforcement_calculation_version == null || item.reinforcement_calculation_version === 1;
  const unavailable = pricing?.available === false;
  const concreteRow = (catalog.concrete || []).find((c) => c.id === item.selected_concrete_id);
  const overrideLabel = !concreteRow
    ? "Concrete cost override (unknown unit)"
    : concreteRow.material_type === "bagged_concrete"
      ? "Concrete $/bag override"
      : "Concrete $/CY override";

  return (
    <div className="bg-white rounded-sm border border-gray-200 border-l-4 border-l-amber-500 p-4">
      {unavailable && (
        <div className="mb-3 rounded-sm border border-amber-300 bg-amber-50 px-2 py-1" id={`foundation-${index}-pricing`}>
          <p className="text-[11px] font-semibold text-amber-800">Saved amounts (not current pricing)</p>
          <p className="text-[10px] text-amber-700">Saved quantities may not reflect the current design.</p>
          {(pricing.issues || []).map((i, k) => (
            <p key={k} className="text-[10px] text-amber-700">{i.message}</p>
          ))}
        </div>
      )}
      <div className="flex flex-wrap items-start justify-between gap-3 mb-3">
        <div className="flex items-center gap-2">
          <Box className="w-4 h-4 text-amber-500" aria-hidden="true" />
          <span className="text-[12px] font-bold text-gray-700">Foundation #{index + 1}</span>
          <select
            value={item.foundation_type || ""}
            onChange={(e) => set({ foundation_type: e.target.value })}
            className="h-8 rounded-md border border-input bg-transparent px-2 text-sm font-semibold"
          >
            {item.foundation_type !== "spread_foot" && item.foundation_type !== "pillar" && (
              <option value={item.foundation_type || ""} disabled>
                {item.foundation_type ? `Unsupported type: ${item.foundation_type}` : "Choose foundation type"}
              </option>
            )}
            <option value="spread_foot">Spread Footing</option>
            <option value="pillar">Pillar / Caisson</option>
          </select>
        </div>
        <div className="text-right">
          <div className="font-bold text-gray-900">{amt(item.item_total_cost)}</div>
          <div className="text-[11px] text-gray-400">
            {num2(item.concrete_volume_cy)} CY concrete
          </div>
        </div>
        <div className="flex items-center gap-2">
          {onDuplicate && (
            <button type="button" onClick={() => onDuplicate(index)} className="text-gray-400 hover:text-blue-600" title="Duplicate">
              <Copy className="w-4 h-4" aria-hidden="true" />
            </button>
          )}
          <button type="button"
            onClick={() => {
              if (!window.confirm(`Remove Foundation #${index + 1}?`)) return;
              onRemove(index);
            }}
            className="text-gray-400 hover:text-red-600"
            title="Delete"
          >
            <Trash2 className="w-4 h-4" aria-hidden="true" />
          </button>
        </div>
      </div>

      <Field
        label="Description"
        value={item.description || ""}
        onChange={(e) => set({ description: e.target.value })}
      />

      {/* Dimensions */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mt-3">
        <Field label="Quantity" type="number" value={item.quantity ?? 1} onChange={numSet("quantity")} />
        {isPillar ? (
          <Field label="Diameter (in)" type="number" value={item.diameter ?? 0} onChange={numSet("diameter")} />
        ) : (
          <>
            <Field label="Length (in)" type="number" value={item.length_inches ?? 0} onChange={numSet("length_inches")} />
            <Field label="Width (in)" type="number" value={item.width_inches ?? 0} onChange={numSet("width_inches")} />
          </>
        )}
        <Field label="Depth (in)" type="number" value={item.depth_inches ?? 0} onChange={numSet("depth_inches")} />
        <Field
          label="Grade offset (in)"
          type="number"
          value={item.grade_offset_inches ?? 0}
          onChange={numSet("grade_offset_inches")}
        />
        <Field
          label="Rotation (°)"
          type="number"
          value={item.rotation_degrees ?? 0}
          onChange={numSet("rotation_degrees")}
        />
      </div>

      {/* Concrete + excavation */}
      <div className="grid grid-cols-2 sm:grid-cols-3 gap-3 mt-3">
        <Picker
          label="Concrete"
          value={item.selected_concrete_id}
          onChange={(v) => set({ selected_concrete_id: v })}
          options={catalog.concrete}
          placeholder="Use project rate"
        />
        <label className="text-xs text-gray-500">
          Excavation method
          <select
            value={item.excavation_method || ""}
            onChange={(e) => set({ excavation_method: e.target.value })}
            className="flex h-9 w-full rounded-md border border-input bg-transparent px-2 text-sm shadow-sm"
          >
            <option value="">Project default</option>
            <option value="hand_dig">Hand dig</option>
            <option value="equipment_excavation">Equipment</option>
          </select>
        </label>
        <Picker
          label="Forming material"
          value={item.selected_forming_id}
          onChange={(v) => set({ selected_forming_id: v })}
          options={catalog.forming || []}
          placeholder="None"
        />
        <Field
          label={overrideLabel}
          type="number"
          step="any"
          min="0"
          value={item.custom_concrete_cost_per_cy ?? ""}
          onChange={nullSet("custom_concrete_cost_per_cy")}
          aria-label={overrideLabel}
          aria-invalid={pricing?.issues?.some((i) => i.field === "custom_concrete_cost_per_cy") || undefined}
          aria-describedby={pricing?.issues?.some((i) => i.field === "custom_concrete_cost_per_cy") ? `foundation-${index}-pricing` : undefined}
        />
        {item.custom_concrete_cost_per_cy !== null && item.custom_concrete_cost_per_cy !== undefined && (
          <button
            type="button"
            className="text-[10px] text-amber-700 hover:underline self-end"
            onClick={() => set({ custom_concrete_cost_per_cy: null })}
          >
            Clear override
          </button>
        )}
      </div>

      {/* Options */}
      <div className="flex flex-wrap gap-4 mt-3 pt-3 border-t border-gray-100">
        <Check label="Rebar" checked={item.include_rebar} onChange={(v) => set({ include_rebar: v })} />
        <Check label="Forming" checked={item.include_forming} onChange={(v) => set({ include_forming: v })} />
        <Check label="Finishing" checked={item.include_finishing} onChange={(v) => set({ include_finishing: v })} />
        <Check
          label="This is a new sign location"
          checked={item.is_new_sign_location}
          onChange={(v) => set({ is_new_sign_location: v })}
        />
      </div>

      {item.include_rebar && legacyReinforcement && (
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mt-3">
          {isPillar ? (
            <>
              <Field
                label="Rebar size"
                value={item.pillar_rebar_size || "#4"}
                onChange={(e) => set({ pillar_rebar_size: e.target.value })}
              />
              <Field
                label="Hoop dia (in)"
                type="number"
                value={item.pillar_rebar_hoop_diameter ?? 0}
                onChange={numSet("pillar_rebar_hoop_diameter")}
              />
              <Field
                label="Hoops (layers)"
                type="number"
                value={item.pillar_rebar_layers ?? 1}
                onChange={numSet("pillar_rebar_layers")}
              />
              <Field
                label="Vertical bars"
                type="number"
                value={item.pillar_vertical_rebar_count ?? 4}
                onChange={numSet("pillar_vertical_rebar_count")}
              />
            </>
          ) : (
            <>
              <Field
                label="Rebar size"
                value={item.rebar_size ?? ""}
                onChange={(e) => set({ rebar_size: e.target.value })}
              />
              <Field
                label="Spacing length (in)"
                type="number"
                value={item.rebar_spacing_length ?? 12}
                onChange={numSet("rebar_spacing_length")}
              />
              <Field
                label="Spacing width (in)"
                type="number"
                value={item.rebar_spacing_width ?? 12}
                onChange={numSet("rebar_spacing_width")}
              />
              <Field label="Layers" type="number" value={item.rebar_layers ?? 1} onChange={numSet("rebar_layers")} />
            </>
          )}
          <div className="col-span-2 sm:col-span-4 text-xs text-gray-500">
            {Number.isFinite(item.rebar_feet) ? item.rebar_feet.toFixed(1) : "Not saved"} ft ·{" "}
            {Number.isFinite(item.rebar_weight_lbs) ? item.rebar_weight_lbs.toFixed(0) : "Not saved"} lbs ·{" "}
            {amt(item.rebar_cost)}
          </div>
        </div>
      )}

      {!legacyReinforcement && (
        <p className="mt-3 rounded-sm border border-gray-200 bg-gray-50 px-3 py-2 text-[11px] text-gray-600">
          {item.reinforcement_calculation_version === 2 ? (
            <>Version 2 reinforcement uses the accepted design. Edit geometry and pricing through the controlled proposal below.{" "}
              <span className="font-semibold text-gray-800">Physical {num2(item.rebar_geometry_feet)} ft / priced {num2(item.rebar_feet)} ft - {amt(item.rebar_cost)}</span></>
          ) : (
            <>Unsupported reinforcement version. Reload before changing reinforcement pricing.</>
          )}
        </p>
      )}

      {/* Excavation summary */}
      <div className="mt-3 rounded-sm border border-amber-200 bg-amber-50 px-3 py-2">
        <div className="text-[10px] font-bold uppercase tracking-wide text-amber-700">Excavation</div>
        <div className="text-[11px] text-amber-900">
          Volume: ~{Number.isFinite(item.excavation_volume_cy) ? item.excavation_volume_cy.toFixed(2) : "Not saved"} CY · Cost: {amt(item.excavation_cost)}
        </div>
      </div>

      {/* Cost breakdown */}
      <div className="mt-3 rounded-sm border border-gray-200 bg-slate-50 p-2">
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 text-xs">
          {[
            ["Rebar", item.rebar_cost],
            ["Forming", item.forming_cost],
            ["Pouring", item.pouring_cost],
            ["Finishing", item.finishing_cost],
            ["Excavation", item.excavation_cost],
          ].map(([label, value]) => (
            <div key={label} className="px-1">
              <div className="text-gray-400">{label}</div>
              <div className="font-semibold text-gray-800">{amt(value)}</div>
            </div>
          ))}
        </div>
        <div className="mt-2 text-center text-[11px] italic text-amber-700">
          Concrete material &amp; truck costs are aggregated for the entire project.
        </div>
      </div>
    </div>
  );
}

import ReinforcementDraftGeometry from "./ReinforcementDraftGeometry";
import ReinforcementDraftMaterial from "./ReinforcementDraftMaterial";

const verLabel = (v) => {
  if (v === null || v === undefined || v === 1) return "Legacy";
  if (v === 2) return "Version 2";
  return "Unsupported";
};

export default function FoundationReinforcementProposalPanel({
  item, draft, catalog = [], preview, disabled = false, busy = false, error,
  acknowledgments = null, onAcknowledgmentsChange,
  onStart, onDraftChange, onPreview, onAccept, onDiscard,
}) {
  const label = verLabel(item?.reinforcement_calculation_version);
  const blocked = disabled || busy || label === "Unsupported";
  const ackProvided = acknowledgments !== null && acknowledgments !== undefined;
  const ack = acknowledgments !== null && typeof acknowledgments === "object" && !Array.isArray(acknowledgments) &&
    (Object.getPrototypeOf(acknowledgments) === Object.prototype || Object.getPrototypeOf(acknowledgments) === null)
    ? acknowledgments : null;
  const ackEligible = !ackProvided || Boolean(
    ack?.preliminary === true &&
    Array.isArray(preview?.warningCodes) &&
    preview.warningCodes.every(
      (code) => typeof code === "string" && code.trim().length > 0 &&
        (Array.isArray(ack?.warningCodes) ? ack.warningCodes : []).includes(code)
    )
  );
  const eligible = Boolean(
    typeof preview?.id === "string" && preview.id.trim().length > 0 &&
    preview?.canAccept === true && preview?.stale !== true &&
    !blocked && ackEligible
  );

  const guard = (fn) => (...a) => { if (!blocked) fn?.(...a); };
  const changeDraft = (patch) => { if (!blocked) onDraftChange?.({ ...draft, ...patch }); };

  return (
    <div className="rounded-sm border border-gray-200 bg-white p-3 min-w-0 max-w-full">
      <div className="flex items-center justify-between gap-2">
        <p className="text-[13px] font-semibold text-gray-800">Reinforcement proposal</p>
        <span className="rounded-sm bg-gray-100 px-1.5 py-0.5 text-[11px] text-gray-600">{label}</span>
      </div>
      <p className="mt-1 text-[11px] text-amber-700">Preliminary geometry and internal cost only. Not a structural design or engineering approval.</p>
      <p className="text-[11px] text-gray-500">Proposal edits do not change current prices until explicit acceptance; unknown supports/weights/units remain unknown.</p>
      {error && <div role="alert" className="mt-1 rounded-sm border border-red-200 bg-red-50 px-2 py-1 text-[12px] text-red-700">{String(error)}</div>}
      {label === "Unsupported" && (
        <div className="mt-1 rounded-sm border border-amber-300 bg-amber-50 px-2 py-1 text-[12px] text-amber-800">This reinforcement mode is unsupported; proposal edits are unavailable.</div>
      )}

      {!draft ? (
        <div className="mt-2">
          <p className="text-[12px] text-gray-500">No reinforcement draft yet. Start a controlled proposal to draft geometry and material.</p>
          <button type="button" disabled={blocked} onClick={guard(onStart)} className="mt-1 rounded-sm border border-amber-400 bg-amber-50 px-2 py-1 text-[12px] text-amber-800 disabled:text-gray-300">
            Start Proposal
          </button>
        </div>
      ) : (
        <fieldset disabled={blocked} className="mt-2 space-y-3 min-w-0">
          <ReinforcementDraftGeometry draft={draft} item={item} disabled={blocked} onChange={(design) => changeDraft({ design })} />
          <ReinforcementDraftMaterial draft={draft} catalog={catalog} disabled={blocked} onChange={(p) => { if (!blocked) onDraftChange?.({ ...draft, ...p }); }} />

          {preview && (
            <div className="break-words rounded-sm border border-gray-200 bg-gray-50 p-2 min-w-0 max-w-full">
              <p className="text-[12px] font-semibold text-gray-700">Preview</p>
              {preview.stale && <p className="text-[11px] text-amber-700">Preview is stale - refresh before accepting.</p>}
              {preview.rateSourceLabel && <p className="text-[11px] text-gray-500">{preview.rateSourceLabel}</p>}
              <div className="mt-1 space-y-0.5">
                {(preview.quantities || []).map((q, i) => (
                  <div key={i} className="flex flex-wrap justify-between gap-1 text-[12px] text-gray-600"><span>{q.label}</span><span>{q.before} - {q.after}</span></div>
                ))}
                {(preview.costs || []).map((c, i) => (
                  <div key={i} className="flex flex-wrap justify-between gap-1 text-[12px] text-gray-600"><span>{c.label}</span><span>{c.value} <span className="text-[10px] text-gray-400">({c.provenance})</span></span></div>
                ))}
              </div>
              {(preview.issues || []).map((i, k) => (
                <p key={k} className={`text-[11px] ${i.severity === "warning" ? "text-amber-700" : "text-red-700"}`}>{i.message}</p>
              ))}
            </div>
          )}

          {ackProvided && (() => {
            const ackPreliminary = ack?.preliminary === true;
            const ackCodes = Array.isArray(ack?.warningCodes) ? ack.warningCodes.filter((c) => typeof c === "string") : [];
            const issues = Array.isArray(preview?.issues) ? preview.issues : [];
            const uniqueCodes = [];
            (Array.isArray(preview?.warningCodes) ? preview.warningCodes : []).forEach((code) => {
              if (typeof code === "string" && code.trim().length > 0 && !uniqueCodes.includes(code)) uniqueCodes.push(code);
            });
            const ackDisabled = blocked || typeof onAcknowledgmentsChange !== "function";
            const emit = (preliminary, codes) => { if (!ackDisabled) onAcknowledgmentsChange?.({ preliminary, warningCodes: [...codes] }); };
            return (
              <div className="mt-1 space-y-1 text-[11px] text-gray-700">
                <label className="flex items-center gap-2">
                  <input
                    type="checkbox"
                    checked={ackPreliminary}
                    disabled={ackDisabled}
                    onChange={(event) => emit(event.target.checked, ackCodes)}
                    className="h-3.5 w-3.5 rounded border-gray-300 flex-shrink-0"
                  />
                  <span>I understand this is preliminary only, not engineering approval.</span>
                </label>
                {uniqueCodes.map((code) => {
                  const issue = issues.find((entry) => entry && entry.severity === "warning" && entry.code === code);
                  return (
                    <label key={code} className="flex items-center gap-2">
                      <input
                        type="checkbox"
                        checked={ackCodes.includes(code)}
                        disabled={ackDisabled}
                        onChange={(event) => emit(ackPreliminary, event.target.checked ? [...new Set([...ackCodes, code])] : ackCodes.filter((c) => c !== code))}
                        className="h-3.5 w-3.5 rounded border-gray-300 flex-shrink-0"
                      />
                      <span>{`Acknowledge warning: ${issue?.message || code}`}</span>
                    </label>
                  );
                })}
              </div>
            );
          })()}

          <div className="flex flex-wrap gap-2">
            <button type="button" disabled={blocked} onClick={guard(onPreview)} className="rounded-sm border border-gray-300 px-2 py-1 text-[12px] text-gray-700 disabled:text-gray-300">
              Refresh Preview
            </button>
            <button type="button" disabled={!eligible} onClick={() => eligible && onAccept?.(preview.id)} className="rounded-sm border border-amber-400 bg-amber-50 px-2 py-1 text-[12px] text-amber-800 disabled:text-gray-300">
              Accept Proposal
            </button>
            <button type="button" disabled={blocked} onClick={guard(onDiscard)} className="rounded-sm border border-red-200 px-2 py-1 text-[12px] text-red-600 disabled:text-gray-300">
              Discard
            </button>
          </div>
        </fieldset>
      )}
    </div>
  );
}

import { useRef, useState } from "react";
import { createFoundationReinforcementEditorSession } from "./foundationReinforcementEditorSession";
import { newCreationRequestKey } from "@/components/estimator/idempotentEntityCreate";

export function useFoundationReinforcementEditor({ getCurrent, commit }) {
  const [, setRevision] = useState(0);
  const callbacksRef = useRef({ getCurrent, commit });
  callbacksRef.current = { getCurrent, commit };
  const sessionRef = useRef(null);
  if (sessionRef.current === null) {
    sessionRef.current = createFoundationReinforcementEditorSession({
      getCurrent: () => callbacksRef.current.getCurrent(),
      commit: (updater) => callbacksRef.current.commit(updater),
      createId: () => newCreationRequestKey("foundation_reinforcement_proposal"),
      now: () => new Date().toISOString(),
      onChange: () => setRevision((r) => r + 1),
    });
  }
  return sessionRef.current;
}

import { useEffect, useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { Checkbox } from '@/components/ui/checkbox';
import { Trash2, Wrench } from 'lucide-react';
import { inventoryDraftInput } from "@/components/masterInventory/inventoryNormalization";
import { money, calcEquipmentPricing, equipmentCostTotal } from './foundationCalc';
import { hasFoundationCostSnapshot } from './foundationCatalogIntegrity';
import { setFoundationEquipmentCount } from './foundationEquipmentBindings';

const fin = (v) => Number.isFinite(v);
const intQty = (v) => fin(v) && Number.isInteger(v) && v >= 0;
// Blank-preserving draft coercion (same rule as the wall/pole panels): a blank
// draft stays blank, a numeric draft becomes a number, and a malformed draft
// is stored verbatim so the pricing diagnostics can flag it — never coerced.
// Blank-preserving project-entry draft, delegated to the boundary (CMP-A08).
const equipmentInputValue = inventoryDraftInput;

function OverrideChip({ label, value, onClear, moneyVal = false, invalid = false }) {
  if (value === undefined || value === null) return null;
  return (
    <span className={`inline-flex items-center gap-1 rounded-sm px-1.5 py-0.5 text-[10px] font-semibold ${invalid ? 'bg-red-100 text-red-800 border border-red-300' : 'bg-amber-100 text-amber-800'}`}>
      {label}: {moneyVal && typeof value === 'number' ? money(value) : String(value)}
      <button type="button" aria-label={`Clear ${label}`} onClick={onClear} className={invalid ? 'text-red-900 hover:underline' : 'text-amber-900 hover:underline'}>Clear</button>
    </span>
  );
}

function EquipmentCard({ entry, detail, index, inventory, onUpdate, onRemove, showMiscAttachments }) {
  const [err, setErr] = useState('');
  useEffect(() => { setErr(''); }, [entry]);
  const eq = detail.equipment; // may be undefined when missing
  const issues = detail.issues || [];
  const broken = issues.length > 0;
  const fieldIssue = (field) => issues.some((i) => i.field === field);
  const describedBy = (field) => (fieldIssue(field) ? `equipment-${index}-pricing` : undefined);
  const update = (next) => onUpdate(index, next);
  const setQty = (kind, id, quantity) => {
    try {
      const next = setFoundationEquipmentCount(entry, { kind, id, quantity });
      setErr('');
      update(next);
    } catch (e) { setErr(e.message || 'Quantity change rejected.'); }
  };
  const changeQty = (kind, id, raw) => {
    // Valid input reaches the shared draft immediately, including keyboard saves.
    if (raw === '') return;
    const n = Number(raw);
    if (!intQty(n)) { setErr('Quantity must be a whole number 0 or greater.'); return; }
    setQty(kind, id, n);
  };

  const eqOptions = inventory.filter(i => i.material_type === 'excavation_equipment');
  const compatibleAtts = inventory.filter(a =>
    a.material_type === 'attachment'
    && (showMiscAttachments || !a.is_miscellaneous_attachment)
    && (eq?.compatible_attachment_ids || []).includes(a.id));
  const activeParents = detail.attachmentRows.filter(r => r.quantity > 0 && r.inventory);
  const compatibleSubs = inventory.filter(s =>
    s.material_type === 'sub_attachment'
    && (showMiscAttachments || !s.is_miscellaneous_attachment)
    && activeParents.some(r => (eq?.compatible_attachment_ids || []).includes(r.id)
      && (r.inventory.compatible_sub_attachment_ids || []).includes(s.id)));
  const selectedAttIds = new Set(detail.attachmentMode === 'normalized'
    ? detail.attachmentRows.map(r => r.id)
    : detail.attachmentRows.filter(r => r.quantity !== 0).map(r => r.id));
  const selectedSubIds = new Set(detail.subAttachmentRows.filter(r => r.quantity !== 0).map(r => r.id));

  // legacy_ids: group occurrence counts per lead recipe; normalized keeps each raw row.
  const attView = detail.attachmentMode === 'legacy_ids'
    ? [...new Set(detail.attachmentRows.map(r => r.id))].map(id => ({
        id,
        quantity: detail.attachmentRows.filter(r => r.id === id).length,
        inventory: detail.attachmentRows.find(r => r.id === id)?.inventory,
        row: detail.attachmentRows.find(r => r.id === id),
        group: detail.attachmentRows.filter(r => r.id === id).length > 1,
      }))
    : detail.attachmentRows.map(row => ({ id: row.id, quantity: row.quantity, inventory: row.inventory, row, group: false }));
  const dupNormIds = detail.attachmentMode === 'normalized'
    ? new Set(detail.attachmentRows.map(r => r.id).filter((id) => detail.attachmentRows.filter(r => r.id === id).length > 1))
    : new Set();

  const periodOptions = ['day', 'week', 'month'].filter(p => eq ? fin(eq[`cost_per_${p}`]) : true);
  const savedPeriod = detail.rentalPeriod;
  if (savedPeriod && !periodOptions.includes(savedPeriod)) periodOptions.push(savedPeriod);
  const customQtyActive = entry.custom_qty !== undefined && entry.custom_qty !== null;

  const cardTotal = !broken
    ? money(detail.totalCost)
    : hasFoundationCostSnapshot(detail.totalCost) ? money(detail.totalCost) : 'Not saved';
  const lineAmt = (v) => (broken ? 'Unavailable' : money(v));

  const attRow = (a, key) => {
    const inv = a.inventory;
    const missing = !inv;
    const dupNorm = detail.attachmentMode === 'normalized' && dupNormIds.has(a.id);
    const disabledQty = dupNorm;
    return (
      <div key={key} className={`flex items-center justify-between gap-2 p-2 rounded-lg border text-xs ${a.quantity > 0 ? 'bg-amber-50 border-amber-300' : 'bg-slate-50 border-slate-200'}`}>
        <div className="min-w-0">
          <div className="font-medium text-slate-800 truncate">{inv?.material_name || `Catalog item unavailable (${a.id})`}</div>
          <div className="text-[10px] text-slate-500">
            {missing && <span className="text-amber-700 font-semibold">Unavailable — review. </span>}
            {dupNorm && <span className="text-amber-700 font-semibold">Duplicate rows — quantity editing disabled. </span>}
            {detail.attachmentMode === 'normalized' && a.row.sourceRecord?.qty === 0 && <span>qty 0 priced as 1. </span>}
            {a.group && <span>legacy duplicate ids ×{a.quantity} — catalog per-unit rate only. </span>}
            {!missing && inv && !a.group && hasFoundationCostSnapshot(a.row.cost) && <span>{money(a.row.cost)}</span>}
            {!missing && a.group && fin(inv?.cost_per_day) && <span>rate {money(inv.cost_per_day)}/day</span>}
          </div>
        </div>
        <div className="flex items-center gap-1 shrink-0">
          {dupNorm ? (
            <Button size="sm" variant="outline" className="h-6 text-[10px]" onClick={() => setQty('attachment', a.id, 0)}>Remove all duplicates</Button>
          ) : (
            <input
              type="number" min="0" disabled={disabledQty} aria-label={`Attachment qty ${inv?.material_name || a.id}`}
              className="h-7 w-14 rounded-md border border-input px-1 text-xs disabled:opacity-40"
              value={a.quantity}
              onChange={(e) => changeQty('attachment', a.id, e.target.value)}
            />
          )}
        </div>
      </div>
    );
  };

  const subRow = (s, key) => {
    const inv = s.inventory;
    const missing = !inv;
    const parentLinked = activeParents.some(r => (r.inventory.compatible_sub_attachment_ids || []).includes(s.id));
    return (
      <div key={key} className="flex items-center justify-between gap-2 p-2 rounded-lg border text-xs bg-slate-50 border-slate-200">
        <div className="min-w-0">
          <div className="font-medium text-slate-800 truncate">{inv?.material_name || `Catalog item unavailable (${s.id})`}</div>
          <div className="text-[10px] text-slate-500">
            {missing && <span className="text-amber-700 font-semibold">Unavailable — review. </span>}
            {!missing && !parentLinked && <span className="text-amber-700 font-semibold">No selected parent attachment links this item. </span>}
            {!missing && hasFoundationCostSnapshot(s.cost) && <span>{money(s.cost)}</span>}
          </div>
        </div>
        <input
          type="number" min="0" aria-label={`Sub attachment qty ${inv?.material_name || s.id}`}
          className="h-7 w-14 rounded-md border border-input px-1 text-xs"
          value={s.quantity}
          onChange={(e) => changeQty('sub_attachment', s.id, e.target.value)}
        />
      </div>
    );
  };

  return (
    <Card data-equipment-index={index} className="border border-indigo-200 shadow-sm overflow-hidden mb-4">
      <CardHeader className="py-3 px-4 bg-indigo-50/60 border-b border-indigo-100">
        <div className="flex items-start justify-between">
          <div className="flex flex-col gap-1.5">
            <div className="flex items-center gap-2 flex-wrap">
              <CardTitle className="text-sm font-semibold">{eq?.material_name || `Equipment ${index + 1}`}</CardTitle>
              {eq?.equipment_type && <Badge variant="outline" className="text-xs">{eq.equipment_type}</Badge>}
              {eq?.rental_company && <span className="text-xs text-slate-500">{eq.rental_company}</span>}
              {broken && <Badge variant="secondary" className="text-xs text-amber-800">Saved amounts (not current pricing)</Badge>}
              <Badge variant="secondary" className="text-xs">Total: {cardTotal}</Badge>
            </div>
            {eq?.notes && <p className="text-xs text-slate-500 leading-relaxed max-w-3xl">{eq.notes}</p>}
          </div>
          <div className="flex gap-1">
            <Button size="sm" variant="ghost" className="text-red-500" aria-label={`Remove equipment ${index + 1}`} onClick={onRemove}>
              <Trash2 className="w-3 h-3" aria-hidden="true" />
            </Button>
          </div>
        </div>
      </CardHeader>
      <CardContent className="px-4 pb-4 space-y-4">
        {broken && (
          <ul role="status" id={`equipment-${index}-pricing`} className="list-disc pl-5 text-[11px] text-amber-800">
            {issues.map((i, k) => <li key={k}>{i.message}</li>)}
          </ul>
        )}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
          <div>
            <Label className="text-xs">Equipment</Label>
            <Select
              value={entry.equipment_id || ''}
              onValueChange={(v) => update({ ...entry, equipment_id: v })}
            >
              <SelectTrigger className="h-8"><SelectValue placeholder="Select equipment…" /></SelectTrigger>
              <SelectContent>
                {entry.equipment_id && !eqOptions.some(o => o.id === entry.equipment_id) && (
                  <SelectItem value={entry.equipment_id} disabled>{`Catalog equipment unavailable (${entry.equipment_id})`}</SelectItem>
                )}
                {eqOptions.map(o => <SelectItem key={o.id} value={o.id}>{o.material_name}</SelectItem>)}
              </SelectContent>
            </Select>
            {eq && (eq.compatible_attachment_ids?.length || eq.compatible_sub_attachment_ids?.length) === 0 ? null : null}
            {broken && <p className="text-[10px] text-amber-700 mt-0.5">Reassigning preserves selected attachments/overrides — review compatibility.</p>}
          </div>
          <div>
            <Label className="text-xs">Rental Period</Label>
            <Select value={detail.rentalPeriod} onValueChange={(v) => update({ ...entry, rental_period: v })}>
              <SelectTrigger className="h-8"><SelectValue /></SelectTrigger>
              <SelectContent>
                {periodOptions.map(p => (
                  <SelectItem key={p} value={p}>
                    {p === 'day' ? `Daily (${fin(eq?.cost_per_day) ? money(eq.cost_per_day) : '?'}/day)`
                      : p === 'week' ? `Weekly (${fin(eq?.cost_per_week) ? money(eq.cost_per_week) : '?'}/wk)`
                      : p === 'month' ? `Monthly (${fin(eq?.cost_per_month) ? money(eq.cost_per_month) : '?'}/mo)`
                      : `Review (${savedPeriod})`}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div>
            <Label className="text-xs">Duration {customQtyActive && <span className="text-amber-700">(custom qty override active — editing duration does not clear it)</span>}</Label>
            <input
              type="number" aria-label="Rental duration" min={1} step="any"
              className="flex h-8 w-full rounded-md border border-input bg-transparent px-3 py-1 text-sm"
              value={entry.rental_duration ?? ""}
              placeholder="1"
              aria-invalid={fieldIssue("rental_duration") || undefined}
              aria-describedby={describedBy("rental_duration")}
              onChange={(e) => update({ ...entry, rental_duration: equipmentInputValue(e.target.value) })}
            />
          </div>
          <div className="flex items-end pb-1">
            <div className="flex items-center gap-2">
              <Checkbox
                checked={entry.include_delivery || false}
                onCheckedChange={(v) => update({ ...entry, include_delivery: v })}
                id={`delivery-${entry._id || index}`}
              />
              <Label htmlFor={`delivery-${entry._id || index}`} className="text-xs cursor-pointer">
                Include Delivery {fin(eq?.pickup_delivery_cost) ? `(${money(eq.pickup_delivery_cost)})` : ''}
              </Label>
            </div>
          </div>
        </div>
        <div className="flex flex-wrap gap-2">
          <OverrideChip label="Custom rate" value={entry.custom_rate} moneyVal invalid={fieldIssue('custom_rate')} onClear={() => update({ ...entry, custom_rate: null })} />
          <OverrideChip label="Custom qty" value={entry.custom_qty} invalid={fieldIssue('custom_qty')} onClear={() => update({ ...entry, custom_qty: null })} />
          <OverrideChip label={`Custom delivery${entry.include_delivery ? '' : ' (inactive — delivery excluded)'}`} value={entry.custom_delivery_charge} moneyVal invalid={fieldIssue('custom_delivery_charge')} onClear={() => update({ ...entry, custom_delivery_charge: null })} />
        </div>
        {err && <p role="alert" className="text-[11px] text-red-700">{err}</p>}
        <div className="grid grid-cols-3 gap-2 text-xs text-slate-600">
          <div>Base: <span className="font-semibold text-slate-900">{lineAmt(detail.baseCost)}</span></div>
          <div>Delivery: <span className="font-semibold text-slate-900">{lineAmt(detail.deliveryCost)}</span></div>
          <div>Total: <span className="font-semibold text-slate-900">{cardTotal}</span></div>
        </div>

        <div>
          <Label className="text-xs font-semibold text-slate-600 uppercase tracking-wide mb-2 block">
            <Wrench className="w-3 h-3 inline mr-1" aria-hidden="true" /> Attachments
          </Label>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
            {attView.filter(a => detail.attachmentMode === 'normalized' || a.quantity !== 0).map((a, k) => attRow(a, k))}
          </div>
          {compatibleAtts.filter(a => !selectedAttIds.has(a.id)).length > 0 && eq && (
            <div className="mt-2">
              <Select value="" onValueChange={(v) => v && setQty('attachment', v, 1)}>
                <SelectTrigger className="h-8"><SelectValue placeholder="Add attachment…" /></SelectTrigger>
                <SelectContent>
                  {compatibleAtts.filter(a => !selectedAttIds.has(a.id)).map(a => (
                    <SelectItem key={a.id} value={a.id}>{a.material_name}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}
          {attView.some(a => a.inventory && !(eq?.compatible_attachment_ids || []).includes(a.id)) && (
            <p className="text-[10px] text-amber-700 mt-1">Selected item incompatible with this parent — review.</p>
          )}
        </div>

        {detail.subAttachmentRows.filter(s => s.quantity !== 0).length > 0 && (
          <div>
            <Label className="text-xs font-semibold text-slate-600 uppercase tracking-wide mb-2 block">Sub-attachments</Label>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
              {detail.subAttachmentRows.filter(s => s.quantity !== 0).map((s, k) => subRow(s, k))}
            </div>
          </div>
        )}
        {compatibleSubs.filter(s => !selectedSubIds.has(s.id)).length > 0 && eq && (
          <div>
            <Select value="" onValueChange={(v) => v && setQty('sub_attachment', v, 1)}>
              <SelectTrigger className="h-8"><SelectValue placeholder="Add sub-attachment…" /></SelectTrigger>
              <SelectContent>
                {compatibleSubs.filter(s => !selectedSubIds.has(s.id)).map(s => (
                  <SelectItem key={s.id} value={s.id}>{s.material_name}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

export default function EquipmentTab({ foundationItems = [], inventory = [], selectedEquipmentList = [], onUpdate, markDirty }) {
  const [showAllEquipment, setShowAllEquipment] = useState(false);
  const [showMiscAttachments, setShowMiscAttachments] = useState(false);

  const pricingRows = calcEquipmentPricing(selectedEquipmentList, inventory);
  const total = equipmentCostTotal(pricingRows.map(r => r.pricedEntry));
  const incomplete = pricingRows.some(r => r.issues.length);

  const sortByOrder = (rows) => [...rows].sort((a, b) => (a.sort_order ?? 0) - (b.sort_order ?? 0));
  const excavation = sortByOrder(inventory.filter(i => i.material_type === 'excavation_equipment' && !i.is_non_excavation_equipment));
  const nonExcavation = sortByOrder(inventory.filter(i => i.material_type === 'excavation_equipment' && i.is_non_excavation_equipment));
  const types = new Set((foundationItems || []).map(f => f.foundation_type));
  const hasPillar = types.has('pillar');
  const hasSpread = types.has('spread_foot');
  const filteredExcavation = showAllEquipment || (!hasPillar && !hasSpread) ? excavation
    : excavation.filter(e => (hasPillar && e.is_pillar_excavation) || (hasSpread && e.is_spread_foot_excavation));
  const filteredNonExcavation = nonExcavation;

  const addEquipment = (eqId) => {
    if (!eqId || eqId === '_none') return;
    const eqItem = inventory.find(i => i.id === eqId);
    const newEntry = {
      _id: `eq_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      equipment_id: eqId,
      rental_period: 'day',
      rental_duration: 1,
      include_delivery: (eqItem?.pickup_delivery_cost || 0) > 0,
      attachment_counts: {},
      sub_attachment_counts: {},
    };
    onUpdate([...selectedEquipmentList, newEntry]);
    markDirty();
  };

  const removeEquipment = (idx) => {
    const eq = inventory.find(i => i.id === selectedEquipmentList[idx]?.equipment_id);
    if (!window.confirm(`Remove ${eq?.material_name || 'this equipment'}?`)) return;
    onUpdate(selectedEquipmentList.filter((_, i) => i !== idx));
    markDirty();
  };

  const updateEntry = (idx, updated) => {
    const arr = [...selectedEquipmentList];
    arr[idx] = updated;
    onUpdate(arr);
    markDirty();
  };

  const addSelect = (label, rows, placeholder) => (
    <div className="flex-1 min-w-[260px]">
      <Label className="text-xs font-semibold text-indigo-900 uppercase tracking-wide">{label}</Label>
      <Select value="" onValueChange={addEquipment}>
        <SelectTrigger className="h-9 mt-1"><SelectValue placeholder={placeholder} /></SelectTrigger>
        <SelectContent>
          {rows.length === 0 ? <SelectItem value="_none" disabled>No equipment available</SelectItem>
            : rows.map(eq => <SelectItem key={eq.id} value={eq.id}>{eq.material_name}</SelectItem>)}
        </SelectContent>
      </Select>
    </div>
  );

  return (
    <div className="space-y-4">
      <Card className="border-indigo-200 bg-indigo-50/50 shadow-sm mb-4">
        <CardContent className="py-3 px-4">
          <div className="flex items-center gap-6 mb-4 pb-4 border-b border-indigo-100">
            <div className="flex items-center gap-2">
              <Checkbox id="showAllEq" checked={showAllEquipment} onCheckedChange={setShowAllEquipment} />
              <Label htmlFor="showAllEq" className="text-sm cursor-pointer text-indigo-900 font-medium">Show all equipment</Label>
            </div>
            <div className="flex items-center gap-2">
              <Checkbox id="showMiscAtt" checked={showMiscAttachments} onCheckedChange={setShowMiscAttachments} />
              <Label htmlFor="showMiscAtt" className="text-sm cursor-pointer text-indigo-900 font-medium">Show Miscellaneous Attachments</Label>
            </div>
          </div>
          <div className="flex flex-wrap items-end gap-4">
            {addSelect('Add Excavation Equipment', filteredExcavation, 'Select excavation equipment to add…')}
            {addSelect('Add Non-Excavation Equipment', filteredNonExcavation, 'Select non-excavation equipment to add…')}
          </div>
        </CardContent>
      </Card>

      {incomplete && (
        <div role="alert" className="rounded border border-amber-300 bg-amber-50 px-3 py-2 text-[13px] text-amber-800 font-semibold">
          Pricing unavailable: selected materials or rental items need attention. Saved/known amounts only.
        </div>
      )}

      {selectedEquipmentList.length === 0 && (
        <Card className="border-dashed">
          <CardContent className="py-10 text-center text-slate-400">
            <Wrench className="w-8 h-8 mx-auto mb-2" aria-hidden="true" />
            <p className="font-medium">No equipment added yet</p>
            <p className="text-sm mt-1">Select equipment from the dropdown above.</p>
          </CardContent>
        </Card>
      )}

      {selectedEquipmentList.map((entry, idx) => (
        <EquipmentCard
          key={entry.component_id || entry._id || idx}
          entry={entry}
          detail={pricingRows[idx]}
          index={idx}
          inventory={inventory}
          onUpdate={updateEntry}
          onRemove={() => removeEquipment(idx)}
          showMiscAttachments={showMiscAttachments}
        />
      ))}

      {selectedEquipmentList.length > 0 && (
        <Card className="bg-amber-50 border-amber-200">
          <CardContent className="py-3 px-4 flex items-center justify-between">
            <span className="font-medium text-amber-800">Total Equipment Cost</span>
            <span className="text-lg font-bold text-amber-700">{incomplete ? 'Pricing unavailable' : money(total)}</span>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

import { useMemo } from "react";
import { money, calcSignageCabinetPricing } from "./foundationCalc";
import { landscapeSummary } from "./landscapeMaterials";
import { foundationAssemblyIssues } from "./foundationAssemblyModel";
import { foundationEngineEconomics, foundationHasEnginePricing } from "./foundationSellPricing";
import {
  resolveFoundationStickySummary,
  buildFoundationTakeoff,
  buildFoundationInputChecklist,
} from "./foundationTotalsSummary";

const amt = (v) => (Number.isFinite(v) ? money(v) : "Not saved");
const known = (v, d, u) => (Number.isFinite(v) ? `${v.toFixed(d)} ${u}` : "Not saved");

// O-096 (CMP-H05): `project` and `calc` are OPTIONAL — the panel consumes the
// original four props as before and lights up progressively when the page
// wires them (`project={project} calc={calc}` on the existing call site).
// Unwired, the panel still shows the cost column, the totals-quantity
// takeoff, and the held-amounts checklist — it never claims the issue
// channels were checked when they were not passed.
export default function FoundationTotals({ totals, pricingUnavailable = false, savedSectionTotal = null, sectionTotal = null, project = null, calc = null }) {
  const wallMortar = [totals.total_wall_cost, totals.total_brick_cost, totals.total_fill_cost].every(Number.isFinite)
    ? totals.total_wall_cost - totals.total_brick_cost - totals.total_fill_cost
    : null;
  // Saved-vs-current reconciliation (CMP-A10): `savedSectionTotal` is the
  // acknowledged record's persisted split-total sum (the same number the
  // linked estimate stored as live_total_snapshot at the last Builder save);
  // `sectionTotal` is the live recalculation including cabinets + landscape.
  // Advisory only — never blocks — and |delta| <= $0.005 never fires, the
  // same tolerance builderService.sameNumber / useSectionSync / ProductRow
  // already use for frozen-vs-live snapshot comparisons.
  const saved = Number.isFinite(savedSectionTotal) ? savedSectionTotal : null;
  const currentKnown = Number.isFinite(sectionTotal);
  const savedDelta = saved !== null && currentKnown ? sectionTotal - saved : null;
  const savedDiffers = savedDelta !== null && Math.abs(savedDelta) > 0.005;

  // Separate cost/sell/margin (CMP-H05). Sell precedence mirrors
  // customerPricing.sourceProjectEconomics' foundation branch: engine >
  // applied tier snapshot > override > markup %. Computed sells (engine +
  // markup) require the live cost — a held amount is never multiplied into a
  // fabricated customer price. The engine seam only runs when the record
  // actually carries config (foundationHasEnginePricing — the same cheap
  // detector CustomerPricingPanel uses).
  const summary = useMemo(
    () => resolveFoundationStickySummary({
      sectionTotal,
      savedSectionTotal,
      pricingUnavailable,
      project,
      engineResolver: project && foundationHasEnginePricing(project) ? foundationEngineEconomics : null,
    }),
    [sectionTotal, savedSectionTotal, pricingUnavailable, project]
  );

  // Itemized takeoff (CMP-H05): per-component quantity+amount rows. Falls
  // back to the totals quantity snapshot when `calc`/`project` aren't wired.
  const takeoff = useMemo(
    () => buildFoundationTakeoff({
      totals,
      items: calc?.items, itemPricing: calc?.itemPricing,
      walls: calc?.walls, wallPricing: calc?.wallPricing,
      poles: calc?.poles, polePricing: calc?.polePricing,
      wallCaps: calc?.wallCaps,
      equipment: calc?.equipment, equipmentPricing: calc?.equipmentPricing,
      delivery: calc?.delivery,
      cabinets: project?.signage_cabinets,
      cabinetRows: project ? calcSignageCabinetPricing(project.signage_cabinets) : null,
      landscapeLines: project ? landscapeSummary(project.landscape).lines : null,
      landscapePricing: calc?.landscapePricing,
    }),
    [totals, calc, project]
  );

  // Missing-input checklist (CMP-H05): the blocking channels are exactly the
  // lists the page's pricingBlocked gate reads (calc.inputIssues +
  // calc.catalogIssues); placement + construction warnings are advisory; the
  // held-amounts channel is derived from the partition totals so held
  // buckets surface even where upstream issue lists don't reach (wall caps).
  const checklist = useMemo(
    () => buildFoundationInputChecklist({
      totals,
      pricingUnavailable,
      calc,
      assemblyIssues: project ? foundationAssemblyIssues(project) : null,
    }),
    [totals, pricingUnavailable, calc, project]
  );

  const lines = [
    ["Concrete", totals.total_concrete_cost],
    ["Rebar", totals.total_rebar_cost],
    ["Excavation", totals.total_excavation_cost],
    ["Forming materials", totals.total_forming_materials_cost],
    ["Labor", totals.total_labor_cost],
    ["Poles", totals.total_pole_cost],
    ["Pole painting", totals.total_pole_painting_cost],
    ["Wall material", totals.total_brick_cost],
    ["Internal fill wall", totals.total_fill_cost],
    ["Wall mortar + labor", wallMortar],
    ["Wall caps", totals.total_wall_cap_cost],
    ["Equipment", totals.total_equipment_cost],
  ];

  const marginText = summary.margin.amount !== null
    ? `${money(summary.margin.amount)}${summary.margin.pct !== null ? ` · ${summary.margin.pct.toFixed(1)}%` : ""}`
    : "—";

  return (
    <div className="bg-white rounded-xl border border-gray-200 p-4 sticky top-4">
      <h2 className="font-semibold text-gray-900 mb-3">Section Total</h2>
      {pricingUnavailable && <p className="mb-3 rounded-sm border border-amber-300 bg-amber-50 px-2 py-1 text-[11px] font-semibold text-amber-800">Saved/known amounts only; current pricing is incomplete.</p>}

      {/* Separate cost / sell / margin (O-096). Sell side carries its
          precedence source so a tier/engine/override number never masquerades
          as the manual baseline; held sides render — instead of fabricating. */}
      <div className="grid grid-cols-3 gap-2 mb-3 text-center">
        <div className="bg-slate-50 rounded-lg py-2 px-1">
          <div className="text-[10px] uppercase tracking-wide text-gray-400">Cost (internal)</div>
          <div className="text-sm font-semibold text-gray-800">
            {summary.cost.value !== null ? money(summary.cost.value) : "Not saved"}
          </div>
          <div className="text-[10px] text-gray-400">
            {summary.cost.source === "saved" ? "acknowledged saved" : summary.cost.source === "live" ? "current" : ""}
          </div>
        </div>
        <div className="bg-slate-50 rounded-lg py-2 px-1">
          <div className="text-[10px] uppercase tracking-wide text-gray-400">Sell (customer)</div>
          <div className="text-sm font-semibold text-gray-800">
            {summary.sell.value !== null ? money(summary.sell.value) : "—"}
          </div>
          <div className="text-[10px] text-gray-400">
            {summary.sell.value !== null ? summary.sell.label : (summary.projectLinked ? "not recorded" : "")}
          </div>
        </div>
        <div className="bg-slate-50 rounded-lg py-2 px-1">
          <div className="text-[10px] uppercase tracking-wide text-gray-400">Margin</div>
          <div className={`text-sm font-semibold ${summary.margin.amount !== null && summary.margin.amount < 0 ? "text-red-700" : "text-gray-800"}`}>
            {marginText}
          </div>
          <div className="text-[10px] text-gray-400">
            {summary.margin.basis === "saved" ? "vs saved cost" : summary.margin.basis === "live" ? "sell − cost" : ""}
          </div>
        </div>
      </div>
      {summary.acknowledged?.differs && (
        <p role="status" className="mb-3 rounded-sm border border-blue-200 bg-blue-50 px-2 py-1 text-[11px] text-blue-800">
          Tier snapshot recorded internal cost {money(summary.acknowledged.cost)} → acknowledged margin {money(summary.acknowledged.marginAmount)}{summary.acknowledged.marginPct !== null ? ` (${summary.acknowledged.marginPct.toFixed(1)}%)` : ""}; the cost column above reflects the {summary.cost.source === "saved" ? "saved" : "current"} section total.
        </p>
      )}

      <div className="grid grid-cols-3 gap-2 mb-3 text-center">
        {[
          ["Concrete", known(totals.total_concrete_volume_cy, 2, "CY")],
          ["Excavation", known(totals.total_excavation_volume_cy, 2, "CY")],
          ["Labor", known(totals.total_labor_hours, 1, "hr")],
        ].map(([label, value]) => (
          <div key={label} className="bg-slate-50 rounded-lg py-2">
            <div className="text-[10px] uppercase tracking-wide text-gray-400">{label}</div>
            <div className="text-sm font-semibold text-gray-800">{value}</div>
          </div>
        ))}
      </div>

      <div className="space-y-1.5 text-sm border-t border-gray-100 pt-3">
        {lines.map(([label, value]) => (
          <div key={label} className="flex justify-between text-gray-600">
            <span>{label}</span>
            <span>{amt(value)}</span>
          </div>
        ))}
        <div className="flex justify-between font-bold text-gray-900 text-base border-t border-gray-200 pt-2">
          <span>Total</span>
          <span className="text-red-600">{pricingUnavailable ? <span className="text-amber-700">Pricing unavailable</span> : money(totals.grand_total)}</span>
        </div>
      </div>

      {/* Missing-input checklist (O-096): blocking channels auto-expand;
          advisory and held channels stay collapsed under the count. */}
      {checklist.complete ? (
        <p role="status" className="mt-3 rounded-sm border border-emerald-200 bg-emerald-50 px-2 py-1 text-[11px] font-semibold text-emerald-800">
          All inputs recorded — no missing or held amounts.
        </p>
      ) : checklist.totalCount > 0 ? (
        <details className="mt-3 rounded-sm border border-amber-300 bg-amber-50 px-2 py-1" open={checklist.blockingCount > 0}>
          <summary className="cursor-pointer select-none text-[11px] font-semibold text-amber-800">
            Missing inputs &amp; held amounts —{" "}
            {[
              checklist.blockingCount > 0 ? `${checklist.blockingCount} blocking` : null,
              checklist.advisoryCount > 0 ? `${checklist.advisoryCount} advisory` : null,
              checklist.heldCount > 0 ? `${checklist.heldCount} held` : null,
            ].filter(Boolean).join(", ")}
          </summary>
          <div className="mt-1 max-h-56 space-y-2 overflow-y-auto">
            {checklist.groups.map((g) => (
              <div key={g.key}>
                <div className={`text-[10px] uppercase tracking-wide ${g.severity === "blocking" ? "text-amber-700" : g.severity === "held" ? "text-gray-500" : "text-blue-700"}`}>
                  {g.label} ({g.items.length})
                </div>
                <ul className={`list-disc pl-4 text-[11px] ${g.severity === "advisory" ? "text-blue-900" : "text-amber-900"}`}>
                  {g.items.map((it) => <li key={it.key}>{it.message}</li>)}
                </ul>
              </div>
            ))}
          </div>
        </details>
      ) : !checklist.channelsKnown ? (
        <p className="mt-3 text-[11px] text-gray-400">No held amounts in the totals snapshot.</p>
      ) : null}

      {/* Itemized takeoff (O-096): per-component quantity + amount rows —
          collapsible so the sticky card stays compact. */}
      {takeoff.rowCount > 0 && (
        <details className="mt-3 rounded-sm border border-gray-200 bg-slate-50 px-2 py-1">
          <summary className="cursor-pointer select-none text-[11px] font-semibold text-gray-700">
            Itemized takeoff — {takeoff.rowCount} row{takeoff.rowCount === 1 ? "" : "s"}
          </summary>
          <div className="mt-1 max-h-64 space-y-2 overflow-y-auto">
            {takeoff.groups.map((g) => (
              <div key={g.key}>
                <div className="text-[10px] uppercase tracking-wide text-gray-400">{g.label}</div>
                <ul className="space-y-0.5">
                  {g.rows.map((r) => (
                    <li key={r.key} className="flex justify-between gap-2 text-[11px] text-gray-700">
                      <span className="min-w-0">
                        {r.label}
                        {r.held && <span className="ml-1 font-semibold text-amber-700">(saved)</span>}
                        {r.qty && <span className="block text-[10px] text-gray-400">{r.qty}</span>}
                      </span>
                      <span className="whitespace-nowrap">{r.amount !== null ? money(r.amount) : r.held ? "Not saved" : "—"}</span>
                    </li>
                  ))}
                </ul>
              </div>
            ))}
          </div>
        </details>
      )}

      {saved !== null && !currentKnown && (
        <div role="status" className="mt-3 rounded-sm border border-gray-300 bg-slate-50 px-2 py-1 text-[11px] text-gray-700">
          Saved section total {money(saved)} — current pricing unavailable.
        </div>
      )}
      {savedDiffers && (
        <div role="status" className="mt-3 rounded-sm border border-amber-300 bg-amber-50 px-2 py-1 text-[11px] font-semibold text-amber-800">
          Saved {money(saved)} — current {money(sectionTotal)} ({savedDelta > 0 ? "+" : "−"}{money(Math.abs(savedDelta))}) — recalculated from current inputs and catalog. Save to update the estimate.
        </div>
      )}
    </div>
  );
}

import { money } from "./foundationCalc";
import { hasFoundationCostSnapshot } from "./foundationCatalogIntegrity";

const amt = (v) => (hasFoundationCostSnapshot(v) ? money(v) : "Not saved");
const cy = (v) => (Number.isFinite(v) ? `${v.toFixed(2)} CY` : "Not saved");

export default function ConcreteDeliveryPanel({ project, delivery, onChange }) {
  const admixtures = project.project_concrete_admixtures || [];
  const unavailable = delivery?.pricingUnavailable === true;
  const mixes = delivery?.availableMixes || [];
  const admix = delivery?.availableAdmixes || [];
  const savedMixId = project.project_concrete_type;
  const mixMissing = savedMixId && !mixes.some((m) => m.id === savedMixId);
  const trucks = delivery?.trucksList || [];

  const toggleAdmix = (id) =>
    onChange({
      project_concrete_admixtures: admixtures.includes(id)
        ? admixtures.filter((a) => a !== id)
        : [...admixtures, id],
    });

  return (
    <div className="bg-white rounded-xl border border-gray-200 p-4">
      {unavailable && (
        <p className="mb-3 rounded-sm border border-amber-300 bg-amber-50 px-2 py-1 text-[11px] font-semibold text-amber-800">
          Saved amounts (not current pricing)
        </p>
      )}
      <div className="flex items-center justify-between mb-3">
        <h3 className="font-semibold text-gray-900 text-sm">Ready-Mix Concrete Order</h3>
        <div className="text-right">
          <div className="font-bold text-gray-900">{amt(delivery?.concreteTotal)}</div>
          <div className="text-[11px] text-gray-400">
            {cy(delivery?.roundedYards)} · {amt(delivery?.ratePerYard)}/CY
          </div>
        </div>
      </div>

      <label className="text-xs text-gray-500 block">
        Mix strength
        <select
          value={savedMixId || "4000_ae"}
          disabled={unavailable}
          onChange={(e) => onChange({ project_concrete_type: e.target.value })}
          className="flex h-9 w-full rounded-md border border-input bg-transparent px-2 text-sm shadow-sm disabled:opacity-60"
        >
          {mixMissing && <option value={savedMixId} disabled>Catalog mix unavailable ({savedMixId})</option>}
          {mixes.map((m) => (
            <option key={m.id} value={m.id}>
              {m.name} — {hasFoundationCostSnapshot(m.price) ? `${money(m.price)}/CY` : "price unavailable"}
            </option>
          ))}
        </select>
      </label>
      {!mixMissing && (
        <p className="text-[11px] text-gray-400 mt-1">
          {mixes.find((m) => m.id === (savedMixId || "4000_ae"))?.desc}
        </p>
      )}

      <div className="mt-3 pt-3 border-t border-gray-100">
        <div className="text-xs font-medium text-gray-700 mb-2">Admixtures</div>
        <div className="space-y-2">
          {admixtures
            .filter((id) => !admix.some((a) => a.id === id))
            .map((id) => (
              <div key={id} className="text-xs text-amber-700">Catalog admixture unavailable ({id})</div>
            ))}
          {admix.map((a) => (
            <label key={a.id} className={`flex gap-2 items-start text-xs ${unavailable ? "text-gray-400" : "text-gray-600"}`}>
              <input
                type="checkbox"
                className="mt-0.5"
                disabled={unavailable}
                checked={admixtures.includes(a.id)}
                onChange={() => toggleAdmix(a.id)}
              />
              <span>
                <span className="font-medium text-gray-800">{a.name}</span> — {hasFoundationCostSnapshot(a.price) ? `${money(a.price)}/CY` : "price unavailable"}
                <span className="block text-[11px] text-gray-400">{a.desc}</span>
              </span>
            </label>
          ))}
        </div>
      </div>

      {trucks.length > 0 && (
        <div className="mt-3 pt-3 border-t border-gray-100 space-y-1">
          {trucks.map((t, i) => (
            <div key={i} className="flex justify-between text-xs text-gray-600">
              <span>
                Truck {i + 1} — {cy(t.roundedYards)}
                {Number.isFinite(t.smallOrderFee) && t.smallOrderFee > 0 && ` (small load ${money(t.smallOrderFee)})`}
                {Number.isFinite(t.fuelFee) && t.fuelFee > 0 && ` + fuel ${money(t.fuelFee)}`}
              </span>
              <span className="font-medium text-gray-800">{amt(t.cost)}</span>
            </div>
          ))}
          {(delivery?.additionalStopsCost ?? 0) > 0 && (
            <div className="flex justify-between text-xs text-gray-600">
              <span>Additional sign locations / stops</span>
              <span className="font-medium text-gray-800">{amt(delivery.additionalStopsCost)}</span>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

import { useMemo } from "react";
import { money, calcSignageCabinetPricing } from "./foundationCalc";
import { hasFoundationCostSnapshot } from "./foundationCatalogIntegrity";
import { foundationWallBomRows } from "./wallCalculator";
import { landscapeSummary } from "./landscapeMaterials";

const num = (v) => (Number.isFinite(Number(v)) ? Number(v) : 0);
const qty = (n, unit) => `${num(n).toLocaleString(undefined, { maximumFractionDigits: 2 })} ${unit}`;
const EMPTY_ITEMS = [];
const EMPTY_POLES = [];
const EMPTY_WALLS = [];
const EMPTY_TOTALS = {};
const EMPTY_INVENTORY = [];

export default function FoundationBOM({
  items = EMPTY_ITEMS,
  poles = EMPTY_POLES,
  walls = EMPTY_WALLS,
  delivery,
  totals = EMPTY_TOTALS,
  inventory = EMPTY_INVENTORY,
  itemPricing = EMPTY_ITEMS,
  polePricing = EMPTY_ITEMS,
  wallPricing = EMPTY_ITEMS,
  cabinets = EMPTY_ITEMS,
  landscape,
  landscapePricing,
  pricingUnavailable = false,
}) {
  const cabinetRows = useMemo(() => calcSignageCabinetPricing(cabinets), [cabinets]);
  const rows = useMemo(() => {
    const out = [];
    // rawQty is the real numeric quantity; displayQty is the formatted label.
    // A row with a positive quantity OR a known cost stays listed (free rows
    // included) — the formatted string is never parsed for the drop test.
    const add = (material, displayQty, cost, rawQty = num(displayQty)) => {
      if (num(rawQty) <= 0 && !hasFoundationCostSnapshot(cost)) return;
      out.push({ material, quantity: displayQty, cost });
    };
    const nameOf = (id) => inventory.find((i) => i.id === id)?.material_name || "Material";
    const resolved = items.filter((_, i) => itemPricing[i]?.available !== false);
    const blocked = items.filter((_, i) => itemPricing[i]?.available === false);

    if (delivery?.pricingUnavailable) {
      out.push({
        material: "Concrete delivery/order (saved)",
        quantity: Number.isFinite(delivery.roundedYards) ? qty(delivery.roundedYards, "CY") : "Not saved",
        cost: hasFoundationCostSnapshot(delivery.concreteTotal) ? delivery.concreteTotal : "Not saved",
        saved: true,
      });
    } else if (num(delivery?.roundedYards) > 0) {
      add("Ready-mix concrete (delivered)", qty(delivery.roundedYards, "CY"), delivery.concreteTotal, delivery.roundedYards);
    }
    const bags = resolved.reduce((s, i) => s + num(i.concrete_bags), 0);
    const baggedCost = resolved.reduce((s, i) => s + num(i.concrete_cost), 0);
    if (bags > 0 || baggedCost > 0) add("Bagged concrete", qty(bags, "bags"), baggedCost, bags);

    const rebarFt = resolved.reduce((s, i) => s + num(i.rebar_feet), 0);
    const rebarLbs = resolved.reduce((s, i) => s + num(i.rebar_weight_lbs), 0);
    const rebarCost = resolved.reduce((s, i) => s + num(i.rebar_cost), 0);
    if (rebarFt > 0) {
      add(`Rebar (${qty(rebarLbs, "lbs")})`, qty(rebarFt, "LF"), rebarCost, rebarFt);
    }

    const formingQty = resolved.reduce((s, i) => s + num(i.forming_qty), 0);
    const formingCost = resolved.reduce((s, i) => s + num(i.forming_cost), 0);
    if (formingQty > 0) add("Forming material", qty(formingQty, "units"), formingCost, formingQty);

    blocked.forEach((i) => {
      const label = `Foundation ${i.component_id ?? "?"} (saved)`;
      {
        out.push({
          material: `${label} — concrete`,
          quantity: Number.isFinite(i.concrete_bags) ? qty(i.concrete_bags, "bags") : "Not saved",
          cost: hasFoundationCostSnapshot(i.concrete_cost) ? i.concrete_cost : "Not saved",
          saved: true,
        });
      }
      if (i.include_rebar) {
        out.push({
          material: `${label} — rebar`,
          quantity: Number.isFinite(i.rebar_feet) ? qty(i.rebar_feet, "LF") : "Not saved",
          cost: hasFoundationCostSnapshot(i.rebar_cost) ? i.rebar_cost : "Not saved",
          saved: true,
        });
      }
      if (i.include_forming) {
        out.push({
          material: `${label} — forming`,
          quantity: Number.isFinite(i.forming_qty) ? qty(i.forming_qty, "units") : "Not saved",
          cost: hasFoundationCostSnapshot(i.forming_cost) ? i.forming_cost : "Not saved",
          saved: true,
        });
      }
    });

    const poleGroups = {};
    poles.forEach((p, index) => {
      // Held poles list their acknowledged amounts separately, never dropped.
      if (polePricing[index]?.available === false) return;
      if (!p.pole_id) return;
      poleGroups[p.pole_id] = poleGroups[p.pole_id] || { ft: 0, cost: 0 };
      // Billed length is the distinct required-length snapshot (explicit total
      // stock length, or height + embedment); the legacy y_offset_inches
      // spelling of embedment is the fallback for pre-CMP-E02 rows.
      const billedInches = hasFoundationCostSnapshot(p.required_length_inches)
        ? p.required_length_inches
        : num(p.height_inches) + num(p.embedment_inches ?? p.y_offset_inches);
      poleGroups[p.pole_id].ft += billedInches / 12;
      poleGroups[p.pole_id].cost += num(p.pole_cost);
    });
    Object.entries(poleGroups).forEach(([id, g]) => add(nameOf(id), qty(g.ft, "LF"), g.cost, g.ft));

    const polePainting = poles.reduce((s, p, index) =>
      polePricing[index]?.available === false ? s : s + num(p.pole_painting_cost), 0);
    if (polePainting > 0) {
      add("Pole painting", "—", polePainting);
    }

    const savedPoleFt = (p) => {
      const req = Number(p.required_length_inches);
      if (Number.isFinite(req) && req > 0) return req / 12;
      const h = Number(p.height_inches), d = Number(p.embedment_inches ?? p.y_offset_inches);
      return Number.isFinite(h) && h > 0 && Number.isFinite(d) && d >= 0 ? (h + d) / 12 : null;
    };
    poles.forEach((p, index) => {
      if (polePricing[index]?.available !== false) return;
      const label = `Pole ${index + 1} (saved)`;
      const ft = savedPoleFt(p);
      out.push({
        material: `${label} — pole`,
        quantity: Number.isFinite(ft) ? qty(ft, "LF") : "Not saved",
        cost: hasFoundationCostSnapshot(p.pole_cost) ? p.pole_cost : "Not saved",
        saved: true,
      });
      if (p.include_pole_painting || hasFoundationCostSnapshot(p.pole_painting_cost)) {
        out.push({
          material: `${label} — painting`,
          quantity: "—",
          cost: hasFoundationCostSnapshot(p.pole_painting_cost) ? p.pole_painting_cost : "Not saved",
          saved: true,
        });
      }
    });

    out.push(...foundationWallBomRows(walls, inventory, wallPricing));

    (totals.wall_caps_by_material || []).forEach((g) => add(g.name || "Wall cap", qty(g.qty, "pcs"), g.cost, g.qty));

    // Signage cabinets — a priced row lists at the acknowledged unit cost ×
    // quantity; a held row lists its saved state like the blocked foundation
    // items above (never a silently repriced $0 line).
    cabinetRows.forEach((row, index) => {
      const cabinet = cabinets[index] || {};
      const label = cabinet.description || `Signage cabinet ${index + 1}`;
      if (row.available === false) {
        const recordedQty = Number(cabinet.quantity);
        out.push({
          material: `${label} (saved)`,
          quantity: Number.isFinite(recordedQty) ? qty(recordedQty, "pcs") : "Not saved",
          cost: "Not saved",
          saved: true,
        });
        return;
      }
      const quantity = cabinet.quantity === undefined || cabinet.quantity === null || cabinet.quantity === ""
        ? 1
        : Number(cabinet.quantity);
      add(label, qty(quantity, "pcs"), row.cost, quantity);
    });

    // Landscape / site materials — a fully priced grid lists one row per
    // material; a held grid keeps the acknowledged section total as a single
    // saved row, exactly like the saved concrete-delivery row above.
    if (landscapePricing && landscapePricing.available === false) {
      out.push({
        material: "Site landscaping (saved)",
        quantity: "—",
        cost: hasFoundationCostSnapshot(totals.total_landscape_cost) ? totals.total_landscape_cost : "Not saved",
        saved: true,
      });
    } else {
      landscapeSummary(landscape).lines.forEach((line) => {
        if (line.cost === null || line.sqft === null) {
          out.push({
            material: `Site — ${line.label} (saved)`,
            quantity: Number.isFinite(line.sqft) ? qty(line.sqft, "sq ft") : qty(line.cells, "cells"),
            cost: "Not saved",
            saved: true,
          });
          return;
        }
        add(`Site — ${line.label}`, qty(line.sqft, "sq ft"), line.cost, line.sqft);
      });
    }

    return out;
  }, [items, poles, walls, delivery, totals, inventory, itemPricing, polePricing, wallPricing, cabinets, cabinetRows, landscape, landscapePricing]);

  const materialTotal = rows.every(r => hasFoundationCostSnapshot(r.cost)) ? rows.reduce((sum, row) => sum + row.cost, 0) : null;

  return (
    <div className="bg-white rounded-xl border border-gray-200 p-4">
      <h3 className="font-semibold text-gray-900 mb-3">Bill of Materials</h3>
      {pricingUnavailable && (
        <div className="mb-3 rounded-sm border border-amber-300 bg-amber-50 px-2 py-1">
          <p className="text-[11px] font-semibold text-amber-800">Pricing unavailable — saved quantities may be outdated.</p>
          {itemPricing.filter(p => p && p.available === false)
            .concat(polePricing.filter(p => p && p.available === false))
            .concat(cabinetRows.filter(p => p && p.available === false))
            .concat(landscapePricing && landscapePricing.available === false ? [landscapePricing] : [])
            .flatMap((p, k) =>
            (p.issues || []).map((i, j) => <p key={`${k}-${j}`} className="text-[10px] text-amber-700">{i.message}</p>)
          )}
        </div>
      )}
      {rows.length === 0 ? (
        <p className="text-sm text-gray-500">No materials yet — add a foundation to build the list.</p>
      ) : (
        <>
          <table className="w-full text-sm">
            <thead>
              <tr className="text-left text-xs text-gray-500 border-b border-gray-200">
                <th className="py-1.5">Material</th>
                <th className="py-1.5">Quantity</th>
                <th className="py-1.5 text-right">Cost</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((r, i) => (
                <tr key={i} className="border-b border-gray-100 last:border-0">
                  <td className="py-1.5 pr-3 text-gray-800">{r.material}</td>
                  <td className="py-1.5 pr-3 whitespace-nowrap text-gray-600">{r.quantity}</td>
                  <td className="py-1.5 pl-3 whitespace-nowrap text-right text-gray-900">{hasFoundationCostSnapshot(r.cost) ? money(r.cost) : "Not saved"}</td>
                </tr>
              ))}
            </tbody>
          </table>
          <div className="flex justify-between pt-3 mt-1 border-t border-gray-200 font-bold text-gray-900">
            <span>Listed cost subtotal</span>
            <span>{pricingUnavailable ? <span className="text-amber-700">Pricing unavailable</span> : hasFoundationCostSnapshot(materialTotal) ? money(materialTotal) : "Not saved"}</span>
          </div>
        </>
      )}
    </div>
  );
}

import React from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Trash2, Plus, PenLine } from "lucide-react";
import { money } from "./foundationCalc";
import { hasFoundationCostSnapshot } from "./foundationCatalogIntegrity";
import { foundationWallPricingIssues } from "./wallCalculator";
import { inventoryDraftInput } from "@/components/masterInventory/inventoryNormalization";
import WallShapeEditor from "./WallShapeEditor";

// Blank-preserving project-entry draft, delegated to the boundary (CMP-A08).
const heightInput = inventoryDraftInput;

function WallRow({ wall, index, options, pricing, onChange, onRemove }) {
  const c = wall.calculatedCosts || {};
  const set = (changes) => onChange(index, changes);
  // Settings-aware issues arrive from calcProject; the local re-derive covers
  // consumers that cannot supply them (no settings visibility).
  const pricingIssues = pricing?.issues ?? foundationWallPricingIssues(wall, options, index);
  const pricingUnavailable = pricing?.available === false || pricingIssues.length > 0;
  const amt = (v) => (hasFoundationCostSnapshot(v) ? money(v) : "Not saved");
  const [showEditor, setShowEditor] = React.useState(false);
  const fieldIssue = (field) => pricingIssues.some((i) => i.field === field);
  const describedBy = (field) => (fieldIssue(field) ? `wall-${index}-pricing` : undefined);

  return (
    <div className="bg-white rounded-xl border border-gray-200 p-3 space-y-3">
      <div className="flex items-center justify-between gap-2">
        <Input
          className="min-w-0 max-w-[220px]"
          value={wall.name || ""}
          placeholder={`Wall ${index + 1}`}
          onChange={(e) => set({ name: e.target.value })}
        />
        <div className="flex shrink-0 items-center gap-3">
          <span className="whitespace-nowrap font-bold text-gray-900">{amt(c.totalCost)}</span>
          <Button variant="ghost" size="icon" onClick={() => onRemove(index)}>
            <Trash2 className="w-4 h-4 text-red-500" aria-hidden="true" />
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
        <label className="text-xs text-gray-500">
          Height (in)
          <Input
            type="number"
            step="any"
            value={wall.heightInches ?? ""}
            onChange={(e) => set({ heightInches: heightInput(e.target.value) })}
            aria-label="Wall height (in)"
            aria-invalid={fieldIssue("heightInches") || undefined}
            aria-describedby={describedBy("heightInches")}
          />
        </label>
        <label className="text-xs text-gray-500">
          Mortar gap (in)
          <Input
            type="number"
            step="0.125"
            min="0"
            value={wall.mortarGapInches ?? 0.375}
            placeholder="0.375"
            onChange={(e) => set({ mortarGapInches: heightInput(e.target.value) })}
            aria-label="Wall mortar gap (in)"
            aria-invalid={fieldIssue("mortarGapInches") || undefined}
            aria-describedby={describedBy("mortarGapInches")}
          />
        </label>
        <label className="text-xs text-gray-500 md:col-span-2">
          Wall material
          <select
            className="w-full h-9 rounded-md border border-input bg-transparent px-2 text-sm"
            value={wall.materialId || ""}
            aria-label="Wall material"
            aria-invalid={fieldIssue("materialId") || undefined}
            aria-describedby={describedBy("materialId")}
            onChange={(e) => set({ materialId: e.target.value })}
          >
            <option value="">Select material…</option>
            {wall.materialId && !options.some((o) => o.id === wall.materialId) && (
              <option value={wall.materialId} disabled>{`Catalog material unavailable (${wall.materialId})`}</option>
            )}
            {options.map((o) => (
              <option key={o.id} value={o.id}>
                {o.material_name}
              </option>
            ))}
          </select>
          {wall.materialId && !options.some((o) => o.id === wall.materialId) && (
            <span className="block text-[10px] text-amber-700 mt-1">Catalog material unavailable; current pricing needs review.</span>
          )}
        </label>
      </div>

      <div className="rounded-lg bg-slate-50 p-2 space-y-2">
        <label className="flex items-center gap-2 text-xs font-medium text-gray-700">
          <input
            type="checkbox"
            checked={!!wall.includeInternalWall}
            onChange={(e) => set({ includeInternalWall: e.target.checked })}
          />
          Internal fill wall
        </label>
        {wall.includeInternalWall && (
          <div className="grid grid-cols-2 md:grid-cols-3 gap-2">
            <label className="text-xs text-gray-500 md:col-span-2">
              Fill material
              <select
                className="w-full h-9 rounded-md border border-input bg-transparent px-2 text-sm"
                value={wall.internalMaterialId || ""}
                aria-label="Internal wall material"
                aria-invalid={fieldIssue("internalMaterialId") || undefined}
                aria-describedby={describedBy("internalMaterialId")}
                onChange={(e) => set({ internalMaterialId: e.target.value })}
              >
                <option value="">Select material…</option>
                {wall.internalMaterialId && !options.some((o) => o.id === wall.internalMaterialId) && (
                  <option value={wall.internalMaterialId} disabled>{`Catalog material unavailable (${wall.internalMaterialId})`}</option>
                )}
                {options.map((o) => (
                  <option key={o.id} value={o.id}>
                    {o.material_name}
                  </option>
                ))}
              </select>
              {wall.internalMaterialId && !options.some((o) => o.id === wall.internalMaterialId) && (
                <span className="block text-[10px] text-amber-700 mt-1">Catalog material unavailable; current pricing needs review.</span>
              )}
            </label>
            <label className="text-xs text-gray-500">
              Fill height (in)
              <Input
                type="number"
                step="any"
                value={wall.internalWallHeightInches ?? wall.heightInches ?? ""}
                onChange={(e) => set({ internalWallHeightInches: heightInput(e.target.value) })}
                aria-label="Internal wall height (in)"
                aria-invalid={fieldIssue("internalWallHeightInches") || undefined}
                aria-describedby={describedBy("internalWallHeightInches")}
              />
            </label>
            <label className="text-xs text-gray-500">
              Fill mortar gap (in)
              <Input
                type="number"
                step="0.125"
                min="0"
                value={wall.internalMortarGapInches ?? 0.375}
                placeholder="0.375"
                onChange={(e) => set({ internalMortarGapInches: heightInput(e.target.value) })}
                aria-label="Internal wall mortar gap (in)"
                aria-invalid={fieldIssue("internalMortarGapInches") || undefined}
                aria-describedby={describedBy("internalMortarGapInches")}
              />
            </label>
          </div>
        )}
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-2 text-xs text-gray-600">
        {/* CMP-D03: the snapshot carries its quantity basis — poured concrete
            reads placed volume in CY (never "Units"), unit masonry keeps the
            unit count. Held rows keep whatever basis the acknowledged
            snapshot recorded. */}
        {c.materialQuantityUnit === "cy" ? (
          <div>CY: <span className="font-semibold text-gray-900">{hasFoundationCostSnapshot(c.totalBricks) ? c.totalBricks.toFixed(2) : "Not saved"}</span></div>
        ) : (
          <div>Units: <span className="font-semibold text-gray-900">{hasFoundationCostSnapshot(c.totalBricks) ? Math.round(c.totalBricks) : "Not saved"}</span></div>
        )}
        <div>Courses: <span className="font-semibold text-gray-900">{hasFoundationCostSnapshot(c.numCourses) ? Math.ceil(c.numCourses) : "Not saved"}</span></div>
        <div>Material: <span className="font-semibold text-gray-900">{amt(c.materialCost)}</span></div>
        <div>Mortar: <span className="font-semibold text-gray-900">{amt(c.mortarCost)}</span></div>
        <div>Labor: <span className="font-semibold text-gray-900">{amt(c.laborCost)}</span></div>
        <div>Labor hrs: <span className="font-semibold text-gray-900">{hasFoundationCostSnapshot(c.laborHours) ? c.laborHours.toFixed(1) : "Not saved"}</span></div>
        <div>Linear in: <span className="font-semibold text-gray-900">{hasFoundationCostSnapshot(c.totalLinearInches) ? Math.round(c.totalLinearInches) : "Not saved"}</span></div>
        {pricingUnavailable && <div className="col-span-full text-[10px] font-semibold text-amber-700">Saved amounts (not current pricing)</div>}
        {pricingIssues.length > 0 && (
          <div role="status" className="col-span-full text-[10px] text-amber-700 space-y-0.5" id={`wall-${index}-pricing`}>
            {pricingIssues.map((issue) => <p key={`${issue.field}-${issue.code}`}>{issue.message}</p>)}
          </div>
        )}
      </div>

      <div className="flex items-center gap-2">
        <Button variant="outline" size="sm" onClick={() => setShowEditor((v) => !v)}
          aria-expanded={showEditor}
          aria-invalid={fieldIssue("shape") || undefined}
          aria-describedby={describedBy("shape")}>
          <PenLine className="w-4 h-4" aria-hidden="true" /> {showEditor ? "Hide outline" : "Wall outline"}
        </Button>
        {fieldIssue("shape") ? (
          <span className="text-xs text-amber-600">
            Outline geometry needs repair before repricing - see diagnostics above.
          </span>
        ) : !wall.shape?.segments?.length ? (
          <span className="text-xs text-amber-600">
            No outline yet - draw the wall footprint before estimating quantities.
          </span>
        ) : null}
      </div>

      {showEditor && (
        <WallShapeEditor shape={wall.shape} onChange={(shape) => set({ shape })} />
      )}
    </div>
  );
}

export default function FoundationWallsPanel({ walls = [], options = [], onChange, wallPricing = [] }) {
  const patchWall = (index, changes) =>
    onChange(walls.map((w, i) => (i === index ? { ...w, ...changes } : w)));

  const removeWall = (index) => {
    const name = walls[index]?.name || `Wall ${index + 1}`;
    if (!window.confirm(`Remove ${name}? Wall caps attached to it are retained for review.`)) return;
    onChange(walls.filter((_, i) => i !== index));
  };

  const addWall = () =>
    onChange([
      ...walls,
      { name: `Wall ${walls.length + 1}`, heightInches: 24, mortarGapInches: 0.375, offsetFraction: 0.5 },
    ]);

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <h2 className="font-semibold text-gray-900">Masonry Walls</h2>
        <Button variant="outline" size="sm" onClick={addWall}>
          <Plus className="w-4 h-4" aria-hidden="true" /> Wall
        </Button>
      </div>

      {walls.length === 0 ? (
        <div className="text-center py-8 bg-white rounded-xl border border-dashed border-gray-300 text-gray-500 text-sm">
          No walls on this section.
        </div>
      ) : (
        walls.map((wall, index) => (
          <WallRow
            key={wall.component_id || index}
            wall={wall}
            index={index}
            options={options}
            pricing={wallPricing[index]}
            onChange={patchWall}
            onRemove={removeWall}
          />
        ))
      )}
    </div>
  );
}

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Trash2, Plus } from "lucide-react";
import { money } from "./foundationCalc";
import { hasFoundationCostSnapshot } from "./foundationCatalogIntegrity";
import { foundationWallCapCatalogIssues, wallCapInputNumber, wallCapCutLengthValue } from "./wallCapCalculator";

export default function FoundationWallCapsPanel({ caps = [], walls = [], options = [], onChange }) {
  const patchCap = (index, changes) =>
    onChange(caps.map((c, i) => (i === index ? { ...c, ...changes } : c)));

  const removeCap = (index) => {
    if (!window.confirm(`Remove cap ${index + 1}?`)) return;
    onChange(caps.filter((_, i) => i !== index));
  };

  const addCap = () => {
    const inv = options[0];
    const stockLength = wallCapInputNumber(inv?.cap_stock_length_inches);
    onChange([
      ...caps,
      {
        id: `cap_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
        cap_inventory_id: inv?.id || "",
        wall_component_id: walls[0]?.component_id || "",
        wall_index: walls.length ? 0 : undefined,
        segment_component_id: walls[0]?.shape?.segments?.[0]?.component_id || "",
        segment_index: walls[0]?.shape?.segments?.length ? 0 : undefined,
        position_along_segment_inches: 0,
        length_inches: stockLength !== null && stockLength > 0 ? stockLength : "",
        rotation_offset_degrees: 0,
        lateral_offset_inches: 0,
      },
    ]);
  };

  const capIssues = foundationWallCapCatalogIssues(caps, options);
  const unavailableCaps = new Set(capIssues.filter(issue => issue.code !== "wall_cap_cost_total_invalid").map(issue => issue.index));
  const geometryIssues = (index) => capIssues.filter(issue => issue.index === index && ["length_inches", "cap_stock_length_inches"].includes(issue.field));

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="font-semibold text-gray-900">Wall Caps</h2>
          <p className="text-xs text-gray-500">Full stock price is charged per cut piece.</p>
        </div>
        <Button variant="outline" size="sm" onClick={addCap} disabled={options.length === 0}>
          <Plus className="w-4 h-4" aria-hidden="true" /> Cap
        </Button>
      </div>

      {options.length === 0 && (
        <div className="text-[11px] text-amber-800 bg-amber-50 border border-amber-200 rounded px-2 py-1.5">
          Wall cap catalog unavailable — existing rows remain editable; new caps cannot be added.
        </div>
      )}
      {caps.length === 0 ? (
        <div className="text-center py-6 bg-white rounded-xl border border-dashed border-gray-300 text-gray-500 text-sm">
          No caps on this section.
        </div>
      ) : (
        caps.map((cap, index) => (
          <div key={cap.component_id || cap.id || index} className="bg-white rounded-xl border border-gray-200 p-3">
            <div className="grid grid-cols-1 md:grid-cols-4 gap-2 items-end">
              <label className="text-xs text-gray-500 md:col-span-2">
                Cap material
                <select
                  className="w-full h-9 rounded-md border border-input bg-transparent px-2 text-sm"
                  value={cap.cap_inventory_id || ""}
                  aria-label="Cap material"
                  onChange={(e) => {
                    patchCap(index, {
                      cap_inventory_id: e.target.value,
                    });
                  }}
                >
                  <option value="">Select cap…</option>
                  {cap.cap_inventory_id && !options.some((o) => o.id === cap.cap_inventory_id) && (
                    <option value={cap.cap_inventory_id} disabled>{`Catalog cap unavailable (${cap.cap_inventory_id})`}</option>
                  )}
                  {options.map((o) => (
                    <option key={o.id} value={o.id}>
                      {o.material_name}
                    </option>
                  ))}
                </select>
                {cap.cap_inventory_id && !options.some((o) => o.id === cap.cap_inventory_id) && (
                  <span className="block text-[10px] text-amber-700 mt-1">Catalog cap unavailable; current pricing needs review.</span>
                )}
              </label>
              <label className="text-xs text-gray-500">
                Wall
                <select
                  className="w-full h-9 rounded-md border border-input bg-transparent px-2 text-sm"
                  value={cap.wall_component_id ?? ""}
                  aria-label="Cap wall"
                  onChange={(e) => {
                    const id = e.target.value;
                    const i = walls.findIndex((w) => w.component_id === id);
                    patchCap(index, {
                      wall_component_id: id,
                      wall_index: id === "" || i < 0 ? undefined : i,
                      segment_component_id: "",
                      segment_index: undefined,
                    });
                  }}
                >
                  <option value="">Unassigned</option>
                  {cap.wall_component_id && !walls.some((w) => w.component_id === cap.wall_component_id) && (
                    <option value={cap.wall_component_id} disabled>{`Missing wall (${String(cap.wall_component_id).slice(0, 18)}…)`}</option>
                  )}
                  {walls.map((w, i) => (
                    <option key={w.component_id || i} value={w.component_id || ""}>
                      {w.name || `Wall ${i + 1}`}
                    </option>
                  ))}
                </select>
              </label>
              <label className="text-xs text-gray-500">
                Segment
                <select
                  className="w-full h-9 rounded-md border border-input bg-transparent px-2 text-sm"
                  value={cap.segment_component_id ?? ""}
                  aria-label="Cap segment"
                  onChange={(e) => {
                    const id = e.target.value;
                    const wall = walls.find((w) => w.component_id === cap.wall_component_id);
                    const segs = wall?.shape?.segments || [];
                    const i = segs.findIndex((sg) => sg.component_id === id);
                    patchCap(index, {
                      segment_component_id: id,
                      segment_index: id === "" || i < 0 ? undefined : i,
                    });
                  }}
                >
                  <option value="">Unassigned</option>
                  {cap.segment_component_id && !(walls.find((w) => w.component_id === cap.wall_component_id)?.shape?.segments || []).some((sg) => sg.component_id === cap.segment_component_id) && (
                    <option value={cap.segment_component_id} disabled>{`Missing segment (${String(cap.segment_component_id).slice(0, 18)}…)`}</option>
                  )}
                  {(walls.find((w) => w.component_id === cap.wall_component_id)?.shape?.segments || []).map((sg, i) => (
                    <option key={sg.component_id || i} value={sg.component_id || ""}>
                      {`Segment ${i + 1}`}
                    </option>
                  ))}
                </select>
              </label>
              <label className="text-xs text-gray-500">
                Cut length (in)
                <Input
                  type="number"
                  step="any"
                  value={wallCapInputNumber(wallCapCutLengthValue(cap)) === null ? "" : wallCapCutLengthValue(cap)}
                  aria-label={`Cap ${index + 1} cut length (inches)`}
                  aria-invalid={geometryIssues(index).some((i) => i.field === "length_inches") || undefined}
                  aria-describedby={geometryIssues(index).length ? `wall-cap-${index}-geometry` : undefined}
                  onChange={(e) => {
                    const raw = e.target.value;
                    const parsed = wallCapInputNumber(raw);
                    patchCap(index, { length_inches: parsed === null ? raw : parsed });
                  }}
                />
              </label>
            </div>
            {geometryIssues(index).length > 0 && (
              <div id={`wall-cap-${index}-geometry`} className="mt-1 text-[11px] text-amber-700 space-y-0.5">
                {geometryIssues(index).map((issue) => (
                  <p key={issue.code}>{issue.message}</p>
                ))}
              </div>
            )}
            <div className="flex flex-wrap items-center justify-between gap-x-3 gap-y-2 mt-2 text-xs text-gray-600">
              <span>
                {unavailableCaps.has(index) ? "Saved stock length: " : "Stock length: "}<span className="font-semibold text-gray-900">{hasFoundationCostSnapshot(cap.stock_length_inches) && cap.stock_length_inches > 0 ? cap.stock_length_inches + String.fromCharCode(34) : "Not saved"}</span>
              </span>
              <div className="ml-auto flex items-center gap-3">
                <span className="font-bold text-gray-900">{hasFoundationCostSnapshot(cap.cost) ? money(cap.cost) : "Not saved"}</span>
                {unavailableCaps.has(index) && <span className="text-[10px] text-amber-700">Saved amounts (not current pricing)</span>}
                <Button variant="ghost" size="icon" onClick={() => removeCap(index)}>
                  <Trash2 className="w-4 h-4 text-red-500" aria-hidden="true" />
                </Button>
              </div>
            </div>
          </div>
        ))
      )}
    </div>
  );
}

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { inventoryDraftInput } from "@/components/masterInventory/inventoryNormalization";
import { Trash2, Plus } from "lucide-react";
import { money } from "./foundationCalc";
import { hasFoundationCostSnapshot } from "./foundationCatalogIntegrity";
import {
  POLE_SHAPE_VALUES,
  consolidateFoundationPoles,
} from "./poleCalculator";

// Blank-preserving project-entry draft, delegated to the boundary (CMP-A08).
const heightInput = inventoryDraftInput;

// CMP-E01/O-056: the project-level poles list below is the single priced
// representation. Items can still carry pre-consolidation pole fields; they
// surface here as an advisory (never priced — no double charge) and move onto
// the canonical list only through the explicit onMigrateItemPole callback.
// CMP-E02/O-057: the inputs keep the five distinct quantities separate —
// height above grade, embedment below grade (canonical `embedment_inches`;
// a legacy row's `y_offset_inches` migrates into it on edit), vertical base
// offset, and explicit total stock length — with the actual shape carried on
// `pole_shape`.
export default function FoundationPolesPanel({ poles = [], options = [], items = [], onChange, polePricing = [], onMigrateItemPole }) {
  const patchPole = (index, changes) =>
    onChange(poles.map((p, i) => (i === index ? { ...p, ...changes } : p)));

  const removePole = (index) => {
    if (!window.confirm(`Remove Pole ${index + 1}? Cabinets mounted on it are retained for review.`)) return;
    onChange(poles.filter((_, i) => i !== index));
  };

  const addPole = () =>
    onChange([
      ...poles,
      { pole_id: options[0]?.id || "", height_inches: 120, embedment_inches: 42, include_pole_painting: false },
    ]);

  // Legacy item-pole fields ride on the items; they are advisory-only and
  // never part of the priced list this panel edits.
  const consolidated = consolidateFoundationPoles({ items, poles });

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="font-semibold text-gray-900">Poles</h2>
          <p className="text-xs text-gray-500">
            Priced on billed length — an explicit total stock length, or height above grade plus embedment.
          </p>
        </div>
        <Button variant="outline" size="sm" onClick={addPole} disabled={options.length === 0}>
          <Plus className="w-4 h-4" aria-hidden="true" /> Pole
        </Button>
      </div>

      {options.length === 0 && (
        <div className="text-[11px] text-amber-800 bg-amber-50 border border-amber-200 rounded px-2 py-1.5">
          Pole catalog unavailable — existing rows remain editable; new poles cannot be added.
        </div>
      )}
      {consolidated.legacyPoles.length > 0 && (
        <div role="status" className="text-[11px] text-amber-800 bg-amber-50 border border-amber-200 rounded px-2 py-1.5 space-y-1">
          <p className="font-semibold">Legacy item-pole data — not priced</p>
          {consolidated.legacyPoles.map((d) => (
            <div key={d.source_item_component_id || `item-${d.source_item_index}`} className="flex items-center justify-between gap-2">
              <span>
                Foundation {d.source_item_index + 1} carries legacy pole fields
                {d.legacy_pole_cost !== null || d.legacy_pole_painting_cost !== null ? " (with saved amounts)" : ""}.
              </span>
              {typeof onMigrateItemPole === "function" && (
                <Button variant="outline" size="sm" onClick={() => onMigrateItemPole(d.source_item_index)}>
                  Move to Poles
                </Button>
              )}
            </div>
          ))}
          {consolidated.overlaps.length > 0 && (
            <p>A project pole already sits on the same foundation — verify it is not the same physical pole before migrating.</p>
          )}
        </div>
      )}
      {poles.length === 0 ? (
        <div className="text-center py-6 bg-white rounded-xl border border-dashed border-gray-300 text-gray-500 text-sm">
          No poles on this section.
        </div>
      ) : (
        poles.map((pole, index) => {
          const issues = polePricing[index]?.issues || [];
          const pricingUnavailable = polePricing[index]?.available === false;
          const geometry = polePricing[index]?.geometry || null;
          const fieldIssue = (field) => issues.some((i) => i.field === field);
          const describedBy = issues.length ? `pole-${index}-pricing` : undefined;
          const authoredShape = pole.pole_shape ?? "";
          const shapeChoices = authoredShape && !POLE_SHAPE_VALUES.includes(authoredShape)
            ? [authoredShape, ...POLE_SHAPE_VALUES]
            : POLE_SHAPE_VALUES;
          return (
            <div key={pole.component_id || index} className="bg-white rounded-xl border border-gray-200 p-3">
              <div className="grid grid-cols-2 md:grid-cols-4 gap-2 items-end">
                <label className="text-xs text-gray-500 md:col-span-2">
                  Pole
                  <select
                    className="w-full h-9 rounded-md border border-input bg-transparent px-2 text-sm"
                    value={pole.pole_id || ""}
                    aria-label="Pole material"
                    aria-invalid={fieldIssue("pole_id") || undefined}
                    aria-describedby={fieldIssue("pole_id") ? describedBy : undefined}
                    onChange={(e) => patchPole(index, { pole_id: e.target.value })}
                  >
                    <option value="">Select pole…</option>
                    {pole.pole_id && !options.some((o) => o.id === pole.pole_id) && (
                      <option value={pole.pole_id} disabled>{`Catalog pole unavailable (${pole.pole_id})`}</option>
                    )}
                    {options.map((o) => (
                      <option key={o.id} value={o.id}>
                        {o.material_name}
                      </option>
                    ))}
                  </select>
                  {pole.pole_id && !options.some((o) => o.id === pole.pole_id) && (
                    <span className="block text-[10px] text-amber-700 mt-1">Catalog pole unavailable; current pricing needs review.</span>
                  )}
                </label>
                <label className="text-xs text-gray-500">
                  Shape
                  <select
                    className="w-full h-9 rounded-md border border-input bg-transparent px-2 text-sm"
                    value={authoredShape}
                    aria-label={`Pole ${index + 1} cross-section shape`}
                    aria-invalid={fieldIssue("pole_shape") || undefined}
                    aria-describedby={fieldIssue("pole_shape") ? describedBy : undefined}
                    onChange={(e) => patchPole(index, { pole_shape: e.target.value === "" ? undefined : e.target.value })}
                  >
                    <option value="">Catalog / unspecified</option>
                    {shapeChoices.map((s) => (
                      <option key={s} value={s}>{s}</option>
                    ))}
                  </select>
                </label>
                <label className="text-xs text-gray-500">
                  Foundation
                  <select
                    className="w-full h-9 rounded-md border border-input bg-transparent px-2 text-sm"
                    value={pole.foundation_component_id ?? ""}
                    aria-label="Pole foundation"
                    onChange={(e) => {
                      const id = e.target.value;
                      const i = items.findIndex((it) => it.component_id === id);
                      patchPole(index, {
                        foundation_component_id: id,
                        foundation_idx: id === "" || i < 0 ? undefined : i,
                      });
                    }}
                  >
                    <option value="">Unassigned</option>
                    {pole.foundation_component_id && !items.some((it) => it.component_id === pole.foundation_component_id) && (
                      <option value={pole.foundation_component_id} disabled>{`Missing foundation (${String(pole.foundation_component_id).slice(0, 18)}…)`}</option>
                    )}
                    {items.map((it, i) => (
                      <option key={it.component_id || i} value={it.component_id || ""}>
                        {it.description || `Foundation ${i + 1}`}
                      </option>
                    ))}
                  </select>
                </label>
                <label className="text-xs text-gray-500">
                  Height above grade (in)
                  <Input
                    type="number"
                    step="any"
                    value={pole.height_inches ?? ""}
                    aria-label={`Pole ${index + 1} height above grade (inches)`}
                    aria-invalid={fieldIssue("height_inches") || undefined}
                    aria-describedby={fieldIssue("height_inches") ? describedBy : undefined}
                    onChange={(e) => patchPole(index, { height_inches: heightInput(e.target.value) })}
                  />
                </label>
                <label className="text-xs text-gray-500">
                  Embedment below grade (in)
                  <Input
                    type="number"
                    step="any"
                    // A recorded canonical value wins; blank canonical falls
                    // back to the legacy spelling so display matches pricing.
                    value={(pole.embedment_inches !== undefined && pole.embedment_inches !== null && pole.embedment_inches !== "")
                      ? pole.embedment_inches
                      : (pole.y_offset_inches ?? "")}
                    aria-label={`Pole ${index + 1} embedment below grade (inches)`}
                    aria-invalid={fieldIssue("embedment_inches") || fieldIssue("y_offset_inches") || undefined}
                    aria-describedby={(fieldIssue("embedment_inches") || fieldIssue("y_offset_inches")) ? describedBy : undefined}
                    onChange={(e) => patchPole(index, {
                      // Canonical field carries the edit; the legacy spelling
                      // clears so the two can never diverge into a conflict.
                      embedment_inches: heightInput(e.target.value),
                      y_offset_inches: undefined,
                    })}
                  />
                </label>
                <label className="text-xs text-gray-500">
                  Base offset above grade (in)
                  <Input
                    type="number"
                    step="any"
                    value={pole.base_offset_inches ?? ""}
                    aria-label={`Pole ${index + 1} base offset above grade (inches)`}
                    aria-invalid={fieldIssue("base_offset_inches") || undefined}
                    aria-describedby={fieldIssue("base_offset_inches") ? describedBy : undefined}
                    onChange={(e) => patchPole(index, { base_offset_inches: heightInput(e.target.value) })}
                  />
                </label>
                <label className="text-xs text-gray-500">
                  Total stock length (in)
                  <Input
                    type="number"
                    step="any"
                    value={pole.total_length_inches ?? ""}
                    aria-label={`Pole ${index + 1} total stock length (inches)`}
                    aria-invalid={fieldIssue("total_length_inches") || undefined}
                    aria-describedby={fieldIssue("total_length_inches") ? describedBy : undefined}
                    onChange={(e) => patchPole(index, { total_length_inches: heightInput(e.target.value) })}
                  />
                </label>
              </div>

              <div className="flex items-center justify-between mt-2">
                <label className="flex items-center gap-1.5 text-xs font-medium text-gray-700">
                  <input
                    type="checkbox"
                    checked={!!pole.include_pole_painting}
                    aria-invalid={issues.some((i) => i.code === "pole_paint_setting_unavailable") || undefined}
                    aria-describedby={issues.some((i) => i.code === "pole_paint_setting_unavailable") ? describedBy : undefined}
                    onChange={(e) => patchPole(index, { include_pole_painting: e.target.checked })}
                  />
                  Paint pole
                </label>
                <div className="flex items-center gap-3 text-xs text-gray-600">
                  {geometry && Number.isFinite(geometry.required_length_inches) && (
                    <span title={`Required ${geometry.required_length_inches} in${Number.isFinite(pole.stock_pieces) ? ` · ${pole.stock_pieces} stock ${pole.stock_pieces === 1 ? "piece" : "pieces"}` : ""}${geometry.pole_shape ? ` · ${geometry.pole_shape}` : ""}${geometry.base_offset_inches > 0 ? ` · base +${geometry.base_offset_inches} in` : ""}`}>
                      {geometry.required_length_inches} in req
                    </span>
                  )}
                  <span>Pole {hasFoundationCostSnapshot(pole.pole_cost) ? money(pole.pole_cost) : "Not saved"}</span>
                  <span>Paint {hasFoundationCostSnapshot(pole.pole_painting_cost) ? money(pole.pole_painting_cost) : "Not saved"}</span>
                  <span className="font-bold text-gray-900 text-sm">{hasFoundationCostSnapshot(pole.total_cost) ? money(pole.total_cost) : "Not saved"}</span>
                  {pricingUnavailable && <span className="col-span-full text-[10px] text-amber-700">Saved amounts (not current pricing)</span>}
                  <Button variant="ghost" size="icon" onClick={() => removePole(index)}>
                    <Trash2 className="w-4 h-4 text-red-500" aria-hidden="true" />
                  </Button>
                </div>
              </div>
              {issues.length > 0 && (
                <div role="status" className="mt-2 text-[10px] text-amber-700 space-y-0.5" id={`pole-${index}-pricing`}>
                  {issues.map((issue) => <p key={`${issue.field}-${issue.code}`}>{issue.message}</p>)}
                </div>
              )}
            </div>
          );
        })
      )}
    </div>
  );
}

