import { useEffect, useRef, useState } from "react";
import { base44 } from "@/api/base44Client";
import { Cpu, Loader2 } from "lucide-react";
import ReactMarkdown from "react-markdown";
import {
  prepareFoundationAiReview,
  foundationAiReviewPatch,
  FOUNDATION_AI_REVIEW_POLICY,
} from "./foundationAiReview";

export default function AiEngineeringAssistant({ project, onResult }) {
  const [running, setRunning] = useState(false);
  const [error, setError] = useState("");
  const mountedRef = useRef(true);
  const busyRef = useRef(false);
  const tokenRef = useRef(0);
  const latestRef = useRef({ key: null, onResult });
  let inputError = "";
  let prepared = null;
  try {
    prepared = prepareFoundationAiReview(project);
  } catch (e) {
    inputError = e?.message || "The foundation inputs cannot be reviewed.";
  }
  latestRef.current = { key: prepared?.key ?? null, onResult };

  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
      tokenRef.current += 1;
      busyRef.current = false;
    };
  }, []);

  const run = async () => {
    if (busyRef.current || !prepared || typeof latestRef.current.onResult !== "function") return;
    busyRef.current = true;
    const token = ++tokenRef.current;
    const capturedKey = prepared.key;
    const request = prepared.request;
    setRunning(true);
    setError("");
    try {
      const res = await base44.integrations.Core.InvokeLLM(request);
      if (!mountedRef.current || token !== tokenRef.current) return;
      if (latestRef.current.key !== capturedKey) {
        setError("The design changed while this review was running. Run a fresh review.");
        return;
      }
      const patch = foundationAiReviewPatch(res, { sourceKey: capturedKey, generatedAt: new Date().toISOString() });
      const accepted = latestRef.current.onResult(patch);
      if (accepted === false) setError("The review could not be attached. No review changes were applied.");
    } catch (e) {
      if (!mountedRef.current || token !== tokenRef.current) return;
      setError(e.message || "The preliminary review could not run.");
    } finally {
      if (mountedRef.current && token === tokenRef.current) {
        busyRef.current = false;
        setRunning(false);
      }
    }
  };

  const recommendation = typeof project?.ai_engineering_recommendation === "string" ? project.ai_engineering_recommendation : "";
  const meta = project?.ai_engineering_data;
  const samePolicy = meta?.policy_version === FOUNDATION_AI_REVIEW_POLICY && typeof meta?.source_key === "string" && !!meta.source_key;
  const stale = samePolicy && (!prepared || meta.source_key !== prepared.key);
  const label = stale
    ? "Design changed since this note. Run a fresh review."
    : samePolicy && meta?.source_key
      ? "Preliminary review"
      : "Historical / unverified AI note";

  return (
    <div className="bg-violet-50 border border-violet-200 rounded-sm p-3 mb-3">
      <div className="flex items-start justify-between gap-3 flex-wrap">
        <div className="flex items-start gap-2 min-w-0">
          <Cpu className="w-4 h-4 text-violet-600 mt-0.5" aria-hidden="true" />
          <div className="min-w-0">
            <h3 className="text-[13px] font-bold text-violet-900">AI Preliminary Review</h3>
            <p className="text-[11px] text-violet-700">
              Identify missing inputs and questions for qualified engineering review; not structural calculations or approval.
            </p>
          </div>
        </div>
        <button
          type="button"
          onClick={run}
          disabled={running || !prepared || typeof onResult !== "function"}
          className="h-[30px] px-3 flex items-center gap-1.5 rounded-sm bg-violet-600 text-white text-[12px] font-semibold hover:bg-violet-700 disabled:opacity-60 flex-shrink-0"
        >
          {running ? <Loader2 className="w-3.5 h-3.5 animate-spin" aria-hidden="true" /> : <Cpu className="w-3.5 h-3.5" aria-hidden="true" />}
          {running ? "Reviewing…" : "Review Foundation Inputs"}
        </button>
      </div>

      {(inputError || error) && <div role="alert" className="mt-2 text-[11px] text-red-600">{inputError || error}</div>}

      {recommendation && (
        <div className="mt-3 bg-white border border-violet-200 rounded-sm p-3 text-[12px] text-gray-700 prose prose-sm max-w-none">
          <p className="text-[10px] font-semibold uppercase tracking-wide text-violet-500 mb-1">{label}</p>
          <ReactMarkdown>{recommendation}</ReactMarkdown>
        </div>
      )}
    </div>
  );
}

import { useEffect, useRef, useState } from "react";
import * as THREE from "three";
import { Maximize2, RotateCcw, Eye, EyeOff, Box } from "lucide-react";

const IN = 1 / 12; // inches -> feet units

function buildScene(scene, project, solid, showGround) {
  const group = new THREE.Group();

  const concreteMat = solid
    ? new THREE.MeshStandardMaterial({ color: 0x9ca3af, roughness: 0.9 })
    : new THREE.MeshBasicMaterial({ color: 0x374151, wireframe: true });
  const poleMat = solid
    ? new THREE.MeshStandardMaterial({ color: 0x4b5563, metalness: 0.4, roughness: 0.5 })
    : new THREE.MeshBasicMaterial({ color: 0x1f2937, wireframe: true });

  let cursorX = 0;
  const items = project.items || [];
  items.forEach((item) => {
    const qty = Math.max(1, Number(item.quantity) || 1);
    const depth = (Number(item.depth_inches) || 0) * IN;
    for (let i = 0; i < qty; i++) {
      let mesh;
      let footprint;
      if (item.foundation_type === "pillar") {
        const r = ((Number(item.diameter) || 0) / 2) * IN;
        footprint = r * 2;
        mesh = new THREE.Mesh(new THREE.CylinderGeometry(r, r, depth, 24), concreteMat);
      } else {
        const l = (Number(item.length_inches) || 0) * IN;
        const w = (Number(item.width_inches) || 0) * IN;
        footprint = Math.max(l, w);
        mesh = new THREE.Mesh(new THREE.BoxGeometry(l, depth, w), concreteMat);
      }
      const offset = (Number(item.grade_offset_inches) || 0) * IN;
      mesh.position.set(cursorX + footprint / 2, -depth / 2 + offset, 0);
      mesh.rotation.y = ((Number(item.rotation_degrees) || 0) * Math.PI) / 180;
      group.add(mesh);

      if (item.selected_pole_id || item.pole_total_height_inches) {
        const h = (Number(item.pole_total_height_inches) || 96) * IN;
        const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.35, 0.35, h, 16), poleMat);
        pole.position.set(mesh.position.x, offset + h / 2, 0);
        group.add(pole);
      }

      cursorX += footprint + 2;
    }
  });

  (project.poles || []).forEach((p) => {
    // CMP-E02: distinct quantities — the pole top sits at base offset plus
    // height above grade; embedment extends BELOW grade (canonical
    // embedment_inches; the legacy y_offset_inches spelling carries the same
    // authored "depth in ground" quantity and is no longer read as an upward
    // elevation — CMP-AUD07). Cross-section follows the authored/resolved
    // pole_shape; unspecified stays the round default.
    const height = (Number(p.height_inches) || 96) * IN;
    const embed = (Number(p.embedment_inches ?? p.y_offset_inches) || 0) * IN;
    const base = (Number(p.base_offset_inches) || 0) * IN;
    const len = height + embed;
    const shape = typeof p.pole_shape === "string" ? p.pole_shape.toLowerCase() : "round";
    let pole;
    if (shape === "square" || shape === "rectangular") {
      pole = new THREE.Mesh(new THREE.BoxGeometry(0.7, len, shape === "rectangular" ? 0.45 : 0.7), poleMat);
    } else {
      pole = new THREE.Mesh(new THREE.CylinderGeometry(0.35, 0.35, len, 16), poleMat);
      if (shape === "elliptical") pole.scale.z = 0.55;
    }
    pole.position.set(
      (Number(p.x_inches) || 0) * IN,
      base + (height - embed) / 2,
      (Number(p.z_inches) || 0) * IN
    );
    group.add(pole);
  });

  if (showGround) {
    const grid = new THREE.GridHelper(60, 60, 0xd1d5db, 0xe5e7eb);
    grid.position.y = 0.01;
    group.add(grid);
    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(60, 60),
      new THREE.MeshStandardMaterial({ color: 0xf3f4f6, roughness: 1 })
    );
    ground.rotation.x = -Math.PI / 2;
    group.add(ground);
  }

  // center the model horizontally
  const box = new THREE.Box3().setFromObject(group);
  const center = box.getCenter(new THREE.Vector3());
  group.position.x -= center.x;
  group.position.z -= center.z;

  scene.add(group);
  return group;
}

export default function Foundation3DPreview({ project }) {
  const mountRef = useRef(null);
  const stateRef = useRef({});
  const [solid, setSolid] = useState(true);
  const [showGround, setShowGround] = useState(true);
  const [visible, setVisible] = useState(true);
  const [zoom, setZoom] = useState(100);

  useEffect(() => {
    if (!visible || !mountRef.current) return;
    const mount = mountRef.current;
    const width = mount.clientWidth;
    const height = mount.clientHeight;

    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0xf9fafb);
    const camera = new THREE.PerspectiveCamera(45, width / height, 0.1, 2000);
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setPixelRatio(window.devicePixelRatio);
    renderer.setSize(width, height);
    mount.appendChild(renderer.domElement);

    scene.add(new THREE.HemisphereLight(0xffffff, 0x9ca3af, 1.1));
    const dir = new THREE.DirectionalLight(0xffffff, 0.7);
    dir.position.set(20, 30, 20);
    scene.add(dir);

    const st = stateRef.current;
    st.theta = st.theta ?? Math.PI / 4;
    st.phi = st.phi ?? Math.PI / 3.2;
    st.radius = st.radius ?? 30;
    st.target = st.target || new THREE.Vector3(0, 0, 0);

    const applyCamera = () => {
      const r = st.radius;
      camera.position.set(
        st.target.x + r * Math.sin(st.phi) * Math.cos(st.theta),
        st.target.y + r * Math.cos(st.phi),
        st.target.z + r * Math.sin(st.phi) * Math.sin(st.theta)
      );
      camera.lookAt(st.target);
    };

    buildScene(scene, project, solid, showGround);
    applyCamera();

    let frame;
    const render = () => {
      renderer.render(scene, camera);
      frame = requestAnimationFrame(render);
    };
    render();

    // --- controls ---
    let dragging = null;
    let last = { x: 0, y: 0 };
    const onDown = (e) => {
      dragging = e.button === 2 ? "pan" : "orbit";
      last = { x: e.clientX, y: e.clientY };
      e.preventDefault();
    };
    const onMove = (e) => {
      if (!dragging) return;
      const dx = e.clientX - last.x;
      const dy = e.clientY - last.y;
      last = { x: e.clientX, y: e.clientY };
      if (dragging === "orbit") {
        st.theta += dx * 0.008;
        st.phi = Math.min(Math.PI / 2.02, Math.max(0.15, st.phi - dy * 0.006));
      } else {
        const panScale = st.radius * 0.0015;
        st.target.x -= dx * panScale * Math.cos(st.theta + Math.PI / 2);
        st.target.z -= dx * panScale * Math.sin(st.theta + Math.PI / 2);
        st.target.y += dy * panScale;
      }
      applyCamera();
    };
    const onUp = () => (dragging = null);
    const onWheel = (e) => {
      e.preventDefault();
      st.radius = Math.min(200, Math.max(3, st.radius * (1 + e.deltaY * 0.001)));
      setZoom(Math.round((30 / st.radius) * 100));
      applyCamera();
    };
    const onContext = (e) => e.preventDefault();

    const el = renderer.domElement;
    el.addEventListener("mousedown", onDown);
    window.addEventListener("mousemove", onMove);
    window.addEventListener("mouseup", onUp);
    el.addEventListener("wheel", onWheel, { passive: false });
    el.addEventListener("contextmenu", onContext);

    const onResize = () => {
      const w = mount.clientWidth;
      const h = mount.clientHeight;
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
      renderer.setSize(w, h);
    };
    window.addEventListener("resize", onResize);

    stateRef.current.setView = (view) => {
      if (view === "front") { st.theta = -Math.PI / 2; st.phi = Math.PI / 2.05; }
      if (view === "side") { st.theta = 0; st.phi = Math.PI / 2.05; }
      if (view === "top") { st.theta = -Math.PI / 2; st.phi = 0.16; }
      if (view === "reset") {
        st.theta = Math.PI / 4;
        st.phi = Math.PI / 3.2;
        st.radius = 30;
        st.target.set(0, 0, 0);
        setZoom(100);
      }
      applyCamera();
    };

    return () => {
      cancelAnimationFrame(frame);
      el.removeEventListener("mousedown", onDown);
      window.removeEventListener("mousemove", onMove);
      window.removeEventListener("mouseup", onUp);
      el.removeEventListener("wheel", onWheel);
      el.removeEventListener("contextmenu", onContext);
      window.removeEventListener("resize", onResize);
      renderer.dispose();
      if (el.parentNode === mount) mount.removeChild(el);
    };
  }, [project, solid, showGround, visible]);

  const setView = (v) => stateRef.current.setView?.(v);

  const ToolBtn = ({ children, onClick, active }) => (
    <button
      type="button"
      onClick={onClick}
      className={`h-[24px] px-2 rounded-sm border text-[11px] font-medium flex items-center gap-1 ${
        active ? "bg-blue-600 border-blue-600 text-white" : "bg-white border-gray-300 text-gray-700"
      }`}
    >
      {children}
    </button>
  );

  return (
    <div className="bg-white border border-gray-200 rounded-sm p-2">
      <div className="flex items-center justify-between mb-2">
        <div>
          <span className="text-[12px] font-bold text-gray-800">3D Preview</span>
          <span className="text-[11px] text-gray-400 ml-2">Updates live as you edit</span>
        </div>
        <button
          type="button"
          onClick={() => setVisible((v) => !v)}
          className="text-[11px] font-medium text-gray-600 hover:text-red-600 flex items-center gap-1"
        >
          {visible ? <EyeOff className="w-3.5 h-3.5" aria-hidden="true" /> : <Eye className="w-3.5 h-3.5" aria-hidden="true" />}
          {visible ? "Hide 3D View" : "Show 3D View"}
        </button>
      </div>

      {visible && (
        <>
          <div className="flex items-center gap-1 flex-wrap mb-2">
            <ToolBtn onClick={() => setView("front")}>Front</ToolBtn>
            <ToolBtn onClick={() => setView("side")}>Side</ToolBtn>
            <ToolBtn onClick={() => setView("top")}>Top</ToolBtn>
            <ToolBtn onClick={() => setView("reset")}>
              <RotateCcw className="w-3 h-3" aria-hidden="true" /> Reset
            </ToolBtn>
            <span className="text-[11px] text-gray-500 px-1">{zoom}%</span>
            <ToolBtn onClick={() => setShowGround((v) => !v)} active={!showGround}>
              {showGround ? "Hide Ground" : "Show Ground"}
            </ToolBtn>
            <ToolBtn onClick={() => setSolid((v) => !v)} active={solid}>
              <Box className="w-3 h-3" aria-hidden="true" /> {solid ? "Solid Mode" : "Wireframe"}
            </ToolBtn>
            <ToolBtn onClick={() => mountRef.current?.requestFullscreen?.()}>
              <Maximize2 className="w-3 h-3" aria-hidden="true" /> Full Screen
            </ToolBtn>
          </div>

          <div ref={mountRef} className="w-full h-[420px] rounded-sm overflow-hidden bg-gray-50" />

          <div className="flex items-center justify-between text-[10px] text-gray-500 mt-1 px-1">
            <span>Left Click + Drag: Orbit/Rotate</span>
            <span>Right Click + Drag: Pan/Move</span>
            <span>Scroll Wheel: Zoom in/out</span>
          </div>
        </>
      )}
    </div>
  );
}

import { useEffect, useRef, useState } from "react";
import { base44 } from "@/api/base44Client";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Trash2 } from "lucide-react";
import { deleteFoundationTemplate, saveFoundationTemplate } from "./foundationTemplateService";
import { createFoundationTemplateSnapshot } from "./foundationTemplateModel";
import {
  FOUNDATION_ASSEMBLY_PRESETS,
  describeFoundationAssemblyPreset,
  foundationAssemblyPresetTemplateData,
} from "./foundationAssemblyPresets";
import { PRELIMINARY_NOTICE_TEXT } from "./foundationPreliminaryNotice";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";
import { newCreationRequestKey } from "@/components/estimator/idempotentEntityCreate";

export default function FoundationTemplateDialog({ open, mode, onClose, project, onApply, saveDisabled = false, saveDisabledReason = "" }) {
  const [templates, setTemplates] = useState([]);
  const [name, setName] = useState("");
  const [busy, setBusy] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [loadFailed, setLoadFailed] = useState(false);
  const saveAttemptRef = useRef({ signature: "", key: "" });
  const saveFlightRef = useRef(null);
  const contextRef = useRef({ open: false, mode: null, projectId: null, identity: "", generation: 0, project: null });
  const generationRef = useRef(0);
  const loadSeqRef = useRef(0);
  const mountedRef = useRef(true);
  const draftRef = useRef(null);
  draftRef.current = { project, name };

  const identity = `${open ? 1 : 0}|${mode}|${project?.id ?? ""}`;
  if (contextRef.current.identity !== identity) {
    generationRef.current += 1;
    contextRef.current = {
      open,
      mode,
      projectId: project?.id ?? null,
      project,
      identity,
      generation: generationRef.current,
    };
  } else {
    contextRef.current.open = open;
    contextRef.current.project = project;
  }
  const saveContext = { ...contextRef.current };
  const sameContext = (c) =>
    mountedRef.current &&
    c.open &&
    contextRef.current.open &&
    contextRef.current.identity === c.identity &&
    contextRef.current.generation === c.generation;

  useEffect(() => {
    mountedRef.current = true;
    return () => { mountedRef.current = false; };
  }, []);

  const loadRows = (gen) => {
    const seq = ++loadSeqRef.current;
    setLoading(true);
    setLoadFailed(false);
    setError(null);
    loadAllEntityRows({
      entity: base44.entities.ProjectTemplate,
      query: { module_key: "foundation" },
      sort: "created_date",
      label: "Foundation templates",
    })
      .then((rows) => {
        const c = contextRef.current;
        if (!mountedRef.current || !c.open || c.mode !== "load" || generationRef.current !== gen || loadSeqRef.current !== seq) return;
        setTemplates(rows || []);
        setError(null);
      })
      .catch((e) => {
        const c = contextRef.current;
        if (!mountedRef.current || !c.open || c.mode !== "load" || generationRef.current !== gen || loadSeqRef.current !== seq) return;
        setTemplates([]);
        setLoadFailed(true);
        setError(e?.message || "Templates could not be loaded.");
      })
      .finally(() => {
        if (mountedRef.current && loadSeqRef.current === seq) setLoading(false);
      });
  };

  useEffect(() => {
    if (!open) return;
    saveAttemptRef.current = { signature: "", key: "" };
    setTemplates([]);
    setError(null);
    setLoadFailed(false);
    if (mode !== "load") return;
    loadRows(generationRef.current);
  }, [open, mode, project?.id]);

  const save = () => {
    const sc = saveContext;
    if (saveFlightRef.current) return saveFlightRef.current;
    if (saveDisabled) return null;
    const trimmed = name.trim();
    if (!trimmed || !sameContext(sc) || sc.mode !== "save" || draftRef.current.project !== project || draftRef.current.name !== name) return null;
    let snapshot;
    try {
      snapshot = createFoundationTemplateSnapshot(project, {
        createId: (kind) => newCreationRequestKey(`template_${kind}`),
      });
    } catch (e) {
      setError(e?.message || "Template snapshot could not be prepared.");
      return null;
    }
    const data = { template_name: trimmed, module_key: "foundation", project_data: snapshot };
    const signature = JSON.stringify(data);
    if (saveAttemptRef.current.signature !== signature) {
      saveAttemptRef.current = {
        signature,
        key: `foundation_template_save:${crypto.randomUUID?.() || `${Date.now()}-${Math.random()}`}`,
        data,
      };
    }
    const attempt = saveAttemptRef.current;
    const run = Promise.resolve()
      .then(async () => {
        if (!sameContext(sc)) return;
        setBusy(true);
        try {
          await saveFoundationTemplate({ idempotencyKey: attempt.key, data: attempt.data });
          if (!sameContext(sc)) return;
          if (draftRef.current.project !== project || draftRef.current.name !== name) {
            setError("The earlier template snapshot was saved. Current changes have not been saved as a template.");
            return;
          }
          setName("");
          saveAttemptRef.current = { signature: "", key: "" };
          setError(null);
          onClose();
        } catch (e) {
          if (sameContext(sc)) setError(e?.message || "Template could not be saved.");
        }
      })
      .finally(() => {
        if (saveFlightRef.current !== run) return;
        saveFlightRef.current = null;
        if (mountedRef.current) setBusy(false);
      });
    saveFlightRef.current = run;
    return run;
  };

  const apply = (t) => {
    const sc = saveContext;
    if (!sameContext(sc)) return;
    let ok = false;
    try {
      ok = onApply(t.project_data || {}) === true;
    } catch (e) {
      if (sameContext(sc)) setError(e?.message || "Template could not be applied.");
      return;
    }
    if (!sameContext(sc)) return;
    if (ok) {
      setError(null);
      onClose();
    } else {
      setError("Template was not applied; the current project was left unchanged.");
    }
  };

  // O-094: start-from-assembly presets ride the same onApply(data) lane as a
  // saved template — the page's prepareFoundationTemplatePatch gate validates
  // the preset record, mints fresh component ids, and remaps references.
  const applyPreset = (preset) => {
    const sc = saveContext;
    if (!sameContext(sc)) return;
    let ok = false;
    try {
      ok = onApply(foundationAssemblyPresetTemplateData(preset)) === true;
    } catch (e) {
      if (sameContext(sc)) setError(e?.message || "Assembly preset could not be applied.");
      return;
    }
    if (!sameContext(sc)) return;
    if (ok) {
      setError(null);
      onClose();
    } else {
      setError("Preset was not applied; the current project was left unchanged.");
    }
  };

  const remove = async (t) => {
    const sc = saveContext;
    if (!sameContext(sc)) return;
    if (!window.confirm(`Delete template "${t.template_name || "Untitled"}"?`)) return;
    try {
      await deleteFoundationTemplate(t.id);
      if (!sameContext(sc)) return;
      setTemplates((prev) => prev.filter((x) => x.id !== t.id));
      setError(null);
    } catch (e) {
      if (sameContext(sc)) setError(e?.message || "Template could not be deleted.");
    }
  };

  return (
    <Dialog open={open} onOpenChange={(v) => !v && onClose()}>
      <DialogContent className="max-w-[520px]">
        <DialogHeader>
          <DialogTitle className="text-[15px]">
            {mode === "save" ? "Save as Template" : "Foundation Templates"}
          </DialogTitle>
        </DialogHeader>

        {error ? (
          <div role="alert" className="text-[12px] text-red-700 bg-red-50 border border-red-200 rounded px-2 py-1.5">
            {error}
          </div>
        ) : null}

        {mode === "save" ? (
          <div className="space-y-3">
            <label className="text-[11px] text-gray-500 block">
              Template name
              <input
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="e.g. Standard 8ft Pylon Foundation"
                className="w-full h-[30px] px-2 border border-gray-300 rounded-sm text-[12px] focus:outline-none focus:border-red-400"
              />
            </label>
            {saveDisabled ? (
              <p className="text-[11px] text-amber-800 bg-amber-50 border border-amber-200 rounded px-2 py-1.5">
                {saveDisabledReason || "Saving a template is not available right now."}
              </p>
            ) : null}
            <p className="text-[11px] text-gray-500">
              Saved template notes lead with &quot;{PRELIMINARY_NOTICE_TEXT}&quot;.
            </p>
            <div className="flex justify-end gap-2">
              <button type="button" onClick={onClose} className="h-[30px] px-3 border border-gray-300 rounded-sm text-[12px]">
                Cancel
              </button>
              <button type="button"
                onClick={save}
                disabled={busy || saveDisabled}
                className="h-[30px] px-4 rounded-sm bg-lime-300 border border-lime-400 text-[12px] font-bold text-gray-800 disabled:opacity-60"
              >
                Save Template
              </button>
            </div>
          </div>
        ) : (
          <div className="space-y-4">
            <div>
              <p className="text-[10px] uppercase tracking-wide text-gray-400 mb-1">Start from an assembly preset</p>
              <div className="divide-y divide-gray-100 border border-gray-200 rounded-sm">
                {FOUNDATION_ASSEMBLY_PRESETS.map((p) => {
                  const d = describeFoundationAssemblyPreset(p);
                  return (
                    <div key={d.preset_key} className="flex items-center gap-2 px-2 py-2">
                      <div className="flex-1">
                        <div className="text-[12px] font-semibold text-gray-800">{d.name}</div>
                        <div className="text-[11px] text-gray-500">{d.summary}</div>
                        <div className="text-[10px] text-gray-400">{d.counts_label}</div>
                      </div>
                      <button type="button"
                        onClick={() => applyPreset(p)}
                        className="h-[26px] px-3 rounded-sm bg-white border border-gray-300 text-[11px] font-semibold text-gray-700"
                      >
                        Apply
                      </button>
                    </div>
                  );
                })}
              </div>
              <p className="text-[10px] text-gray-400 mt-1">
                Applying a preset replaces the current foundation assembly sections.
              </p>
            </div>
            <div>
              <p className="text-[10px] uppercase tracking-wide text-gray-400 mb-1">Saved templates</p>
              {loading ? (
                <p className="text-[12px] text-gray-500 py-4">Loading…</p>
              ) : loadFailed ? (
                <div className="py-4 space-y-2">
                  <p className="text-[12px] text-gray-500">Templates could not be loaded.</p>
                  <button type="button"
                    onClick={() => { const c = saveContext; if (sameContext(c)) loadRows(generationRef.current); }}
                    className="h-[26px] px-3 rounded-sm bg-white border border-gray-300 text-[11px] font-semibold text-gray-700"
                  >
                    Retry
                  </button>
                </div>
              ) : templates.length === 0 ? (
                <p className="text-[12px] text-gray-500 py-4">No foundation templates saved yet.</p>
              ) : (
                <div className="divide-y divide-gray-200 max-h-[320px] overflow-y-auto border border-gray-200 rounded-sm">
                  {templates.map((t) => (
                    <div key={t.id} className="flex items-center gap-2 px-2 py-2">
                      <div className="flex-1">
                        <div className="text-[12px] font-semibold text-gray-800">{t.template_name}</div>
                        <div className="text-[11px] text-gray-500">
                          {(t.project_data?.items || []).length} foundations
                        </div>
                        {typeof t.project_data?.ai_engineering_recommendation === "string" &&
                        t.project_data.ai_engineering_recommendation.trim() ? (
                          <div className="text-[10px] text-violet-600">
                            Includes an AI review note — stale on this project
                          </div>
                        ) : null}
                        {typeof t.project_data?.notes === "string" && t.project_data.notes.trim() ? (
                          <div className="text-[10px] text-gray-500">Includes project notes</div>
                        ) : null}
                      </div>
                      <button type="button"
                        onClick={() => apply(t)}
                        className="h-[26px] px-3 rounded-sm bg-white border border-gray-300 text-[11px] font-semibold text-gray-700"
                      >
                        Apply
                      </button>
                      <button type="button" onClick={() => remove(t)} className="text-gray-400 hover:text-red-600">
                        <Trash2 className="w-4 h-4" aria-hidden="true" />
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

