import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { AlertTriangle as AlertTriangleIcon, GitCompareArrows as GitCompareIcon, RefreshCw as RefreshIcon } from "lucide-react";
import {
