// Blank-preserving draft coercion (same rule as the wall/pole/equipment
// panels): a blank draft stays blank, a numeric draft becomes a number, and a
// malformed draft is stored verbatim so the pricing diagnostics can flag it —
// never coerced to 0 by parseFloat || 0.
const cabinetInputValue = (value) =>
  value === "" ? "" : Number.isFinite(Number(value)) ? Number(value) : value;

const Field = ({ label, ...props }) => (
  <label className="text-[10px] text-gray-500">
    {label}
    <Input {...props} className="h-8 text-[12px]" />
  </label>
);

function CabinetRow({ cabinet, detail, diagId, onChange, onRemove }) {
  const issues = detail?.issues || [];
  const broken = issues.length > 0;
  const fieldIssue = (field) => issues.some((i) => i.field === field);
  const describedBy = (field) => (fieldIssue(field) ? diagId : undefined);
  const num = (key) => (e) => onChange({ [key]: cabinetInputValue(e.target.value) });
  const lineTotal = broken || !Number.isFinite(detail?.cost) ? "Not saved" : money(detail.cost);
  return (
    <div className={`rounded-sm border bg-white p-2 ${broken ? "border-amber-300" : "border-gray-200"}`}>
      <div className="flex items-center gap-2 mb-2">
        <Input
          value={cabinet.description || ""}
          onChange={(e) => onChange({ description: e.target.value })}
          placeholder="Cabinet description"
          className="h-8 text-[12px]"
        />
        <span className={`text-[12px] font-bold whitespace-nowrap ${broken ? "text-amber-700" : "text-gray-800"}`}>
          {lineTotal}
        </span>
        <button type="button" onClick={onRemove} className="text-gray-400 hover:text-red-600" title="Remove">
          <Trash2 className="w-4 h-4" aria-hidden="true" />
        </button>
      </div>
      {broken && (
        <ul role="status" id={diagId} className="list-disc pl-5 mb-2 text-[10px] text-amber-800">
          {issues.map((i, k) => <li key={k}>{i.message}</li>)}
        </ul>
      )}
      <div className="grid grid-cols-3 sm:grid-cols-6 gap-2">
        <Field label="Width (in)" type="number" value={cabinet.width_inches ?? 0} onChange={num("width_inches")} />
        <Field label="Height (in)" type="number" value={cabinet.height_inches ?? 0} onChange={num("height_inches")} />
        <Field label="Depth (in)" type="number" value={cabinet.depth_inches ?? 0} onChange={num("depth_inches")} />
        <Field
          label="Mount ht (in)"
          type="number"
          value={cabinet.mount_height_inches ?? 0}
          onChange={num("mount_height_inches")}
        />
        <Field
          label="Qty"
          type="number"
          min={0}
          step="any"
          placeholder="1"
          data-cabinet-field="quantity"
          value={cabinet.quantity ?? ""}
          aria-invalid={fieldIssue("quantity") || undefined}
          aria-describedby={describedBy("quantity")}
          onChange={num("quantity")}
        />
        <Field
          label="Unit cost"
          type="number"
          min={0}
          step="any"
          placeholder="0"
          data-cabinet-field="unit_cost"
          value={cabinet.unit_cost ?? ""}
          aria-invalid={fieldIssue("unit_cost") || undefined}
          aria-describedby={describedBy("unit_cost")}
          onChange={num("unit_cost")}
        />
      </div>
    </div>
  );
}

export default function SignageCabinetsPanel({ cabinets = [], items = [], poles = [], onChange }) {
  const pricingRows = calcSignageCabinetPricing(cabinets);
  const hasIssues = pricingRows.some((row) => row.issues.length > 0);
  const update = (idx, changes) =>
    onChange(cabinets.map((c, i) => (i === idx ? { ...c, ...changes } : c)));
  const remove = (idx) => {
    if (!window.confirm("Remove this cabinet?")) return;
    onChange(cabinets.filter((_, i) => i !== idx));
  };
  const add = (mount, index) => {
    const parent = mount === "foundation" ? items[index] : poles[index];
    onChange([...cabinets, blankCabinet(mount, index, parent?.component_id)]);
  };

  const canonParentId = (c) => (c.mount === "pole" ? c.pole_component_id : c.foundation_component_id);
  const hasCanonProp = (c) => (c.mount === "pole" ? Object.prototype.hasOwnProperty.call(c, "pole_component_id") : Object.prototype.hasOwnProperty.call(c, "foundation_component_id"));

  const group = (mount, index) =>
    cabinets
      .map((c, i) => ({ c, i }))
      .filter(({ c }) => {
        if (c.mount !== mount) return false;
        const parent = mount === "foundation" ? items[index] : poles[index];
        const canon = canonParentId(c);
        if (hasCanonProp(c)) return canon !== "" && canon === parent?.component_id;
        return mount === "foundation" ? c.foundation_index === index : c.pole_index === index;
      });

  const orphans = cabinets
    .map((c, i) => ({ c, i }))
    .filter(({ c }) => {
      if (c.mount !== "pole" && c.mount !== "foundation") return true;
      const canon = canonParentId(c);
      const pool = c.mount === "pole" ? poles : items;
      if (hasCanonProp(c)) {
        if (canon === "") return true;
        return !pool.some((p) => p?.component_id === canon);
      }
      const legacy = c.mount === "pole" ? c.pole_index : c.foundation_index;
      const resolved = typeof legacy === "number" && Number.isInteger(legacy) && legacy >= 0 && pool[legacy] !== undefined;
      return !resolved;
    });

  const reassign = (i, mount, canonId) => {
    const pool = mount === "pole" ? poles : items;
    const index = pool.findIndex((p) => p?.component_id === canonId);
    if (mount === "pole") update(i, { mount: "pole", pole_component_id: canonId, pole_index: canonId === "" || index < 0 ? undefined : index, foundation_component_id: "", foundation_index: undefined });
    else update(i, { mount: "foundation", foundation_component_id: canonId, foundation_index: canonId === "" || index < 0 ? undefined : index, pole_component_id: "", pole_index: undefined });
  };

  return (
    <div className="space-y-4">
      {hasIssues && (
        <p className="rounded-sm border border-amber-300 bg-amber-50 px-2 py-1 text-[11px] font-semibold text-amber-800">
          Cabinet pricing unavailable — fix highlighted inputs. Saved amounts only; the current total is not repriced.
        </p>
      )}
      <div className="bg-white rounded-sm border border-gray-200 p-3">
        <h3 className="text-[13px] font-bold text-gray-900">Signage Cabinets</h3>
        <p className="text-[11px] text-gray-400 mb-2">
          Add cabinets directly on a foundation or mount them on a placed pole.
        </p>

        {items.length === 0 ? (
          <p className="text-[11px] italic text-gray-400">Add a foundation first to mount cabinets on it.</p>
        ) : (
          items.map((item, index) => {
            const rows = group("foundation", index);
            return (
              <div key={index} className="border border-gray-200 rounded-sm p-2 mb-2">
                <div className="flex items-center justify-between mb-1">
                  <span className="text-[12px] font-semibold text-gray-700">
                    Foundation {index + 1}
                    {item.description ? ` — ${item.description}` : ""}
                  </span>
                  <button type="button"
                    onClick={() => add("foundation", index)}
                    className="h-[26px] px-2 flex items-center gap-1 rounded-sm border border-gray-300 text-[11px] text-gray-700 hover:bg-gray-50"
                  >
                    <Plus className="w-3 h-3" aria-hidden="true" /> Add Cabinet
                  </button>
                </div>
                {rows.length === 0 ? (
                  <p className="text-[11px] text-gray-400">No cabinets on this foundation.</p>
                ) : (
                  <div className="space-y-2">
                    {rows.map(({ c, i }) => (
                      <CabinetRow
                        key={c.component_id || c.id || i}
                        cabinet={c}
                        detail={pricingRows[i]}
                        diagId={`signage-cabinet-${i}-pricing`}
                        onChange={(changes) => update(i, changes)}
                        onRemove={() => remove(i)}
                      />
                    ))}
                  </div>
                )}
              </div>
            );
          })
        )}
      </div>

      <div className="bg-white rounded-sm border border-gray-200 p-3">
        <h3 className="text-[13px] font-bold text-gray-900">Signage Cabinets on Poles</h3>
        <p className="text-[11px] text-gray-400 mb-2">
          Add cabinets to placed poles. Place poles in the "Walls &amp; Poles" tab.
        </p>
        {poles.length === 0 ? (
          <p className="text-[11px] italic text-gray-400">
            No poles placed. To mount cabinets on a pole, add poles in the "Walls &amp; Poles" tab. (Or skip this and
            use foundation-mounted cabinets above.)
          </p>
        ) : (
          poles.map((pole, index) => {
            const rows = group("pole", index);
            return (
              <div key={index} className="border border-gray-200 rounded-sm p-2 mb-2">
                <div className="flex items-center justify-between mb-1">
                  <span className="text-[12px] font-semibold text-gray-700">Pole {index + 1}</span>
                  <button type="button"
                    onClick={() => add("pole", index)}
                    className="h-[26px] px-2 flex items-center gap-1 rounded-sm border border-gray-300 text-[11px] text-gray-700 hover:bg-gray-50"
                  >
                    <Plus className="w-3 h-3" aria-hidden="true" /> Add Cabinet
                  </button>
                </div>
                {rows.length === 0 ? (
                  <p className="text-[11px] text-gray-400">No cabinets on this pole.</p>
                ) : (
                  <div className="space-y-2">
                    {rows.map(({ c, i }) => (
                      <CabinetRow
                        key={c.component_id || c.id || i}
                        cabinet={c}
                        detail={pricingRows[i]}
                        diagId={`signage-cabinet-${i}-pricing`}
                        onChange={(changes) => update(i, changes)}
                        onRemove={() => remove(i)}
                      />
                    ))}
                  </div>
                )}
              </div>
            );
          })
        )}

        {orphans.length > 0 && (
          <div data-orphan="true" className="border border-amber-300 bg-amber-50 rounded-sm p-2 mt-2">
            <span className="text-[12px] font-semibold text-amber-800">Unassigned cabinets</span>
            <div className="space-y-2 mt-2">
              {orphans.map(({ c, i }) => (
                <div key={c.component_id || c.id || i}>
                  <CabinetRow
                    cabinet={c}
                    detail={pricingRows[i]}
                    diagId={`signage-cabinet-${i}-pricing`}
                    onChange={(changes) => update(i, changes)}
                    onRemove={() => remove(i)}
                  />
                  <label className="block text-[10px] text-amber-800 mt-1">
                    Reassign
                    <select
                      className="ml-2 h-7 rounded-sm border border-amber-300 bg-white px-1 text-[11px]"
                      value=""
                      aria-label="Reassign cabinet"
                      onChange={(e) => {
                        const v = e.target.value;
                        if (v === "") return;
                        if (v.startsWith("pole:")) reassign(i, "pole", v.slice(5));
                        else if (v.startsWith("foundation:")) reassign(i, "foundation", v.slice(11));
                      }}
                    >
                      <option value="">Select parent…</option>
                      {items.map((it, ix) => (
                        <option key={it.component_id || ix} value={`foundation:${it.component_id}`}>{it.description || `Foundation ${ix + 1}`}</option>
                      ))}
                      {poles.map((po, ix) => (
                        <option key={po.component_id || ix} value={`pole:${po.component_id}`}>{po.description || `Pole ${ix + 1}`}</option>
                      ))}
                    </select>
                  </label>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

import { useState } from "react";
import { Trash2 } from "lucide-react";
import {
  LANDSCAPE_MATERIALS,
  GRID_COLS,
  GRID_ROWS,
  landscapeSummary,
  materialByKey,
} from "./landscapeMaterials";
import { money } from "./foundationCalc";

const sqftLabel = (l) =>
  Number.isFinite(l.sqft) ? `${l.sqft.toFixed(0)} sq ft`
    : `${l.cells} cell${l.cells === 1 ? "" : "s"} — area unavailable`;
const costLabel = (v) => (Number.isFinite(v) ? money(v) : "Not saved");

// Blank-preserving draft coercion (same rule as the cabinet panel): a blank
// draft stays blank, a numeric draft becomes a number, and a malformed draft
// is stored verbatim so the pricing diagnostics can flag it. The cell size is
// never defaulted here — the ported `|| 12` minted a guess on a missing value.
const landscapeInputValue = (value) =>
  value === "" ? "" : Number.isFinite(Number(value)) ? Number(value) : value;

export default function LandscapeDesigner({ landscape, onChange }) {
  const [brush, setBrush] = useState("grass");
  const [painting, setPainting] = useState(false);
  const cells = landscape?.cells || {};
  const summary = landscapeSummary(landscape);
  const broken = summary.issues.length > 0;
  const cellSizeIssue = summary.issues.some((i) => i.field === "cell_size_inches");

  const paint = (x, y) => {
    const key = `${x},${y}`;
    const next = { ...cells };
    if (brush === "dirt") delete next[key];
    else next[key] = brush;
    // Preserve the authored cell size verbatim — never mint a guessed 12 over
    // a missing value; an absent/malformed size stays flagged until recorded.
    onChange({ cell_size_inches: landscape?.cell_size_inches, cells: next });
  };

  return (
    <div className={`bg-white rounded-sm border p-3 ${broken ? "border-amber-300" : "border-gray-200"}`}>
      <div className="flex items-center justify-between mb-2">
        <div>
          <h3 className="text-[13px] font-bold text-gray-900">Landscape Designer</h3>
          <p className="text-[11px] text-gray-400">
            Draw landscaping features, paths and site boundaries. Each cell is 1 sq ft.
          </p>
        </div>
        <div className="flex items-center gap-2">
          <label className="text-[10px] text-gray-500">
            Cell size (in)
            <input
              type="number"
              min={0}
              step="any"
              data-landscape-field="cell_size_inches"
              value={landscape?.cell_size_inches ?? ""}
              aria-invalid={cellSizeIssue || undefined}
              aria-describedby={cellSizeIssue ? "landscape-pricing" : undefined}
              onChange={(e) => onChange({
                cell_size_inches: landscapeInputValue(e.target.value),
                cells,
              })}
              className={`ml-1 h-7 w-16 rounded-sm border px-1 text-[11px] ${cellSizeIssue ? "border-amber-400 bg-amber-50" : "border-gray-300"}`}
            />
          </label>
          <button type="button"
            onClick={() => {
              if (!window.confirm("Clear all landscaping from the canvas?")) return;
              onChange({ cell_size_inches: 12, cells: {} });
            }}
            className="h-[26px] px-2 flex items-center gap-1 rounded-sm border border-gray-300 text-[11px] text-gray-600 hover:bg-gray-50"
          >
            <Trash2 className="w-3 h-3" aria-hidden="true" /> Clear
          </button>
        </div>
      </div>

      {broken && (
        <ul role="status" id="landscape-pricing" className="list-disc pl-5 mb-2 text-[10px] text-amber-800">
          {summary.issues.map((i, k) => <li key={k}>{i.message}</li>)}
        </ul>
      )}

      <div className="flex gap-3 items-start">
        <div className="w-[120px] flex-shrink-0 space-y-1">
          <div className="text-[10px] font-bold uppercase tracking-wide text-gray-400">Materials</div>
          {LANDSCAPE_MATERIALS.map((m) => (
            <button type="button"
              key={m.key}
              onClick={() => setBrush(m.key)}
              className={`w-full flex items-center gap-2 px-2 py-1 rounded-sm border text-[11px] ${
                brush === m.key ? "border-red-400 bg-red-50 font-semibold" : "border-gray-200 hover:bg-gray-50"
              }`}
            >
              <span className="w-3 h-3 rounded-sm" style={{ background: m.color }} />
              <span className="truncate text-gray-700">{m.label}</span>
            </button>
          ))}
        </div>

        <div
          className="flex-1 overflow-auto rounded-sm border border-gray-300 bg-[#a1866f] p-1 select-none"
          onMouseLeave={() => setPainting(false)}
        >
          <div
            className="grid gap-px"
            style={{ gridTemplateColumns: `repeat(${GRID_COLS}, minmax(14px, 1fr))` }}
          >
            {Array.from({ length: GRID_ROWS }).map((_, y) =>
              Array.from({ length: GRID_COLS }).map((__, x) => {
                const key = cells[`${x},${y}`];
                const mat = key ? materialByKey(key) : null;
                return (
                  <div
                    key={`${x},${y}`}
                    onMouseDown={() => {
                      setPainting(true);
                      paint(x, y);
                    }}
                    onMouseEnter={() => painting && paint(x, y)}
                    onMouseUp={() => setPainting(false)}
                    className="aspect-square cursor-crosshair"
                    style={{ background: mat ? mat.color : "rgba(0,0,0,0.06)" }}
                  />
                );
              })
            )}
          </div>
        </div>
      </div>

      {summary.lines.length > 0 && (
        <div className="mt-3 border-t border-gray-100 pt-2 space-y-1">
          {summary.lines.map((l) => (
            <div key={l.key} className="flex items-center gap-2 text-[11px] text-gray-600">
              <span className="w-2.5 h-2.5 rounded-sm" style={{ background: l.color }} />
              <span className="flex-1">{l.label}</span>
              <span>{sqftLabel(l)}</span>
              <span className="w-16 text-right font-semibold text-gray-800">{costLabel(l.cost)}</span>
            </div>
          ))}
          <div className="flex justify-between text-[12px] font-bold text-gray-900 pt-1">
            <span>Landscape total</span>
            <span className={Number.isFinite(summary.total) ? "" : "text-amber-700"}>{costLabel(summary.total)}</span>
          </div>
        </div>
      )}
    </div>
  );
}

import { Input } from "@/components/ui/input";
import { money } from "./foundationCalc";
import { foundationHasEnginePricing } from "./foundationSellPricing";

export default function CustomerPricingPanel({ cost, project, onChange }) {
  const markup = project.customer_markup_percent || 0;
  const override = project.customer_price_override;
  const marked = cost * (1 + markup / 100);
  const price = override > 0 ? override : marked;
  const margin = price > 0 ? ((price - cost) / price) * 100 : 0;

  // Sell-side precedence (CMP-A10; mirrors sourceProjectEconomics' foundation
  // branch in customerPricing.js): explicit pricing-engine config resolves
  // the live customer price first; absent engine config an applied Markup
  // Tier snapshot (customer_pricing.applied === true with a numeric total)
  // replaces it wholesale; otherwise the manual baseline below wins —
  // customer_price_override > 0 beats cost x (1 + markup %). `price` here is
  // therefore the MANUAL baseline: honest whenever neither upstream layer is
  // engaged, advisory-shadowed otherwise.
  const enginePriced = foundationHasEnginePricing(project);
  const tierTotal = project.customer_pricing?.applied === true && Number.isFinite(Number(project.customer_pricing?.total))
    ? Number(project.customer_pricing.total)
    : null;
  const tierShadowsBaseline = !enginePriced && tierTotal !== null && Math.abs(tierTotal - price) > 0.005;

  return (
    <div className="max-w-xl bg-white rounded-sm border border-gray-200 p-4 space-y-3">
      <div>
        <h3 className="text-[13px] font-bold text-gray-900">Customer Pricing</h3>
        <p className="text-[11px] text-gray-400">
          Internal cost stays private — the customer price below is what flows to the estimate presentation.
        </p>
      </div>

      {enginePriced && (
        <p role="status" className="rounded-sm border border-blue-200 bg-blue-50 px-2 py-1 text-[11px] text-blue-800">
          Pricing-engine configuration on this project resolves the live customer price (precedence: pricing engine → applied tier → price override → markup %). The manual markup/override below still applies to components without engine config.
        </p>
      )}
      {tierShadowsBaseline && (
        <p role="status" className="rounded-sm border border-blue-200 bg-blue-50 px-2 py-1 text-[11px] text-blue-800">
          Applied Tier {project.customer_pricing?.tier_number} pricing ({money(tierTotal)}) is the live customer price — the markup/override below is stored but not used while a tier is applied. Editing either field switches this section back to manual pricing.
        </p>
      )}

      <div className="flex justify-between text-[12px] text-gray-600">
        <span>Internal section cost</span>
        <span className="font-semibold text-gray-900">{money(cost)}</span>
      </div>

      <div className="grid grid-cols-2 gap-3">
        <label className="text-[11px] text-gray-500">
          Markup %
          <Input
            type="number"
            value={markup}
            onChange={(e) => onChange({ customer_markup_percent: parseFloat(e.target.value) || 0 })}
          />
        </label>
        <label className="text-[11px] text-gray-500">
          Price override
          <Input
            type="number"
            value={override ?? ""}
            placeholder="Use markup"
            onChange={(e) => onChange({ customer_price_override: parseFloat(e.target.value) || 0 })}
          />
        </label>
      </div>

      <div className="border-t border-gray-100 pt-3 space-y-1 text-[12px]">
        <div className="flex justify-between text-gray-600">
          <span>Markup amount</span>
          <span>{money(marked - cost)}</span>
        </div>
        <div className="flex justify-between text-gray-600">
          <span>Gross margin</span>
          <span>{margin.toFixed(1)}%</span>
        </div>
        {/* O-096: when the applied tier is the live sell, the acknowledged
            margin pair comes straight from the customer_pricing snapshot
            fields (total vs raw_subtotal) — never recomputed from the manual
            baseline it shadows. */}
        {tierShadowsBaseline && Number.isFinite(Number(project.customer_pricing?.raw_subtotal)) && (
          <div className="flex justify-between text-blue-700">
            <span>Tier {project.customer_pricing?.tier_number} snapshot margin (acknowledged)</span>
            <span>
              {money(tierTotal - Number(project.customer_pricing.raw_subtotal))}
              {tierTotal > 0 ? ` · ${(((tierTotal - Number(project.customer_pricing.raw_subtotal)) / tierTotal) * 100).toFixed(1)}%` : ""}
            </span>
          </div>
        )}
        <div className="flex justify-between text-[14px] font-bold text-gray-900 pt-1">
          <span>Customer price</span>
          <span className="text-red-700">{money(price)}</span>
        </div>
      </div>
    </div>
  );
}

import React, { useEffect, useMemo, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Label } from "@/components/ui/label";
import { TrendingUp, Info } from "lucide-react";
import { applyMarkups, parseVolumeDiscountBrackets, parseVolumeDiscountCategories } from "./markupEngine";
import { loadCustomerPricingConfig } from "./savedCustomerPricing";
import TierBadge, { getTierTheme } from "./TierBadge";

const fmt = (n) => "$" + (Number(n) || 0).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });

/**
 * Reusable Customer Pricing Summary tab for every estimator.
 *
 * Props:
 *   project      — the in-memory project object with totals
 *   categorize   — function(project) => [{ module, label, cost, category_key }]
 *   accentColor  — tailwind color name (purple, red, green, blue, orange) for the header
 *   onTierChange — optional callback. When provided, selected tier becomes the Builder's saved tier on next save.
 *   onApplyTier  — optional explicit-apply callback for Builders that already have a working manual pricing mode.
 */
export default function CustomerPricingTab({ project, categorize, accentColor = "slate", onTierChange, onApplyTier }) {
  const [tiers, setTiers] = useState([]);
  const [categories, setCategories] = useState([]);
  const [settings, setSettings] = useState([]);
  const [tierNumber, setTierNumber] = useState(1);
  const [customerDefaultTier, setCustomerDefaultTier] = useState(1);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState("");

  useEffect(() => {
    let active = true;
    (async () => {
      if (active) {
        setLoading(true);
        setLoadError("");
      }
      try {
        const config = await loadCustomerPricingConfig(project);
        if (!active) return;
        setTiers(config.tiers || []);
        setCategories(config.categories || []);
        setSettings(config.settings || []);
        setCustomerDefaultTier(Number(config.customer?.pricing_tier) || 1);
        setTierNumber(Number(config.defaultTierNumber) || 1);
      } catch (e) {
        console.error("CustomerPricingTab load error:", e);
        if (active) setLoadError(e?.message || "Customer pricing configuration could not be verified.");
      }
      if (active) setLoading(false);
    })();
    return () => { active = false; };
  }, [project?.customer_id]);

  useEffect(() => {
    const savedTier = Number(project?.customer_pricing?.tier_number || project?.customer_pricing_tier);
    if (savedTier > 0 && tiers.some((tier) => Number(tier.tier_number) === savedTier)) {
      setTierNumber(savedTier);
    }
  }, [project?.customer_pricing?.tier_number, project?.customer_pricing_tier, tiers]);

  const selectedTier = useMemo(
    () => tiers.find((t) => t.tier_number === Number(tierNumber)) || tiers[0],
    [tiers, tierNumber]
  );

  const lines = useMemo(() => {
    try {
      return categorize(project) || [];
    } catch (e) {
      console.error("categorize error:", e);
      return [];
    }
  }, [project, categorize]);

  const markupResult = useMemo(() => {
    const brackets = parseVolumeDiscountBrackets(settings);
    const eligibleCategoryKeys = parseVolumeDiscountCategories(settings);
    const categoryFlags = Object.fromEntries(
      (categories || []).map((c) => [c?.category_key, c?.volume_discount_eligible]).filter(([k]) => k),
    );
    return applyMarkups(lines, selectedTier, { brackets, eligibleCategoryKeys, categoryFlags });
  }, [lines, selectedTier, settings, categories]);

  const categoryNameByKey = useMemo(
    () => Object.fromEntries(categories.map((c) => [c.category_key, c.category_name])),
    [categories]
  );

  // Group lines by category for display
  const byCategory = useMemo(() => {
    const map = {};
    markupResult.lines.forEach((l) => {
      const key = l.category_key;
      if (!map[key]) {
        map[key] = { name: categoryNameByKey[key] || key, lines: [], rawTotal: 0, finalTotal: 0 };
      }
      map[key].lines.push(l);
      map[key].rawTotal += l.cost;
      map[key].finalTotal += l.final_cost;
    });
    return map;
  }, [markupResult, categoryNameByKey]);

  const theme = getTierTheme(tierNumber);

  if (loading) {
    return (
      <Card className="bg-white border-0 shadow-sm">
        <CardContent className="p-8 text-center text-slate-500">Loading pricing tiers…</CardContent>
      </Card>
    );
  }

  if (loadError) {
    return (
      <Card className="bg-red-50 border-red-200">
        <CardContent className="p-6 text-sm text-red-900">
          <div className="flex items-start gap-2">
            <Info className="w-4 h-4 mt-0.5 flex-shrink-0" />
            <div>
              <p className="font-medium mb-1">Customer pricing unavailable</p>
              <p className="text-xs">{loadError}</p>
              <p className="text-xs mt-1">Tier-based customer pricing is not treated as missing or recalculated from fallback configuration while these pricing records cannot be verified.</p>
            </div>
          </div>
        </CardContent>
      </Card>
    );
  }

  if (tiers.length === 0) {
    return (
      <Card className="bg-amber-50 border-amber-200">
        <CardContent className="p-6 text-sm text-amber-900">
          <div className="flex items-start gap-2">
            <Info className="w-4 h-4 mt-0.5 flex-shrink-0" />
            <div>
              <p className="font-medium mb-1">No pricing tiers configured</p>
              <p className="text-xs">
                Visit <span className="font-semibold">Admin → Markups</span> to set up tier markups before using this view.
              </p>
            </div>
          </div>
        </CardContent>
      </Card>
    );
  }

  if (lines.length === 0) {
    return (
      <Card className="bg-white border-0 shadow-sm">
        <CardContent className="p-8 text-center text-slate-500 text-sm">
          Add items to the project to see customer pricing.
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-4">
      {/* Tier selector */}
      <Card className="bg-white border-0 shadow-sm">
        <CardHeader className="pb-3">
          <CardTitle className="text-lg flex items-center gap-2">
            <TrendingUp className={`w-5 h-5 text-${accentColor}-600`} />
            Customer Pricing Summary
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-3">
          <div className="flex flex-wrap items-end gap-4">
            <div className="min-w-[260px] flex-1">
              <Label className="text-xs mb-1.5 block">Pricing Tier</Label>
              <Select
                value={String(tierNumber)}
                onValueChange={(v) => {
                  const nextTier = Number(v);
                  setTierNumber(nextTier);
                  onTierChange?.(nextTier);
                }}
              >
                <SelectTrigger className="h-10">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {tiers.map((t) => (
                    <SelectItem key={t.id} value={String(t.tier_number)}>
                      Tier {t.tier_number} — {t.tier_name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className={`flex items-center gap-3 px-4 py-2 rounded-xl ${theme.soft} ${theme.softText} border ${theme.accent}`}>
              <TierBadge tierNumber={tierNumber} />
              <div>
                <p className="text-xs opacity-75">Selected Tier</p>
                <p className="font-semibold text-sm">{selectedTier?.tier_name || `Tier ${tierNumber}`}</p>
              </div>
              {onApplyTier && (
                <button
                  type="button"
                  onClick={() => onApplyTier(tierNumber)}
                  className="ml-auto h-8 px-3 rounded border border-current/25 bg-white/80 text-xs font-semibold hover:bg-white"
                >
                  Use Tier {tierNumber}
                </button>
              )}
            </div>
          </div>
          {selectedTier?.description && (
            <p className="text-xs text-slate-500 italic">{selectedTier.description}</p>
          )}
        </CardContent>
      </Card>

      {/* Cost breakdown by category */}
      <Card className="bg-white border-0 shadow-sm">
        <CardHeader className="pb-3">
          <CardTitle className="text-base">Marked-Up Breakdown by Category</CardTitle>
        </CardHeader>
        <CardContent className="overflow-x-auto p-0">
          <table className="w-full text-sm">
            <thead className="bg-slate-50 text-slate-600 text-xs">
              <tr>
                <th className="text-left px-4 py-2 font-medium">Description</th>
                <th className="text-right px-4 py-2 font-medium">Cost</th>
                <th className="text-right px-4 py-2 font-medium">Markup</th>
                <th className="text-right px-4 py-2 font-medium">Vol Disc</th>
                <th className="text-right px-4 py-2 font-medium">Customer Price</th>
              </tr>
            </thead>
            <tbody>
              {Object.entries(byCategory).map(([catKey, group]) => (
                <React.Fragment key={catKey}>
                  <tr className="bg-slate-100/70">
                    <td colSpan={5} className="px-4 py-2 font-semibold text-slate-700 text-xs uppercase tracking-wide">
                      {group.name}
                      <span className="ml-2 text-slate-500 font-normal normal-case tracking-normal">
                        — {fmt(group.rawTotal)} cost → <span className="font-semibold text-slate-700">{fmt(group.finalTotal)}</span>
                      </span>
                    </td>
                  </tr>
                  {group.lines.map((l, i) => (
                    <tr key={`${catKey}-${i}`} className="border-t border-slate-100 hover:bg-slate-50/50">
                      <td className="px-4 py-2">{l.label}</td>
                      <td className="px-4 py-2 text-right tabular-nums text-slate-500">{fmt(l.cost)}</td>
                      <td className="px-4 py-2 text-right tabular-nums">
                        {(l.markup_multiplier * 100).toFixed(1)}%
                      </td>
                      <td className="px-4 py-2 text-right tabular-nums">
                        {l.volume_discount_applied > 0 ? `${l.volume_discount_applied}%` : "—"}
                      </td>
                      <td className="px-4 py-2 text-right tabular-nums font-semibold">{fmt(l.final_cost)}</td>
                    </tr>
                  ))}
                </React.Fragment>
              ))}
            </tbody>
          </table>
        </CardContent>
      </Card>

      {/* Grand total card */}
      <Card className={`border-2 ${theme.accent} ${theme.soft}`}>
        <CardContent className="p-5 space-y-2">
          <div className="flex justify-between text-sm text-slate-600">
            <span>Internal cost subtotal</span>
            <span className="tabular-nums">{fmt(markupResult.totals.raw_subtotal)}</span>
          </div>
          <div className="flex justify-between text-sm text-slate-600">
            <span>After Tier {tierNumber} markup</span>
            <span className="tabular-nums">{fmt(markupResult.totals.marked_subtotal)}</span>
          </div>
          {markupResult.totals.volume_discount_pct > 0 && (
            <div className="flex justify-between text-sm text-amber-700">
              <span>Volume discount ({markupResult.totals.volume_discount_pct}%)</span>
              <span className="tabular-nums">
                −{fmt(markupResult.totals.marked_subtotal - markupResult.totals.grand_total)}
              </span>
            </div>
          )}
          <div className={`border-t pt-2 flex justify-between items-center ${theme.softText}`}>
            <span className="text-lg font-bold">Customer Price</span>
            <span className="text-2xl font-bold tabular-nums">{fmt(markupResult.totals.grand_total)}</span>
          </div>
          {markupResult.totals.raw_subtotal > 0 && (
            <p className="text-xs text-slate-500 pt-1">
              Margin: <span className="font-semibold">{fmt(markupResult.totals.grand_total - markupResult.totals.raw_subtotal)}</span>
              {" "}({(((markupResult.totals.grand_total - markupResult.totals.raw_subtotal) / markupResult.totals.grand_total) * 100).toFixed(1)}% of customer price)
            </p>
          )}
        </CardContent>
      </Card>

      <Card className="bg-blue-50 border-blue-200">
        <CardContent className="p-3 text-xs text-blue-900 flex items-start gap-2">
          <Info className="w-4 h-4 flex-shrink-0 mt-0.5" />
          <span>
            Markups and volume discount brackets are configured in <strong>Admin → Markups</strong>.
            {onTierChange ? (
              <> Tier {tierNumber} will be saved with this Builder the next time you save it. Customer default: Tier {customerDefaultTier}.</>
            ) : onApplyTier ? (
              <> Preview tiers freely, then choose <strong>Use Tier {tierNumber}</strong> to replace this Builder's manual sell-price mode. Customer default: Tier {customerDefaultTier}.</>
            ) : (
              <> This view is currently preview-only.</>
            )}
          </span>
        </CardContent>
      </Card>
    </div>
  );
}

import { base44 } from "@/api/base44Client";
import { applyMarkups, parseVolumeDiscountBrackets, parseVolumeDiscountCategories } from "./markupEngine";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";

const num = (value, fallback = 0) => Number.isFinite(Number(value)) ? Number(value) : fallback;

function resolveTierNumber({ project, customer, requestedTierNumber, tiers }) {
  const candidates = [
    requestedTierNumber,
    project?.customer_pricing?.tier_number,
    project?.customer_pricing_tier,
    customer?.pricing_tier,
    1,
  ];
  for (const candidate of candidates) {
    const tierNumber = num(candidate, NaN);
    if (Number.isFinite(tierNumber) && (tiers || []).some((tier) => num(tier.tier_number) === tierNumber)) {
      return tierNumber;
    }
  }
  return num(tiers?.[0]?.tier_number, 1);
}

const isNotFoundError = (error) => Number(error?.response?.status || error?.status || error?.statusCode || 0) === 404;

export async function loadCustomerPricingConfig(project = {}) {
  try {
    const [tiers, categories, settings, customer] = await Promise.all([
      // Tier definitions and pricing Settings directly change customer selling
      // price, so a read failure must never masquerade as "not configured".
      loadAllEntityRows({ entity: base44.entities.MarkupTier, sort: "sort_order", label: "Customer pricing markup tiers" }),
      // Category records only provide display labels; pricing lines already carry
      // their category keys, so this metadata may remain non-blocking.
      loadAllEntityRows({ entity: base44.entities.MarkupCategory, sort: "sort_order", label: "Customer pricing markup categories" }).catch(() => []),
      loadAllEntityRows({ entity: base44.entities.Settings, query: { category: "pricing" }, sort: null, label: "Customer pricing settings" }),
      project?.customer_id
        ? base44.entities.Customer.get(project.customer_id).catch((error) => {
            // Preserve legacy projects whose historical Customer record no longer
            // exists, but fail closed on permission/network/service read errors.
            if (isNotFoundError(error)) return null;
            throw error;
          })
        : Promise.resolve(null),
    ]);

    const defaultTierNumber = resolveTierNumber({ project, customer, tiers });
    return { tiers: tiers || [], categories: categories || [], settings: settings || [], customer, defaultTierNumber };
  } catch (error) {
    throw new Error(`Customer pricing configuration could not be verified: ${error?.message || "unknown read error"}`);
  }
}

export function calculateCustomerPricingFromConfig({ project, categorize, tierNumber, tiers = [], settings = [], customer = null, categories = [] }) {
  if (!project || typeof categorize !== "function" || !tiers.length) return null;
  const resolvedTierNumber = resolveTierNumber({ project, customer, requestedTierNumber: tierNumber, tiers });
  const selectedTier = tiers.find((tier) => num(tier.tier_number) === resolvedTierNumber) || tiers[0];
  const lines = categorize(project) || [];
  if (!selectedTier || !lines.length) return null;

  const categoryFlags = Object.fromEntries(
    (categories || []).map((c) => [c?.category_key, c?.volume_discount_eligible]).filter(([k]) => k),
  );
  const result = applyMarkups(lines, selectedTier, {
    brackets: parseVolumeDiscountBrackets(settings),
    eligibleCategoryKeys: parseVolumeDiscountCategories(settings),
    categoryFlags,
  });

  return {
    applied: true,
    tier_number: num(selectedTier.tier_number, resolvedTierNumber),
    tier_name: selectedTier.tier_name || `Tier ${resolvedTierNumber}`,
    tier_updated_date: String(selectedTier?.updated_date || ""),
    customer_default_tier: num(customer?.pricing_tier, 1),
    raw_subtotal: num(result?.totals?.raw_subtotal),
    marked_subtotal: num(result?.totals?.marked_subtotal),
    eligible_subtotal: num(result?.totals?.eligible_subtotal),
    volume_discount_pct: num(result?.totals?.volume_discount_pct),
    total: num(result?.totals?.grand_total),
    saved_at: new Date().toISOString(),
    lines: (result?.lines || []).map((line) => ({
      module: line.module || "",
      label: line.label || "",
      category_key: line.category_key || "",
      cost: num(line.cost),
      markup_multiplier: num(line.markup_multiplier, 1),
      marked_up_cost: num(line.marked_up_cost),
      volume_discount_applied: num(line.volume_discount_applied),
      final_cost: num(line.final_cost),
    })),
  };
}

export async function calculateSavedCustomerPricing({ project, categorize, tierNumber }) {
  const config = await loadCustomerPricingConfig(project);
  return calculateCustomerPricingFromConfig({
    project,
    categorize,
    tierNumber,
    tiers: config.tiers,
    settings: config.settings,
    customer: config.customer,
    categories: config.categories,
  });
}

import { assertEstimateProductMutationAllowed } from "@/components/estimator/estimateMutationGuard";
import { staffEntities } from "@/components/staff/staffEntities";

// String fields can differ only by stray or repeated whitespace; normalize
// whitespace (but not case) so stored rows match their intended patches.
const cleanString = (value) => String(value ?? "").trim().replace(/\s+/g, " ");

function normalize(value) {
  if (Array.isArray(value)) return value.map(normalize);
  if (!value || typeof value !== "object") return value;
  return Object.keys(value).sort().reduce((out, key) => {
    // Values compared here are individual patch fields, not whole entity rows.
    // Preserve nested ids and metadata because they can be substantive Builder
    // item identity inside arrays/objects.
    out[key] = normalize(value[key]);
    return out;
  }, {});
}

function sameValue(a, b) {
  if (a !== null && a !== undefined && a !== "" && b !== null && b !== undefined && b !== "") {
    if (Number.isFinite(Number(a)) && Number.isFinite(Number(b))) {
      return Math.abs(Number(a) - Number(b)) <= 0.000001;
    }
  }
  if (typeof a === "string" && typeof b === "string") {
    return cleanString(a) === cleanString(b);
  }
  return JSON.stringify(normalize(a)) === JSON.stringify(normalize(b));
}

export function sourcePatchMatches(record, patch) {
  if (!record || !patch) return false;
  return Object.entries(patch).every(([key, value]) => sameValue(record?.[key], value));
}

export async function preflightBuilderSourceMutation({ estimateId = "" } = {}) {
  if (!estimateId) return null;
  const estimate = await staffEntities.AllInOneEstimate.get(estimateId);
  if (!estimate?.id) throw new Error("Estimate could not be verified before saving this Builder source.");
  await assertEstimateProductMutationAllowed(estimate);
  return estimate;
}

export async function updateBuilderSourceProject({
  entity,
  sourceId,
  expectedUpdatedAt,
  data,
  estimateId = "",
  label = "Builder source project",
}) {
  if (!entity?.updateMany || !entity?.get || !sourceId) {
    throw new Error(`${label} could not initialize its concurrency-safe update.`);
  }
  const expected = String(expectedUpdatedAt || "").trim();
  if (!expected) {
    throw new Error(`${label} is missing its loaded version. Reload it before saving.`);
  }

  await preflightBuilderSourceMutation({ estimateId });

  const verified = (record) => !!record && record.id === sourceId
    && typeof record.updated_date === "string" && record.updated_date.length > 0
    && sourcePatchMatches(record, data);
  const conflict = () => new Error(`${label} changed in another session. Reload it before saving.`);

  let result;
  try {
    result = await entity.updateMany(
      { id: sourceId, updated_date: expected },
      { $set: data },
    );
  } catch (error) {
    const current = await entity.get(sourceId).catch(() => null);
    if (verified(current)) return current;
    throw error;
  }

  if (!result || !Number.isInteger(result.updated) || (result.updated !== 0 && result.updated !== 1)) {
    throw new Error(`${label} conditional-update result could not be verified.`);
  }

  if (result.updated === 1) {
    const saved = await entity.get(sourceId).catch(() => null);
    if (!saved) throw new Error(`${label} was updated but could not be re-read.`);
    if (!verified(saved)) throw conflict();
    return saved;
  }

  const current = await entity.get(sourceId).catch(() => null);
  if (verified(current)) {
    // Exact retry after a lost successful response. Do not rewrite the row merely
    // to refresh its timestamp; reuse the already-persisted intended state.
    return current;
  }

  throw conflict();
}

const CONFLICT_RE = /409|conflict|changed by another|changed in another session/i;

function classify(error) {
  const msg = String(error && (error.message || error) || '');
  if (CONFLICT_RE.test(msg) || error?.status === 409 || error?.code === 409) return 'conflict';
  return 'failed';
}

export function createFoundationSaveSession() {
  let inFlight = null;

  const run = ({ sourceId, editRevision, getCurrent, saveSource, syncBuilder }) => {
    if (inFlight) return inFlight;
    const attempt = Promise.resolve().then(async () => {
      const warnings = [];
      const base = { sourceId, sourceVersion: null, savedEditRevision: editRevision, sourceSaved: false, builderSync: 'not_required', error: null, warnings };
      const isCurrent = () => {
        try {
          const c = getCurrent() || {};
          return c.sourceId === sourceId && c.editRevision === editRevision && c.loaded === true;
        } catch { return false; }
      };
      if (!isCurrent()) return { ...base, status: 'superseded' };
      let savedProject;
      try {
        savedProject = await saveSource();
      } catch (error) {
        // conflictDetected marks a REAL classified concurrent-edit conflict
        // (CAS moved under the save) — distinct from the local 'conflict'
        // outcomes the page synthesizes for its draft-pending/reload gates, so
        // the merge-conflict dialog opens only for genuine source divergence.
        const cls = classify(error);
        return { ...base, status: isCurrent() ? cls : 'superseded', error, ...(cls === 'conflict' ? { conflictDetected: true } : {}) };
      }
      if (!savedProject || savedProject.id !== sourceId || typeof savedProject.updated_date !== 'string' || !savedProject.updated_date) {
        const error = new Error('Source save returned an unverified record.');
        const cls = classify(error);
        return { ...base, status: isCurrent() ? cls : 'superseded', error, ...(cls === 'conflict' ? { conflictDetected: true } : {}) };
      }
      base.sourceSaved = true;
      base.sourceVersion = savedProject.updated_date;
      if (!isCurrent()) {
        return { ...base, status: 'superseded', builderSync: syncBuilder ? 'pending' : 'not_required' };
      }
      if (syncBuilder) {
        try {
          await syncBuilder(savedProject);
          base.builderSync = 'synced';
        } catch (error) {
          base.builderSync = 'pending';
          base.error = error;
          warnings.push('builder_sync_failed');
          return { ...base, status: isCurrent() ? 'partial' : 'superseded' };
        }
      }
      return { ...base, status: isCurrent() ? 'saved' : 'superseded' };
    });
    const shared = attempt.finally(() => { if (inFlight === shared) inFlight = null; });
    inFlight = shared;
    return shared;
  };

  return { run, isSaving: () => inFlight !== null };
}

// Pure unsent browser-tab draft recovery for the foundation estimator.
// Owns sessionStorage envelope read/write/CAS-clear only — no page/router/auth logic.
export const FOUNDATION_DRAFT_FIELDS = [
  "project_name", "notes", "assembly_schema_version",
  "items", "walls", "poles", "wall_caps", "signage_cabinets", "selected_equipment", "landscape",
  "project_concrete_type", "project_concrete_admixtures", "excavation_method", "selected_concrete_id",
  "ai_engineering_recommendation", "ai_engineering_data",
  // O-104/O-105 — design-basis + site/hazard capture blocks.
  "design_basis", "site_hazard",
  // Customer Pricing tab surface — markup %, manual price override, and the
  // applied-tier record (applied/tier_number). Persisted by payload(); restored
  // verbatim through the assembly normalizer's passthrough.
  "customer_markup_percent", "customer_price_override", "customer_pricing",
  "concrete_cost_per_cy", "rebar_cost_per_ft",
  "forming_materials_cost_spread_foot", "forming_materials_cost_pillar",
  "min_excavation_time_hours",
  "hand_dig_excavation_cost_per_cy", "equipment_excavation_cost_per_cy",
  "forming_labor_rate", "pouring_labor_rate", "finishing_labor_rate",
  "hand_dig_labor_rate", "equipment_excavation_labor_rate",
];

const KEY_PREFIX = "ccs:foundation-draft:v1:";
const MAX_CHARS = 1_000_000;
const ASSEMBLY_ARRAYS = ["items", "walls", "poles", "wall_caps", "signage_cabinets", "selected_equipment"];

const validId = (v) => typeof v === "string" && v.trim().length > 0 && v.length <= 256;
const isPlain = (v) => {
  if (!v || typeof v !== "object" || Array.isArray(v)) return false;
  const p = Object.getPrototypeOf(v);
  return p === Object.prototype || p === null;
};
const keyFor = (ownerId, sourceId, estimateId) =>
  KEY_PREFIX + encodeURIComponent(JSON.stringify([ownerId, sourceId, estimateId ?? null]));

// Deep clone that REJECTS unsupported shapes; undefined props omitted (JSON semantics).
const cloneChecked = (value, seen = new Set(), inArray = false) => {
  if (value === undefined) { if (inArray) throw new Error("Undefined array entry in draft data."); return undefined; }
  if (value === null) return null;
  const t = typeof value;
  if (t === "number") { if (!Number.isFinite(value)) throw new Error("Non-finite number in draft data."); return value; }
  if (t === "string" || t === "boolean") return value;
  if (t !== "object") throw new Error(`Unsupported draft value type: ${t}`);
  if (seen.has(value)) throw new Error("Cycle in draft data.");
  if (Array.isArray(value)) {
    seen.add(value);
    const out = Array.from(value, v => cloneChecked(v, seen, true));
    seen.delete(value);
    return out;
  }
  if (!isPlain(value)) throw new Error("Non-plain object in draft data (Date/Map/class instance not supported).");
  seen.add(value);
  const entries = [];
  for (const [k, v] of Object.entries(value)) {
    const c = cloneChecked(v, seen, false);
    if (c !== undefined) entries.push([k, c]);
  }
  seen.delete(value);
  return Object.fromEntries(entries);
};

const checkAssembly = (data) => {
  for (const f of ASSEMBLY_ARRAYS) {
    if (f in data && !Array.isArray(data[f])) return `${f} must be an array.`;
    if (Array.isArray(data[f])) for (const r of data[f]) if (!isPlain(r)) return `${f} must contain plain records.`;
  }
  if (data.customer_pricing !== undefined && !isPlain(data.customer_pricing))
    return "customer_pricing must be a record.";
  if (data.assembly_schema_version !== undefined && data.assembly_schema_version !== 1)
    return `Unsupported assembly_schema_version: ${data.assembly_schema_version}`;
  return null;
};

const pickDraft = (project) => {
  const entries = [];
  for (const field of FOUNDATION_DRAFT_FIELDS) {
    if (!Object.hasOwn(project, field)) continue; // own-property only — no inherited fields
    const v = cloneChecked(project[field]);
    if (v !== undefined) entries.push([field, v]);
  }
  return Object.fromEntries(entries);
};

const validEnvelope = (raw, ownerId, sourceId, estimateId) => {
  let env;
  try { env = JSON.parse(raw); } catch { return { ok: false, message: "Stored draft is not valid JSON." }; }
  if (!isPlain(env)) return { ok: false, message: "Stored draft is not a record." };
  if (env.version !== 1) return { ok: false, message: "Unsupported draft version." };
  if (env.ownerId !== ownerId || env.sourceId !== sourceId || (env.estimateId ?? null) !== (estimateId ?? null))
    return { ok: false, message: "Stored draft context does not match." };
  if (!validId(env.token)) return { ok: false, message: "Missing draft token." };
  if (!validId(env.baseUpdatedAt)) return { ok: false, message: "Missing base revision." };
  if (typeof env.savedAt !== "string" || !Number.isFinite(Date.parse(env.savedAt))) return { ok: false, message: "Invalid savedAt timestamp." };
  // A loss marker is a small tombstone written when a draft could not be
  // stored (quota/size). It carries no data; read() surfaces it as invalid so
  // the page warns and offers Discard instead of losing the draft silently.
  if (env.draftLost === true) return { ok: true, env, lost: true };
  if (!isPlain(env.data)) return { ok: false, message: "Draft data missing." };
  const bad = checkAssembly(env.data);
  if (bad) return { ok: false, message: bad };
  let data;
  try { data = pickDraft(env.data); } catch (e) { return { ok: false, message: String(e.message || e) }; }
  return { ok: true, env, data };
};

export function createFoundationDraftStore({ getStorage, ownerId, sourceId, estimateId = null }) {
  const unavailable = (msg) => ({ status: "unavailable", message: msg });
  const noAccess = () => ({ read: () => unavailable("No valid draft identity for this owner/source."), write: () => unavailable("No valid draft identity for this owner/source."), clear: () => unavailable("No valid draft identity for this owner/source.") });
  if (typeof getStorage !== "function") return noAccess();
  if (!validId(ownerId) || !validId(sourceId) || (estimateId !== null && !validId(estimateId))) return noAccess();
  const key = keyFor(ownerId, sourceId, estimateId);
  const storage = () => {
    try {
      const s = getStorage();
      if (!s || typeof s.getItem !== "function" || typeof s.setItem !== "function" || typeof s.removeItem !== "function")
        return { __err: "Storage provider returned no session storage." };
      return s;
    } catch (e) { return { __err: String(e.message || e) }; }
  };
  const getItem = (s) => { try { return { raw: s.getItem(key) }; } catch (e) { return { err: `Draft read failed: ${e.message || e}` }; } };

  const read = () => {
    const s = storage();
    if (s.__err) return unavailable(`Draft storage unavailable: ${s.__err}`);
    const got = getItem(s);
    if (got.err) return unavailable(got.err);
    if (got.raw === null || got.raw === undefined) return { status: "empty" };
    if (got.raw.length > MAX_CHARS) return { status: "invalid", revision: got.raw, message: "Stored draft exceeds size limit." };
    const v = validEnvelope(got.raw, ownerId, sourceId, estimateId);
    if (!v.ok) return { status: "invalid", revision: got.raw, message: v.message };
    if (v.lost) return { status: "invalid", revision: got.raw, savedAt: v.env.savedAt, baseUpdatedAt: v.env.baseUpdatedAt, message: `A browser draft (saved ${v.env.savedAt}) could not be kept — the browser's per-tab storage refused to store it. Nothing was restored; the saved project is unchanged.` };
    return { status: "found", revision: got.raw, draft: v.data, savedAt: v.env.savedAt, baseUpdatedAt: v.env.baseUpdatedAt, token: v.env.token };
  };

  const write = ({ project, baseUpdatedAt, token, savedAt, expectedRevision }) => {
    const s = storage();
    if (s.__err) return unavailable(`Draft storage unavailable: ${s.__err}`);
    try {
      if (!isPlain(project)) return { status: "invalid", message: "Draft needs a plain project record." };
      if (project.id !== sourceId) return { status: "invalid", message: `Draft project.id must equal sourceId (${sourceId}).` };
      if (!validId(token)) return { status: "invalid", message: "Draft token must be a nonempty string." };
      if (!validId(baseUpdatedAt)) return { status: "invalid", message: "baseUpdatedAt must be a nonempty string." };
      if (typeof savedAt !== "string" || !Number.isFinite(Date.parse(savedAt))) return { status: "invalid", message: "savedAt must be a valid ISO timestamp string." };
      const data = pickDraft(project);
      const bad = checkAssembly(data);
      if (bad) return { status: "invalid", message: bad };
      const envelope = { version: 1, ownerId, sourceId, estimateId: estimateId ?? null, token, baseUpdatedAt, savedAt, data };
      const serialized = JSON.stringify(envelope);
      const got = getItem(s);
      if (got.err) return unavailable(got.err);
      // Graceful-loss marker: when nothing is stored and a write cannot land
      // (size cap or quota throw), leave a small tombstone so the next open
      // warns and offers Discard instead of losing the draft silently. Never
      // clobber an existing stored draft — it is always more valuable.
      const leaveLossMarker = (bytes) => {
        try {
          const cur = getItem(s);
          if (cur.err || (cur.raw !== null && cur.raw !== undefined)) return false;
          const marker = JSON.stringify({ version: 1, ownerId, sourceId, estimateId: estimateId ?? null, token, baseUpdatedAt, savedAt, draftLost: true, droppedBytes: bytes });
          if (marker.length > MAX_CHARS) return false;
          s.setItem(key, marker);
          return true;
        } catch { return false; }
      };
      if (serialized.length > MAX_CHARS) {
        const marked = leaveLossMarker(serialized.length);
        return { status: "invalid", message: got.raw !== null && got.raw !== undefined
          ? "Draft exceeds 1,000,000 character limit; previous draft retained."
          : `Draft exceeds 1,000,000 character limit.${marked ? " A loss marker was stored so reopening this tab warns." : ""}` };
      }
      if ((got.raw ?? null) !== (expectedRevision ?? null))
        return { status: "conflict", revision: got.raw ?? undefined, message: "Draft changed since expected revision; existing draft retained." };
      try { s.setItem(key, serialized); } catch (e) {
        const marked = leaveLossMarker(serialized.length);
        const suffix = marked ? " A loss marker was stored so reopening this tab warns."
          : (got.raw !== null && got.raw !== undefined ? " The previously stored draft was retained." : "");
        return unavailable(`Draft write failed: ${e.message || e}${suffix}`);
      }
      return { status: "stored", revision: serialized, draft: data };
    } catch (e) { return { status: "invalid", message: String(e.message || e) }; }
  };

  const clear = (expectedRevision) => {
    const s = storage();
    if (s.__err) return unavailable(`Draft storage unavailable: ${s.__err}`);
    const got = getItem(s);
    if (got.err) return unavailable(got.err);
    if (got.raw === null || got.raw === undefined) return { status: "removed" };
    if (got.raw !== expectedRevision) return { status: "retained", message: "Draft changed since expected revision; retained." };
    try { s.removeItem(key); } catch (e) { return unavailable(`Draft clear failed: ${e.message || e}`); }
    return { status: "removed" };
  };

  return { read, write, clear };
}

// ---------------------------------------------------------------------------
// Draft ↔ saved-source merge-conflict model (CMP-A04 tail).
// Pure comparison/summary helpers only — no storage, page, router, or entity
// logic. The dialog renders what each side holds; the store keeps its
// write/CAS-clear contract so a resolution never silently drops either side.
//
// Semantics that shape the model:
//   * A draft envelope anchors to the saved revision it was written against
//     (env.baseUpdatedAt). When that anchor no longer equals the record's
//     current updated_date, a concurrent save moved underneath the draft —
//     that is the only divergent-base signal a browser tab can ever see.
//   * Draft restore is an OVERLAY through the page's commit path
//     ({...current, ...draft}): fields the draft never recorded keep the
//     current editor values, so "saved has it, draft lacks it" is a
//     keep-saved-by-omission field — displayed, never counted as a conflict.
//   * There is no true three-way merge: the envelope stores the base revision
//     STRING, not the base content, so "who changed" cannot be proven per
//     field. Resolution choices are therefore honest whole-draft choices:
//     keep-draft (draft fields win on overlay), keep-saved (discard draft),
//     keep-both (saved stays open; the draft is re-anchored as a fresh offer).
// ---------------------------------------------------------------------------

// Same normalize/compare discipline as sourcePatchMatches — key-sorted,
// whitespace-normalized strings, 1e-6 numeric tolerance.
const normalizeDraftValue = (value) => {
  if (Array.isArray(value)) return value.map(normalizeDraftValue);
  if (!value || typeof value !== "object") return value;
  return Object.keys(value).sort().reduce((out, key) => {
    out[key] = normalizeDraftValue(value[key]);
    return out;
  }, {});
};

export function sameFoundationDraftValue(a, b) {
  const emptyA = a === undefined || a === null || a === "";
  const emptyB = b === undefined || b === null || b === "";
  if (emptyA && emptyB) return true;
  if (!emptyA && !emptyB && Number.isFinite(Number(a)) && Number.isFinite(Number(b))) {
    return Math.abs(Number(a) - Number(b)) <= 0.000001;
  }
  if (typeof a === "string" && typeof b === "string") {
    return String(a).trim().replace(/\s+/g, " ") === String(b).trim().replace(/\s+/g, " ");
  }
  return JSON.stringify(normalizeDraftValue(a ?? null)) === JSON.stringify(normalizeDraftValue(b ?? null));
}

