  hand_dig_excavation_cost_per_cy: "Hand-dig excavation $/CY",
  equipment_excavation_cost_per_cy: "Equipment excavation $/CY",
  forming_labor_rate: "Forming labor rate",
  pouring_labor_rate: "Pouring labor rate",
  finishing_labor_rate: "Finishing labor rate",
  hand_dig_labor_rate: "Hand-dig labor rate",
  equipment_excavation_labor_rate: "Equipment excavation labor rate",
};

export function foundationDraftFieldLabel(field) {
  return DRAFT_FIELD_LABELS[field] || field;
}

const clip = (text, max = 56) => {
  const t = String(text);
  return t.length > max ? `${t.slice(0, max - 1)}…` : t;
};

const rowCountLabel = (field, n) => {
  const labels = {
    items: ["foundation item", "foundation items"],
    walls: ["wall", "walls"],
    poles: ["pole", "poles"],
    wall_caps: ["wall cap", "wall caps"],
    signage_cabinets: ["signage cabinet", "signage cabinets"],
    selected_equipment: ["equipment row", "equipment rows"],
    project_concrete_admixtures: ["admixture", "admixtures"],
  };
  const [one, many] = labels[field] || ["row", "rows"];
  return `${n} ${n === 1 ? one : many}`;
};

// Display-safe one-line summary of one side's value for a draft field. Never
// claims equality (the diff row carries that) — this is a shape/size hint so a
// reviewer can tell "3 items" from "2 items" and an applied tier from markup.
export function summarizeFoundationDraftField(field, value) {
  if (value === undefined) return { kind: "absent", text: "—" };
  if (value === null) return { kind: "value", text: "null" };
  if (Array.isArray(value)) return { kind: "rows", count: value.length, text: rowCountLabel(field, value.length) };
  if (typeof value === "object") {
    if (field === "landscape") {
      const cells = value.cells && typeof value.cells === "object" ? Object.keys(value.cells).length : 0;
      return { kind: "record", text: `landscape grid — ${cells} filled ${cells === 1 ? "cell" : "cells"}` };
    }
    if (field === "customer_pricing") {
      if (value.applied === true) {
        const tier = Number.isFinite(Number(value.tier_number)) ? `tier ${value.tier_number}` : "a pricing tier";
        return { kind: "record", text: `Applied ${tier}` };
      }
      return { kind: "record", text: "No tier applied" };
    }
    if (field === "ai_engineering_data") return { kind: "record", text: "AI review note (recorded)" };
    const keys = Object.keys(value).length;
    return { kind: "record", text: `record (${keys} ${keys === 1 ? "field" : "fields"})` };
  }
  if (typeof value === "boolean") return { kind: "value", text: value ? "yes" : "no" };
  return { kind: "value", text: clip(value) };
}

// Per-field diff over FOUNDATION_DRAFT_FIELDS — the union of keys present on
// either side. Status vocabulary:
//   same        — both sides equal (or both absent)
//   diverged    — both present with different values (a real conflict row)
//   draft_only  — draft recorded a value the saved record does not carry
//   saved_only  — saved record carries a value the draft never recorded;
//                 a draft restore OVERLAYS draft fields, so this value is
//                 untouched by either restore choice — displayed for honesty,
//                 never counted toward the conflict
export function diffFoundationDraftFields({ draft, saved }) {
  const safeDraft = isPlain(draft) ? draft : {};
  const safeSaved = isPlain(saved) ? saved : {};
  const rows = [];
  for (const field of FOUNDATION_DRAFT_FIELDS) {
    const hasDraft = Object.hasOwn(safeDraft, field);
    const hasSaved = Object.hasOwn(safeSaved, field);
    if (!hasDraft && !hasSaved) continue;
    const dv = hasDraft ? safeDraft[field] : undefined;
    const sv = hasSaved ? safeSaved[field] : undefined;
    let status;
    if (hasDraft && hasSaved) status = sameFoundationDraftValue(dv, sv) ? "same" : "diverged";
    else status = hasDraft ? "draft_only" : "saved_only";
    rows.push({
      field,
      label: foundationDraftFieldLabel(field),
      status,
      draft: summarizeFoundationDraftField(field, dv),
      saved: summarizeFoundationDraftField(field, sv),
    });
  }
  return rows;
}

// Whole-conflict summary. `saved` is the persisted/acknowledged project record
// (the side a CAS conflict or a moved draft anchor is judged against);
// `baseUpdatedAt`/`draftSavedAt` come off the draft envelope.
// Statuses:
//   in_sync              — anchor matches AND no field differences (draft is the
//                          saved baseline verbatim; nothing to resolve)
//   edits_only           — anchor matches, fields differ (ordinary unsent
//                          edits; the normal offer flow, not a merge conflict)
//   base_moved_identical — anchor stale but content identical to saved; only
//                          the anchor needs rebasing
//   conflict             — anchor stale AND >=1 diverged/draft_only field
//   unverifiable         — a side could not be compared (non-record draft, or
//                          no saved record supplied); the dialog shows what it
//                          can and never diffs blind
export function summarizeFoundationDraftConflict({ draft, saved, baseUpdatedAt = null, draftSavedAt = null } = {}) {
  const savedUpdatedAt = isPlain(saved) && typeof saved.updated_date === "string" ? saved.updated_date : null;
  const baseMoved = !!baseUpdatedAt && !!savedUpdatedAt && baseUpdatedAt !== savedUpdatedAt;
  const base = {
    baseUpdatedAt: baseUpdatedAt ?? null,
    savedUpdatedAt,
    draftSavedAt: draftSavedAt ?? null,
    baseMoved,
  };
  if (!isPlain(draft)) {
    return { ...base, status: "unverifiable", reason: "draft_unreadable", fields: [], counts: { diverged: 0, draftOnly: 0, savedOnly: 0, same: 0 } };
  }
  if (!isPlain(saved)) {
    return { ...base, status: "unverifiable", reason: "saved_unreadable", fields: [], counts: { diverged: 0, draftOnly: 0, savedOnly: 0, same: 0 } };
  }
  const fields = diffFoundationDraftFields({ draft, saved });
  const counts = fields.reduce((acc, row) => {
    if (row.status === "diverged") acc.diverged += 1;
    else if (row.status === "draft_only") acc.draftOnly += 1;
    else if (row.status === "saved_only") acc.savedOnly += 1;
    else acc.same += 1;
    return acc;
  }, { diverged: 0, draftOnly: 0, savedOnly: 0, same: 0 });
  const differs = counts.diverged + counts.draftOnly;
  const status = differs > 0
    ? (baseMoved ? "conflict" : "edits_only")
    : (baseMoved ? "base_moved_identical" : "in_sync");
  return { ...base, status, fields, counts };
}

// True when a conflict summary is a state the user should actively resolve
// rather than pass through the ordinary restore/discard offer.
export function foundationDraftConflictNeedsReview(summary) {
  return ["conflict", "base_moved_identical", "unverifiable"].includes(summary?.status);
}

// Build the project-shaped payload for a "keep both" re-anchor: the draft's
// recorded fields verbatim over the store's required identity. Writing this
// through store.write() re-bases the same draft content onto the CURRENT saved
// revision (baseUpdatedAt = the acknowledged updated_date), converting a
// stale-anchored draft into a fresh draft the reviewer explicitly chose to
// keep — it remains an ordinary restorable offer afterwards.
export function foundationDraftRebaseProject({ draft, sourceId } = {}) {
  if (!isPlain(draft) || !validId(sourceId)) return null;
  return { id: sourceId, ...cloneChecked(draft) };
}

const ARRAYS = ["items", "walls", "poles", "wall_caps", "signage_cabinets"];
const ID_MAX = 200;
const MAX_COLLISIONS = 8;
const UNRESOLVED_PREFIX = "unresolved:";
const UNRESOLVED = {
  foundation: `${UNRESOLVED_PREFIX}legacy-foundation`,
  pole: `${UNRESOLVED_PREFIX}legacy-pole`,
  wall: `${UNRESOLVED_PREFIX}legacy-wall`,
  segment: `${UNRESOLVED_PREFIX}legacy-segment`,
};

const isRecord = (v) => !!v && typeof v === "object" && !Array.isArray(v);
const isId = (v) => typeof v === "string" && v.trim().length > 0 && v.length <= ID_MAX;
const isReserved = (v) => typeof v === "string" && v.startsWith(UNRESOLVED_PREFIX);
const isUnresolvedToken = (v) => Object.values(UNRESOLVED).includes(v);
const deepClone = (v) => (v === undefined ? undefined : JSON.parse(JSON.stringify(v)));
// Preserve a malformed value raw when it cannot be JSON-cloned (functions,
// cycles) — the copy path must not crash on legacy data.
const cloneRawValue = (v) => {
  try { return deepClone(v); } catch { return v; }
};
const cloneNode = (n) => (isRecord(n) ? { ...n } : n);

const fin = (v) => typeof v === "number" && Number.isFinite(v);
const segEndpoints = (shape, i) => {
  const pts = shape?.points;
  if (!Array.isArray(pts) || pts.length < 2) return null;
  const closed = shape?.closed === true && pts.length >= 3;
  const a = pts[i], b = pts[(i + 1) % pts.length];
  if (i >= pts.length || (!closed && i >= pts.length - 1)) return null;
  if (!fin(a?.x) || !fin(a?.z) || !fin(b?.x) || !fin(b?.z)) return null;
  return `${a.x},${a.z}->${b.x},${b.z}`;
};

const legacyIndexOf = (row, keys) => {
  for (const k of keys) {
    const v = row?.[k];
    if (v === null || v === undefined) continue;
    if (v === -1) return { explicit: true };
    if (typeof v === "number" && Number.isInteger(v) && v >= 0) return { index: v };
    if (typeof v === "string" && /^\d+$/.test(v)) return { index: parseInt(v, 10) };
    return { invalid: v };
  }
  return { absent: true };
};

const collectIds = (project) => {
  const ids = new Set();
  const walk = (rows) => (rows || []).forEach((r) => {
    if (isId(r?.component_id)) ids.add(r.component_id);
  });
  ARRAYS.forEach((k) => walk(project?.[k]));
  (project?.walls || []).forEach((w) => walk(w?.shape?.segments));
  (project?.poles || []).forEach((p) => walk(p?.signs));
  return ids;
};

const collectRefs = (project) => {
  const refs = new Set();
  const add = (v) => { if (isId(v)) refs.add(v); };
  (project?.poles || []).forEach((p) => add(p?.foundation_component_id));
  (project?.wall_caps || []).forEach((c) => { add(c?.wall_component_id); add(c?.segment_component_id); });
  (project?.signage_cabinets || []).forEach((c) => { add(c?.foundation_component_id); add(c?.pole_component_id); });
  return refs;
};

const freshId = (createId, kind, used) => {
  for (let i = 0; i < MAX_COLLISIONS; i += 1) {
    const id = createId(kind);
    if (isId(id) && !isReserved(id) && !used.has(id)) { used.add(id); return id; }
  }
  throw new Error(`foundation assembly: could not mint a unique component id for ${kind}`);
};

const validateRef = (v, kind) => {
  if (v === undefined || v === null) return;
  if (typeof v !== "string" || (v !== "" && !isId(v) && !isUnresolvedToken(v))) {
    throw new Error(`foundation assembly: invalid ${kind} reference value`);
  }
};

const ensureNodeId = (row, createId, kind, used, seen) => {
  if (!isRecord(row)) throw new Error(`foundation assembly: ${kind} row must be a record`);
  const n = cloneNode(row);
  const existing = n.component_id;
  if (existing !== undefined && existing !== null) {
    if (!isId(existing) || isReserved(existing)) throw new Error(`foundation assembly: invalid component_id on ${kind} row`);
    if (seen.has(existing)) throw new Error(`foundation assembly: duplicate component_id "${existing}"`);
    seen.add(existing); used.add(existing);
  } else {
    const id = freshId(createId, kind, used);
    n.component_id = id;
    seen.add(id);
  }
  return n;
};

const reserve = (project, previous, used) => {
  const check = (v) => { if (typeof v === "string" && v.length > 0) used.add(v); };
  for (const src of [previous || {}, project || {}]) {
    collectIds(src).forEach((id) => used.add(id));
    collectRefs(src).forEach((id) => used.add(id));
    const kinds = ["items", "walls", "poles", "wall_caps", "signage_cabinets"];
    for (const k of kinds) for (const r of src?.[k] || []) {
      if (!isRecord(r)) throw new Error(`foundation assembly: ${k} row must be a record`);
      for (const [f, kind] of [["foundation_component_id","foundation"],["pole_component_id","pole"],["wall_component_id","wall"],["segment_component_id","segment"]]) validateRef(r[f], kind);
    }
    for (const w of src?.walls || []) for (const s of w?.shape?.segments || []) check(s?.component_id);
    for (const p of src?.poles || []) for (const s of p?.signs || []) check(s?.component_id);
  }
};

const rebuildIndex = (canon, parents) => {
  if (canon === "" || canon === undefined || isUnresolvedToken(canon)) return undefined;
  const i = (parents || []).findIndex((p) => p?.component_id === canon);
  return i >= 0 ? i : undefined;
};

const resolveParent = (canonValue, hasCanon, legacy, incoming, prev, unresolvedToken) => {
  if (hasCanon) {
    if (canonValue === undefined || canonValue === null) return { canon: "", index: undefined };
    if (canonValue === "") return { canon: "", index: undefined };
    if (isUnresolvedToken(canonValue)) return { canon: canonValue, index: undefined, dangling: true, token: true };
    const found = (incoming || []).some((p) => p?.component_id === canonValue);
    return { canon: canonValue, index: found ? rebuildIndex(canonValue, incoming) : undefined, dangling: !found };
  }
  if (legacy.index !== undefined) {
    let canon;
    if (prev) canon = prev[legacy.index]?.component_id;
    else canon = incoming?.[legacy.index]?.component_id;
    if (isId(canon) && (incoming || []).some((p) => p?.component_id === canon)) {
      return { canon, index: rebuildIndex(canon, incoming) };
    }
    if (isId(canon)) return { canon: unresolvedToken, index: undefined, dangling: true, token: true };
    return { canon: unresolvedToken, index: undefined, dangling: true, token: true, outOfRange: true };
  }
  if (legacy.invalid !== undefined) return { canon: unresolvedToken, index: undefined, dangling: true, token: true, invalid: legacy.invalid };
  if (legacy.explicit) return { canon: "", index: undefined };
  return { canon: undefined, index: undefined };
};

const normalizeWalls = (walls, prevWalls, createId, used, seen) => {
  const prevSegIds = new Map();
  (prevWalls || []).forEach((w) => {
    const segs = w?.shape?.segments || [];
    segs.forEach((s, i) => {
      const key = segEndpoints(w?.shape, i);
      if (!isId(s?.component_id) || !key) return;
      const k = `${w.component_id}|${key}`;
      if (prevSegIds.has(k)) prevSegIds.set(k, null);
      else prevSegIds.set(k, s.component_id);
    });
  });
  const out = [];
  for (const w of walls || []) {
    const n = ensureNodeId(w, createId, "wall", used, seen);
    const shape = isRecord(n.shape) ? { ...n.shape } : n.shape;
    const segs = shape?.segments;
    if (segs !== undefined && !Array.isArray(segs)) throw new Error("foundation assembly: wall shape segments must be an array");
    if (Array.isArray(segs)) {
      for (const s of segs) if (!isRecord(s)) throw new Error("foundation assembly: wall shape segments must be records");
      const incomingCount = new Map();
      segs.forEach((s, i) => {
        const key = segEndpoints(shape, i);
        if (key) incomingCount.set(key, (incomingCount.get(key) || 0) + 1);
      });
      const priorCount = new Map();
      (prevWalls || []).forEach((w2) => {
        (w2?.shape?.segments || []).forEach((s2, i) => {
          const key = segEndpoints(w2?.shape, i);
          if (w2?.component_id === n.component_id && key) priorCount.set(key, (priorCount.get(key) || 0) + 1);
        });
      });
      shape.segments = segs.map((s, i) => {
        const prior = s.component_id;
        if (prior !== undefined && prior !== null) return ensureNodeId(s, createId, "wall_segment", used, seen);
        const key = segEndpoints(shape, i);
        const kept = key && incomingCount.get(key) === 1 && priorCount.get(key) === 1 ? prevSegIds.get(`${n.component_id}|${key}`) : undefined;
        if (kept && !seen.has(kept)) {
          const sn = cloneNode(s);
          sn.component_id = kept;
          seen.add(kept); used.add(kept);
          return sn;
        }
        return ensureNodeId(s, createId, "wall_segment", used, seen);
      });
    }
    n.shape = shape;
    out.push(n);
  }
  return out;
};

const normalizePoles = (poles, items, prevItems, createId, used, seen) =>
  (poles || []).map((p) => {
    const n = ensureNodeId(p, createId, "pole", used, seen);
    const legacy = legacyIndexOf(p, ["foundation_idx"]);
    const res = resolveParent(n.foundation_component_id, Object.prototype.hasOwnProperty.call(p, "foundation_component_id"), legacy, items, prevItems, UNRESOLVED.foundation);
    n.foundation_component_id = res.canon === undefined ? "" : res.canon;
    n.foundation_idx = res.index;
    const signs = p?.signs;
    if (signs !== undefined && !Array.isArray(signs)) throw new Error("foundation assembly: pole signs must be an array");
    if (Array.isArray(signs)) n.signs = signs.map((s) => ensureNodeId(s, createId, "pole_sign", used, seen));
    return n;
  });

const normalizeCaps = (caps, walls, prevWalls, createId, used, seen) =>
  (caps || []).map((c) => {
    const n = ensureNodeId(c, createId, "wall_cap", used, seen);
    const wRes = resolveParent(n.wall_component_id, Object.prototype.hasOwnProperty.call(c, "wall_component_id"), legacyIndexOf(c, ["wall_index"]), walls, prevWalls, UNRESOLVED.wall);
    n.wall_component_id = wRes.canon === undefined ? "" : wRes.canon;
    n.wall_index = wRes.index;
    const wall = (walls || []).find((w) => w?.component_id === n.wall_component_id);
    const segs = wall?.shape?.segments || [];
    const prevSegs = prevWalls ? ((prevWalls.find((w) => w?.component_id === n.wall_component_id)?.shape?.segments) || []) : null;
    const sRes = resolveParent(n.segment_component_id, Object.prototype.hasOwnProperty.call(c, "segment_component_id"), legacyIndexOf(c, ["segment_index"]), segs, prevSegs, UNRESOLVED.segment);
    n.segment_component_id = sRes.canon === undefined ? "" : sRes.canon;
    n.segment_index = sRes.index;
    return n;
  });

const normalizeCabinets = (cabinets, items, poles, prevItems, prevPoles, createId, used, seen) =>
  (cabinets || []).map((c) => {
    const n = ensureNodeId(c, createId, "signage_cabinet", used, seen);
    const mount = c?.mount;
    if (mount === "pole") {
      const res = resolveParent(n.pole_component_id, Object.prototype.hasOwnProperty.call(c, "pole_component_id"), legacyIndexOf(c, ["pole_index"]), poles, prevPoles, UNRESOLVED.pole);
      n.pole_component_id = res.canon === undefined ? "" : res.canon;
      n.pole_index = res.index;
      n.foundation_component_id = n.foundation_component_id ?? "";
      n.foundation_index = undefined;
    } else if (mount === "foundation") {
      const res = resolveParent(n.foundation_component_id, Object.prototype.hasOwnProperty.call(c, "foundation_component_id"), legacyIndexOf(c, ["foundation_index"]), items, prevItems, UNRESOLVED.foundation);
      n.foundation_component_id = res.canon === undefined ? "" : res.canon;
      n.foundation_index = res.index;
      n.pole_component_id = n.pole_component_id ?? "";
      n.pole_index = undefined;
    } else {
      n.mount = mount;
      if (n.foundation_component_id === undefined) n.foundation_component_id = "";
      if (n.pole_component_id === undefined) n.pole_component_id = "";
      n.foundation_index = undefined;
      n.pole_index = undefined;
    }
    return n;
  });

export function normalizeFoundationAssembly(project, { previous = null, createId } = {}) {
  if (typeof createId !== "function") throw new Error("foundation assembly: createId(kind) factory is required");
  if (!isRecord(project)) throw new Error("foundation assembly: project must be a record");
  const ver = project.assembly_schema_version;
  if (ver !== undefined && ver !== 1) throw new Error(`foundation assembly: unsupported assembly_schema_version ${String(ver)}`);
  const used = new Set();
  const seen = new Set();
  for (const k of ARRAYS) {
    if (project[k] !== undefined && !Array.isArray(project[k])) throw new Error(`foundation assembly: ${k} must be an array`);
  }
  reserve(project, previous, used);
  const next = { ...project, assembly_schema_version: 1 };
  next.items = (project.items || []).map((it) => ensureNodeId(it, createId, "item", used, seen));
  next.walls = normalizeWalls(project.walls, previous?.walls, createId, used, seen);
  next.poles = normalizePoles(project.poles, next.items, previous?.items, createId, used, seen);
  next.wall_caps = normalizeCaps(project.wall_caps, next.walls, previous?.walls, createId, used, seen);
  next.signage_cabinets = normalizeCabinets(project.signage_cabinets, next.items, next.poles, previous?.items, previous?.poles, createId, used, seen);
  return { project: next, issues: foundationAssemblyIssues(next) };
}

export function foundationAssemblyIssues(project) {
  const issues = [];
  if (!isRecord(project)) return issues;
  const items = project.items || [];
  const walls = project.walls || [];
  const poles = project.poles || [];
  const byId = (arr, id) => isId(id) && (arr || []).some((p) => p?.component_id === id);
  for (const p of poles) {
    const canon = p?.foundation_component_id;
    if (canon === "" || canon === undefined || canon === null) continue;
    if (isReserved(canon)) issues.push({ code: "unresolved-parent", kind: "pole", componentId: p?.component_id, parentId: canon, message: "Pole legacy foundation index could not be resolved; left unresolved until reassigned." });
    else if (!byId(items, canon)) issues.push({ code: "dangling-parent", kind: "pole", componentId: p?.component_id, parentId: canon, message: "Pole references a foundation that is not present; it stays priced until reassigned." });
  }
  for (const c of project.wall_caps || []) {
    const wId = c?.wall_component_id;
    if (wId === "" || wId === undefined || wId === null) issues.push({ code: "missing-mount", kind: "wall_cap", componentId: c?.component_id, parentId: undefined, message: "Wall cap has no wall assigned; it stays priced until assigned." });
    else if (isReserved(wId)) issues.push({ code: "unresolved-parent", kind: "wall_cap", componentId: c?.component_id, parentId: wId, message: "Wall cap wall could not be resolved; left unresolved until reassigned." });
    else if (!byId(walls, wId)) issues.push({ code: "dangling-parent", kind: "wall_cap", componentId: c?.component_id, parentId: wId, message: "Wall cap references a wall that is not present; it stays priced until reassigned." });
    const wall = walls.find((w) => w?.component_id === wId);
    const segs = wall?.shape?.segments || [];
    const sId = c?.segment_component_id;
    if (sId === "" || sId === undefined || sId === null) { if (wall) issues.push({ code: "missing-mount", kind: "wall_cap", componentId: c?.component_id, parentId: undefined, message: "Wall cap has no wall segment assigned; it stays priced until assigned." }); }
    else if (isReserved(sId)) issues.push({ code: "unresolved-parent", kind: "wall_cap", componentId: c?.component_id, parentId: sId, message: "Wall cap segment could not be resolved; left unresolved until reassigned." });
    else if (!byId(segs, sId)) issues.push({ code: "dangling-parent", kind: "wall_cap", componentId: c?.component_id, parentId: sId, message: "Wall cap references a wall segment that is not present; it stays priced until reassigned." });
  }
  for (const c of project.signage_cabinets || []) {
    if (c?.mount === "pole") {
      const canon = c?.pole_component_id;
      if (canon === "" || canon === undefined || canon === null) issues.push({ code: "missing-mount", kind: "signage_cabinet", componentId: c?.component_id, parentId: undefined, message: "Cabinet has no pole or foundation assigned; it stays priced until assigned." });
      else if (isReserved(canon)) issues.push({ code: "unresolved-parent", kind: "signage_cabinet", componentId: c?.component_id, parentId: canon, message: "Cabinet pole could not be resolved; left unresolved until reassigned." });
      else if (!byId(poles, canon)) issues.push({ code: "dangling-parent", kind: "signage_cabinet", componentId: c?.component_id, parentId: canon, message: "Cabinet references a pole that is not present; it stays priced until reassigned." });
    } else if (c?.mount === "foundation") {
      const canon = c?.foundation_component_id;
      if (canon === "" || canon === undefined || canon === null) issues.push({ code: "missing-mount", kind: "signage_cabinet", componentId: c?.component_id, parentId: undefined, message: "Cabinet has no pole or foundation assigned; it stays priced until assigned." });
      else if (isReserved(canon)) issues.push({ code: "unresolved-parent", kind: "signage_cabinet", componentId: c?.component_id, parentId: canon, message: "Cabinet foundation could not be resolved; left unresolved until reassigned." });
      else if (!byId(items, canon)) issues.push({ code: "dangling-parent", kind: "signage_cabinet", componentId: c?.component_id, parentId: canon, message: "Cabinet references a foundation that is not present; it stays priced until reassigned." });
    } else {
      issues.push({ code: "unsupported-mount", kind: "signage_cabinet", componentId: c?.component_id, parentId: undefined, message: "Cabinet mount is not supported; it stays priced and visible until reassigned." });
    }
  }
  return issues;
}

export function cloneFoundationComponents(project, { createId } = {}) {
  if (typeof createId !== "function") throw new Error("foundation assembly: createId(kind) factory is required");
  if (!isRecord(project)) throw new Error("foundation assembly: project must be a record");
  // Legacy rows can carry a malformed wall outline — a nonarray `shape.segments`
  // value on a stored row. The copy path must not crash on them: detach the
  // field for normalization, then restore the authored value raw on the clone —
  // no id remap is possible on a non-array, so none is attempted.
  const rawWallSegments = new Map();
  const wallsForNormalize = (Array.isArray(project.walls) ? project.walls : []).map((w, i) => {
    if (!isRecord(w) || !isRecord(w.shape)) return w;
    const segs = w.shape.segments;
    if (segs === undefined || Array.isArray(segs)) return w;
    rawWallSegments.set(i, segs);
    const shape = { ...w.shape };
    delete shape.segments;
    return { ...w, shape };
  });
  const { project: normalized } = normalizeFoundationAssembly(
    rawWallSegments.size ? { ...project, walls: wallsForNormalize } : project,
    { createId }
  );
  const used = new Set([...collectIds(normalized), ...collectRefs(normalized)]);
  const idMap = new Map();
  const remap = (oldId, kind) => {
    if (!isId(oldId) || isReserved(oldId)) return oldId;
    if (idMap.has(oldId)) return idMap.get(oldId);
    const id = freshId(createId, kind, used);
    idMap.set(oldId, id);
    return id;
  };
  const components = { assembly_schema_version: 1 };
  const copyRows = (rows, kind) => (rows || []).map((r) => {
    const n = deepClone(r);
    n.component_id = remap(n.component_id, kind);
    return n;
  });
  if (project.items !== undefined) components.items = copyRows(normalized.items, "item");
  if (project.walls !== undefined) {
    components.walls = copyRows(normalized.walls, "wall").map((w, i) => ({
      ...w,
      shape: isRecord(w.shape)
        ? {
            ...w.shape,
            segments: rawWallSegments.has(i)
              ? cloneRawValue(rawWallSegments.get(i))
              : Array.isArray(w.shape.segments)
                ? w.shape.segments.map((s) => ({ ...s, component_id: remap(s.component_id, "wall_segment") }))
                : (w.shape.segments || []),
          }
        : w.shape,
    }));
  }
  if (project.poles !== undefined) {
    components.poles = copyRows(normalized.poles, "pole").map((p) => ({
      ...p,
      foundation_component_id: isId(p.foundation_component_id) && idMap.has(p.foundation_component_id) ? idMap.get(p.foundation_component_id) : p.foundation_component_id,
      signs: (p.signs || []).map((s) => ({ ...s, component_id: remap(s.component_id, "pole_sign") })),
    }));
  }
  if (project.wall_caps !== undefined) {
    components.wall_caps = copyRows(normalized.wall_caps, "wall_cap").map((c) => ({
      ...c,
      wall_component_id: isId(c.wall_component_id) && idMap.has(c.wall_component_id) ? idMap.get(c.wall_component_id) : c.wall_component_id,
      segment_component_id: isId(c.segment_component_id) && idMap.has(c.segment_component_id) ? idMap.get(c.segment_component_id) : c.segment_component_id,
    }));
  }
  if (project.signage_cabinets !== undefined) {
    components.signage_cabinets = copyRows(normalized.signage_cabinets, "signage_cabinet").map((c) => ({
      ...c,
      foundation_component_id: isId(c.foundation_component_id) && idMap.has(c.foundation_component_id) ? idMap.get(c.foundation_component_id) : c.foundation_component_id,
      pole_component_id: isId(c.pole_component_id) && idMap.has(c.pole_component_id) ? idMap.get(c.pole_component_id) : c.pole_component_id,
    }));
  }
  const parents = components.items || [];
  const wallRows = components.walls || [];
  const poleRows = components.poles || [];
  (components.poles || []).forEach((p) => { p.foundation_idx = rebuildIndex(p.foundation_component_id, parents); });
  (components.wall_caps || []).forEach((c) => {
    c.wall_index = rebuildIndex(c.wall_component_id, wallRows);
    const rawSegs = wallRows.find((w) => w?.component_id === c.wall_component_id)?.shape?.segments;
    const segs = Array.isArray(rawSegs) ? rawSegs : [];
    c.segment_index = rebuildIndex(c.segment_component_id, segs);
  });
  (components.signage_cabinets || []).forEach((c) => {
    if (c.mount === "pole") { c.pole_index = rebuildIndex(c.pole_component_id, poleRows); c.foundation_index = undefined; }
    else { c.foundation_index = rebuildIndex(c.foundation_component_id, parents); c.pole_index = undefined; }
  });
  return { components, idMap };
}

import { normalizeFoundationAssembly, cloneFoundationComponents } from "./foundationAssemblyModel.js";
import { ensurePreliminaryNotice } from "./foundationPreliminaryNotice.js";

// Shared allowlist: the page's template-apply fields plus selected_concrete_id
// and notes. Identity, receipt, and creation keys are never carried.
//
// O-007 (CMP-A07) field semantics — a template is a reusable design whose
// snapshot deliberately matches the save-as-copy carry set:
//   * Design assemblies (items/walls/poles/wall_caps/signage_cabinets) and the
//     landscape grid travel verbatim; cloneFoundationComponents mints fresh
//     component_ids (incl. nested wall segments and pole signs) on apply.
//   * The document hyperlink and the persisted AI/beautify brief image
//     (beautify_data_url) are design-associated state and round-trip verbatim.
//     Customer/estimate identity links (client_name, customer_id,
//     estimate_number) are NOT carried — applying a template must never relink
//     the target project to another customer or quote.
//   * Customer pricing SETTINGS round-trip like save-as-copy:
//     customer_markup_percent and customer_price_override verbatim;
//     customer_pricing carries the applied-tier SELECTION only (see
//     sanitizeTemplateCustomerPricing) — never the computed sell snapshot,
//     which is derived from the source design's costs and would display a
//     stale price on a different design. The save path recomputes the
//     snapshot whenever customer_pricing.applied === true.
//   * User-authored rate inputs match the draft-recovery/payload field set so
//     an applied template reproduces the same cost math.
//   * ai_engineering_data carries the review verbatim EXCEPT apply-time
//     provenance stamping (see stampTemplateAppliedAiData): its source_key
//     identifies the design the AI analyzed — the template SOURCE project's
//     design — so on any other project the review surface detects the key
//     mismatch and shows its stale banner. The key is kept (it is the true
//     reference to the analyzed design) and the record gains explicit
//     provenance fields marking the note as template-carried.
//   * notes is client-estimate-adjacent free text; template-authored notes
//     always lead with the canonical O-119 preliminary-engineering sentence
//     (see stampTemplateNotesNotice) on BOTH snapshot and apply.
//   * pricing_engine is excluded: it is external per-project engine context
//     (customer-tier config opt-in), never page-authored, and must not
//     transplant one project's engine settings onto another. Totals,
//     concrete_delivery_snapshot, status, id/updated_date and sync receipts
//     are likewise excluded — they are derived or record-scoped.
export const FOUNDATION_TEMPLATE_FIELDS = [
  "items",
  "walls",
  "poles",
  "wall_caps",
  "signage_cabinets",
  "selected_equipment",
  "project_concrete_type",
  "project_concrete_admixtures",
  "excavation_method",
  "selected_concrete_id",
  "landscape",
  "ai_engineering_recommendation",
  "ai_engineering_data",
  "notes",
  "hyperlink",
  "beautify_data_url",
  "customer_markup_percent",
  "customer_price_override",
  "customer_pricing",
  "concrete_cost_per_cy",
  "rebar_cost_per_ft",
  "forming_materials_cost_spread_foot",
  "forming_materials_cost_pillar",
  "min_excavation_time_hours",
  "hand_dig_excavation_cost_per_cy",
  "equipment_excavation_cost_per_cy",
  "forming_labor_rate",
  "pouring_labor_rate",
  "finishing_labor_rate",
  "hand_dig_labor_rate",
  "equipment_excavation_labor_rate",
];

const ASSEMBLY_ARRAYS = ["items", "walls", "poles", "wall_caps", "signage_cabinets"];

const isRecord = (v) => v !== null && typeof v === "object" && !Array.isArray(v);
const deepClone = (v) => (v === undefined ? v : JSON.parse(JSON.stringify(v)));

const checkTemplateRecord = (data, noun) => {
  if (!isRecord(data)) throw new Error(`Foundation template ${noun} must be a record.`);
  if (data.assembly_schema_version !== undefined && data.assembly_schema_version !== 1) {
    throw new Error("Template uses an unsupported assembly version and was not applied.");
  }
};

// customer_pricing: carry the applied-tier SELECTION, never the computed sell
// snapshot (total/lines/subtotals/tier_name are derived from the source
// design's costs; verbatim carry would display a stale price the moment the
// template is applied to a different design). Records without applied === true
// hold no computed snapshot and travel verbatim; a malformed value fails
// closed. The save path recomputes the snapshot whenever applied === true.
const sanitizeTemplateCustomerPricing = (v) => {
  if (v === undefined) return v;
  if (v === null) return null;
  if (!isRecord(v)) throw new Error("Foundation template customer_pricing must be a record.");
  if (v.applied !== true) return deepClone(v);
  return { applied: true, tier_number: v.tier_number };
};

// ai_engineering_data: the review's source_key identifies the design the AI
// analyzed — the template SOURCE project's design, not the apply target's.
// The carried key can never match the target's live design key (it embeds the
// source project's id/updated_date), so the review surface marks the note
// stale ("Design changed since this note") exactly like a review whose own
// design moved on. source_key stays verbatim — it is the true reference to
// the analyzed design — and the record gains explicit provenance so a
// template-carried note is distinguishable from a review that went stale on
// its own project: origin_source_key preserves the analyzed-design key,
// template_applied flags the carry, template_applied_at records when the note
// was carried onto this project. Non-record values fail closed, same as
// customer_pricing. On chained templates (a project that received a template
// apply is itself saved as a template) the earliest origin_source_key is
// preserved — it still names the design actually reviewed.
const stampTemplateAppliedAiData = (v, { appliedAt } = {}) => {
  if (v === undefined) return v;
  if (v === null) return null;
  if (!isRecord(v)) throw new Error("Foundation template ai_engineering_data must be a record.");
  const out = deepClone(v);
  if (out.origin_source_key === undefined) {
    out.origin_source_key = typeof out.source_key === "string" && out.source_key ? out.source_key : null;
  }
  out.template_applied = true;
  out.template_applied_at =
    typeof appliedAt === "string" && Number.isFinite(Date.parse(appliedAt))
      ? appliedAt
      : new Date().toISOString();
  return out;
};

// notes: a template-authored note leads with the canonical O-119 preliminary
// sentence on BOTH snapshot (the stored template carries it at rest — the
// source project is itself a preliminary concept, so the sentence is true the
// moment it is written, and the dialog row preview stays honest) and apply
// (covers templates stored before this change or authored outside the
// snapshot path). Idempotent — ensurePreliminaryNotice returns an
// already-stamped note unchanged, so save -> apply -> save chains never
// double-stamp. null travels as null (an explicit template clear stays a
// clear); absent stays absent so apply never injects notes onto a target that
// keeps its own. Non-string values fail closed, same as customer_pricing.
const stampTemplateNotesNotice = (v) => {
  if (v === undefined) return v;
  if (v === null) return null;
  if (typeof v !== "string") throw new Error("Foundation template notes must be a string.");
  return ensurePreliminaryNotice(v);
};

// Snapshot the allowed design fields of a project for template storage.
// Validates supplied assembly arrays; preserves values verbatim otherwise.
export function createFoundationTemplateSnapshot(project, { createId } = {}) {
  checkTemplateRecord(project, "source");
  const out = { assembly_schema_version: 1 };
  for (const k of FOUNDATION_TEMPLATE_FIELDS) {
    if (project[k] !== undefined) out[k] = deepClone(project[k]);
  }
  if (out.customer_pricing !== undefined) {
    out.customer_pricing = sanitizeTemplateCustomerPricing(out.customer_pricing);
  }
  if (out.notes !== undefined) {
    out.notes = stampTemplateNotesNotice(out.notes);
  }
  const supplied = {};
  let hasAssembly = false;
  for (const k of ASSEMBLY_ARRAYS) {
    if (out[k] !== undefined) {
      supplied[k] = out[k];
      hasAssembly = true;
    }
  }
  if (hasAssembly) {
    let n = 0;
    const f = typeof createId === "function" ? createId : (kind) => `tmpl_${kind}_${n++}`;
    normalizeFoundationAssembly(supplied, { createId: f });
  }
  return out;
}

// Build the commit patch for applying a stored template: only supplied
// assembly arrays are cloned with fresh IDs; omitted keys are absent so the
// target's existing fields are preserved.
export function prepareFoundationTemplatePatch(data, { createId, appliedAt } = {}) {
  checkTemplateRecord(data, "data");
  if (typeof createId !== "function") throw new Error("Foundation template apply requires a createId factory.");
  const provided = {};
  for (const k of FOUNDATION_TEMPLATE_FIELDS) {
    if (data[k] !== undefined) provided[k] = deepClone(data[k]);
  }
  // Apply-time sanitization is the fail-closed gate: it also covers templates
  // stored before this normalization or authored outside the snapshot path.
  if (provided.customer_pricing !== undefined) {
    provided.customer_pricing = sanitizeTemplateCustomerPricing(provided.customer_pricing);
  }
  if (provided.ai_engineering_data !== undefined) {
    provided.ai_engineering_data = stampTemplateAppliedAiData(provided.ai_engineering_data, { appliedAt });
  }
  if (provided.notes !== undefined) {
    provided.notes = stampTemplateNotesNotice(provided.notes);
  }
  const arrays = {};
  for (const k of ASSEMBLY_ARRAYS) if (provided[k] !== undefined) arrays[k] = provided[k];
  const cloned = Object.keys(arrays).length
    ? cloneFoundationComponents(arrays, { createId }).components
    : {};
  return { ...provided, ...cloned };
}

import { deleteEntityIfUnchanged } from "@/components/estimator/builder/builderEntityPersistence";

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

// Read-after-write grace for the post-create verify read: a create whose
// response was lost can still have landed, and an immediate empty verify
// read is not conclusive.
const VERIFY_RETRY_DELAY_MS = 700;

const canonicalRecord = (rows = []) => [...rows].sort((a, b) => {
  const aStamp = String(a?.created_date || "");
  const bStamp = String(b?.created_date || "");
  if (aStamp !== bStamp) return aStamp.localeCompare(bStamp);
  return String(a?.id || "").localeCompare(String(b?.id || ""));
})[0] || null;

function normalize(value) {
  if (Array.isArray(value)) return value.map(normalize);
  if (!value || typeof value !== "object") return value;
  return Object.keys(value).sort().reduce((out, key) => {
    out[key] = normalize(value[key]);
    return out;
  }, {});
}

function sameValue(a, b) {
  const emptyA = a === undefined || a === null || a === "";
  const emptyB = b === undefined || b === null || b === "";
  if (emptyA && emptyB) return true;
  if (!emptyA && !emptyB && Number.isFinite(Number(a)) && Number.isFinite(Number(b))) {
    return Math.abs(Number(a) - Number(b)) <= 0.000001;
  }
  // Trimmed server values must match the retry payload — backend `clean()`
  // trims most string fields on write, so a strict compare would false-negative
  // a legitimately-reused record and 409 "retry key belongs to different data".
  if (typeof a === "string" && typeof b === "string") return a.trim() === b.trim();
  return JSON.stringify(normalize(a)) === JSON.stringify(normalize(b));
}

function matchesPayload(row, payload) {
  return !!row && Object.entries(payload || {}).every(([field, value]) => sameValue(row[field], value));
}

export function newCreationRequestKey(prefix = "create") {
  const token = globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  return `${String(prefix || "create").trim()}:${token}`;
}

export async function ensureIdempotentEntityCreate({
  entity,
  keyField = "idempotency_key",
  key,
  data,
  label = "Record",
} = {}) {
  const cleanField = String(keyField || "").trim();
  const cleanKey = String(key || "").trim();
  if (!entity?.filter || !entity?.create || !cleanField || !cleanKey) {
    throw new Error(`${label} could not initialize its retry-safe create.`);
  }

  const payload = { ...data, [cleanField]: cleanKey };
  const load = async () => {
    const rows = await entity.filter({ [cleanField]: cleanKey });
    if (!Array.isArray(rows)) throw new Error(`${label} retry state could not be verified.`);
    return rows.filter((row) => String(row?.[cleanField] || "").trim() === cleanKey);
  };

  const existing = await load();
  if (existing.length > 1) {
    throw new Error(`${label} already has multiple records with this retry key. No row was deleted; reload and review the duplicates before continuing.`);
  }
  if (existing.length === 1) {
    if (!matchesPayload(existing[0], payload)) {
      throw new Error(`${label} retry key already belongs to a record with different data. No row was changed.`);
    }
    return existing[0];
  }

  let created = null;
  let createError = null;
  try {
    created = await entity.create(payload);
  } catch (error) {
    createError = error;
  }

  let afterCreate = null;
  let verifyError = null;
  try {
    afterCreate = await load();
  } catch (error) {
    verifyError = error;
  }
  // Read-after-write lag: a create that failed at the response layer can
  // still have landed, so an immediate empty/failed verify is not conclusive.
  // Give the write a moment and re-read once before declaring the outcome
  // unknown — a retry must resolve the existing row, never create a dup.
  if ((!Array.isArray(afterCreate) || afterCreate.length === 0) && (createError || !created?.id)) {
    await sleep(VERIFY_RETRY_DELAY_MS);
    try {
      const retryRows = await load();
      if (Array.isArray(retryRows)) afterCreate = retryRows;
    } catch (error) {
      verifyError = verifyError || error;
    }
  }
  if (!Array.isArray(afterCreate)) {
    if (created?.id && matchesPayload(created, payload)) return created;
    throw new Error(`${label} create outcome could not be verified. Do not retry blindly; reload first. ${verifyError?.message || "Recovery lookup failed."}`);
  }

  if (afterCreate.length === 1) {
    // Our create returned an id but the only visible same-key row is a
    // different record — a concurrent create landed too and ours is still
    // indexing. Fail closed instead of silently orphaning our row as a dup.
    if (created?.id && String(afterCreate[0].id) !== String(created.id)) {
      throw new Error(`${label} was created concurrently more than once. No uncertain duplicate was deleted; reload and review records with this retry key.`);
    }
    if (!matchesPayload(afterCreate[0], payload)) {
      throw new Error(`${label} retry key exists but its live data does not match this create. No row was changed or deleted.`);
    }
    return afterCreate[0];
  }

  if (afterCreate.length > 1) {
    const keep = canonicalRecord(afterCreate);
    const ours = created?.id ? afterCreate.find((row) => row.id === created.id) : null;
    if (ours && ours.id !== keep?.id && matchesPayload(ours, payload)) {
      await deleteEntityIfUnchanged({
        entity,
        record: ours,
        guardFields: { [cleanField]: cleanKey },
        label: `${label} losing retry duplicate`,
      });
      const finalRows = await load();
      if (finalRows.length === 1 && finalRows[0]?.id === keep?.id && matchesPayload(finalRows[0], payload)) {
        return finalRows[0];
      }
    }
    throw new Error(`${label} was created concurrently more than once. No uncertain duplicate was deleted; reload and review records with this retry key.`);
  }

  if (created?.id && matchesPayload(created, payload)) return created;
  if (createError) {
    throw new Error(`${label} create failed and no matching record was visible on recovery read. Do not retry blindly; reload first. ${createError?.message || ""}`.trim());
  }
  throw new Error(`${label} create response could not be verified. Do not retry blindly; reload first.`);
}

import { staffEntities } from "@/components/staff/staffEntities";
import { ensureIdempotentEntityCreate, newCreationRequestKey } from "@/components/estimator/idempotentEntityCreate";
import { ensurePreliminaryNotice } from "./foundationPreliminaryNotice.js";

// Convert a Foundation project into a Brick & Stone draft (#77). Carries the
// shared identity fields; geometry/materials stay at module defaults for
// recalc, and the Foundation source is never modified. The optional
// attemptRef holds a signature-stable creation_request_key so a double-click
// or a lost response reuses the same draft instead of creating duplicates.
export async function convertFoundationToBrickStone({ project, attemptRef } = {}) {
  if (!project?.id) throw new Error("Save the Foundation project before converting.");
  const sourceName = String(project.project_name || "Foundation").trim();
  const payload = {
    project_name: `${sourceName} (Brick & Stone)`,
    client_name: String(project.client_name || "").trim(),
    customer_id: String(project.customer_id || "").trim() || undefined,
    estimate_number: String(project.estimate_number || "").trim() || undefined,
    hyperlink: String(project.hyperlink || "").trim() || undefined,
    status: "draft",
    notes: ensurePreliminaryNotice(`Converted from Foundation project "${sourceName}" (${project.id}). Re-enter masonry dimensions to calculate.`),
  };
  const signature = JSON.stringify(payload);
  if (attemptRef && attemptRef.current?.signature !== signature) {
    attemptRef.current = { signature, key: newCreationRequestKey("foundation_to_brick_stone") };
  }
  const key = attemptRef?.current?.key || newCreationRequestKey("foundation_to_brick_stone");
  const created = await ensureIdempotentEntityCreate({
    entity: staffEntities.BrickStoneProject,
    keyField: "creation_request_key",
    key,
    data: payload,
    label: "Brick & Stone draft",
  });
  if (!created?.id) throw new Error("Brick & Stone draft could not be verified.");
  return created;
}

import { ensureIdempotentEntityCreate, newCreationRequestKey } from "@/components/estimator/idempotentEntityCreate";
import { getSessionToken } from "@/components/auth/EmailGate";
import { invokePortal } from "@/components/portal/PortalPanel";

// Fields that must never be cloned into a new project row — identity and
// server-managed values. The copy keeps every editable payload field while a
// fresh identity and a fresh creation_request_key make it a real new record.
const STRIP_ON_COPY = new Set([
  "id",
  "created_date",
  "updated_date",
  "created_by",
  "created_by_id",
  "is_sample",
  "creation_request_key",
  "idempotency_key",
]);

// Clone a module's save payload into a brand-new project record (#78). The
// caller passes its normal persisted payload; we strip identity/system fields,
// force "(Copy)" onto the name, and create through the same
// signature-stable retry-key + ensureIdempotentEntityCreate flow Foundation
// uses so a double-click or lost response can never produce duplicate copies.
export async function saveModuleProjectCopy({
  entity,
  payload,
  attemptRef,
  keyPrefix,
  nameField = "project_name",
  baseName,
  extraData = {},
  label = "Project copy",
}) {
  const copyData = { ...payload };
  for (const key of STRIP_ON_COPY) delete copyData[key];
  copyData[nameField] = `${baseName || copyData[nameField] || "Estimate"} (Copy)`;
  Object.assign(copyData, extraData);

  const signature = JSON.stringify(copyData);
  if (attemptRef.current.signature !== signature) {
    attemptRef.current = {
      signature,
      key: newCreationRequestKey(keyPrefix),
    };
  }

  const copy = await ensureIdempotentEntityCreate({
    entity,
    keyField: "creation_request_key",
    key: attemptRef.current.key,
    data: copyData,
    label,
  });
  if (!copy?.id) throw new Error(`${label} could not be verified.`);
  return copy;
}

// Create (or reuse) a read-only staff_view portal link for an estimate and
// return its absolute URL (#88). The link is view-only end-to-end: the portal
// bootstrap closes every non-'customer' mutation on that kind server-side.
export async function createEstimateReadOnlyShareLink({ estimateId, label } = {}) {
  const id = String(estimateId || "").trim();
  if (!id) throw new Error("An estimate id is required to share a read-only link.");
  const sessionToken = getSessionToken();
  if (!sessionToken) throw new Error("Sign-in required.");
  const data = await invokePortal(sessionToken, {
    action: "create_link",
    kind: "staff_view",
    estimate_id: id,
    label,
    creation_request_key: crypto.randomUUID(),
  });
  const token = data?.token || data?.link?.token;
  if (!token) throw new Error("The share link could not be verified.");
  return `${window.location.origin}/customerportal?token=${encodeURIComponent(token)}`;
}
